t.guides["forever/alliance/02-westfall"] = (function() return {
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}. {object:1166} stands in the farmhouse at the {area:219}, among them: {npc:1646}' compass is inside.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Погромщики и мошенники из Братства Справедливости занимают фермы к западу (ориентир: {area:108}), между прибрежной дорогой и поселением {area:20}. Среди них, в доме на ферме ({area:219}), стоит {object:1166}: внутри компас, который ищет {npc:1646}.\nОсторожно: в пещере ({area:113}) много членов Братства стоят плотно, там легко выманить сразу нескольких.",
		["Defias Trappers and Smugglers"] = "Ловчие и контрабандисты из Братства Справедливости",
		["East along the road past {area:18}: {npc:248242} and {npc:248248} stand at the foot of the tower."] = "На восток по дороге мимо {area:18}: {npc:248242} и {npc:248248} стоят у подножия башни.",
		["Every Defias on this loop can drop a {item:829}: the Trappers and Smugglers, and the guards at {object:290}."] = "С любого члена Братства Справедливости на этом круге может выпасть {item:829}: с ловчих и контрабандистов, а также со стражей у {object:290}.",
		["Fill the vial at the farm's well"] = "Наполните склянку у колодца фермы",
		["Fill the vial at the well"] = "Наполните склянку у колодца",
		["Finish the Goretusk Livers"] = "Доберите печень жутевепря",
		["Finish the {item:729}"] = "Доберите: {item:729}",
		["Finish the {quest:153}"] = "Завершите: {quest:153}",
		["Fleshrippers circle the fields along this loop: kill the ones you pass for the stew's meat."] = "Над полями вдоль этого круга кружат шкуродеры: убивайте встречных ради мяса для рагу.",
		["Follow the hills south to the tower."] = "Идите по холмам на юг к башне.",
		["For {npc:266} in {area:69}, Redridge"] = "Для NPC {npc:266} ({area:69}, Красногорье)",
		["Goretusk Livers as you go"] = "Печень жутевепря по пути",
		["Goretusk Snouts"] = "Рыла жутевепря",
		["Goretusks and Young Goretusks root along every leg of this loop: kill the ones you pass for the pie's livers."] = "Жутевепри и молодые жутевепри роются на каждом отрезке этого круга: убивайте встречных ради печени для пирога.",
		["Harvest Watchers"] = "Дозорные полей",
		["Harvest Watchers north of {area:107}"] = "Дозорные полей к северу от места {area:107}",
		["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Отправляйтесь в {zone:1453}. Там нет учителя шаманов: от {object:28027} сядьте на {area:2257} до {zone:1455}, обучитесь у {npc:258098}, затем вернитесь на трамвае к кораблю.",
		["In through the main gate (already done if you are in the city)"] = "Войдите через главные ворота (уже сделано, если вы в городе)",
		["It lies by the river north-west of the logging camp."] = "Оно лежит у реки к северо-западу от лесозаготовок.",
		["Level 12, 14 and 16 spells"] = "Заклинания 12, 14 и 16-го уровней",
		["Longshore Murloc Gills"] = "Жабры мурлока с Бескрайнего берега",
		["Murloc Coastrunners and Raiders line the north coast from above the mine east toward the {area:916}: work along the beach eastward. They flee at low health: pull one at a time."] = "Мурлоки-береговики и мурлоки-налетчики занимают северное побережье от места над рудником на восток до {area:916}: двигайтесь по пляжу на восток. При низком здоровье они убегают: выманивайте по одному.",
		["North-west from {area:108} toward {area:918}: Defias Trappers and Smugglers camp in the fields between them."] = "На северо-запад от {area:108} к {area:918}: ловчие и контрабандисты из Братства Справедливости стоят лагерем в полях между ними.",
		["On the way south from the {area:916} to {area:107}: Harvest Watchers (level 14-15) and Golems work the fields west of the road; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks these fields: leave it alone."] = "По пути на юг от места {area:916} к месту {area:107}: Дозорные полей (14-15 уровень) и големы работают на полях к западу от дороги; с них падают изопружины, гиростабилизаторы, {item:732} и иногда {item:255155}. По этим полям ходит {npc:573}, редкий противник 20 уровня: не трогайте его.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Только если вы добыли в Элвиннском лесу предмет {item:1972}: щелкните по нему правой кнопкой",
		["Red Linen Bandanas"] = "Красные льняные банданы",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Гноллы из стаи Речной Лапы стоят лагерем на холмах к западу (ориентир: {area:86}); {quest:91725} лежат в их лагерях.",
		["Sacks of Oats in the fields around the farm"] = "Мешки овса на полях вокруг фермы",
		["Shaman training"] = "Обучение шамана",
		["South along the road, past the fork. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way."] = "На юг вдоль дороги, мимо развилки. {npc:233} стоит снаружи, {npc:235} — в доме, {npc:253395} — в амбаре к западу. Молодые жутевепри и шкуродёры бродят по полям вокруг фермы: по пути начните собирать печень и мясо для похлёбки.",
		["Still short of eight? Young Goretusks root in the fields just west of {area:107}."] = "Не хватает до восьми? Молодые жутевепри роются в полях сразу к западу от {area:107}.",
		["Still short of fifteen? Defias Trappers camp in the fields just west of {area:108}."] = "Не хватает до пятнадцати? Ловчие из Братства Справедливости стоят лагерем в полях сразу к западу от {area:108}.",
		["Still short of three? Young Fleshrippers circle the fields north-west of {area:107}."] = "Не хватает до трех? Молодые шкуродеры кружат над полями к северо-западу от {area:107}.",
		["The bridge"] = "Мост",
		["The gnoll camps"] = "Лагеря гноллов",
		["The {area:2} murlocs"] = "Мурлоки ({area:2})",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters), the Park (Druids)."] = "Учителя: {object:2100} (воины, разбойники), собор (паладины, жрецы), {object:2101} (маги, чернокнижники), {object:28027} (охотники), парк (друиды).",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); у оружия ближнего боя охотника важнее всего характеристики, а у двуручного их больше всего.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Раз уж вы здесь: изучите навык {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием паладин качается быстрее всего.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["Young Goretusks root in the fields along the road south from Saldean's to {area:108}: take their snouts on the way."] = "Молодые жутевепри роются в полях вдоль дороги на юг от фермы Сальденов до {area:108}: по пути собирайте их рыла.",
		["{area:108}'s tower and {npc:523}"] = "Башня на {area:108} и {npc:523}",
		["{area:20}: kill these as you meet them"] = "{area:20}: убивайте этих по пути",
		["{area:918}'s well"] = "Колодец ({area:918})",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} для задания «Сбор лекарственных ингредиентов» (6123), {zone:1439}: {npc:1313}, товары для алхимиков; травники вместо этого собирают его там сами",
		["{item:2998}, from {object:1166}"] = "{item:2998} – из объекта {object:1166}",
		["{item:6529}, from {npc:5494}"] = "{item:6529}: продает {npc:5494}",
		["{item:729} as you go"] = "{item:729} по пути",
		["{item:729}: Fleshrippers"] = "{item:729}: шкуродеры",
		["{item:814}: keep five for {npc:392} at the {area:115}, later on the route"] = "{item:814}: оставьте пять для NPC {npc:392} ({area:115}), позже по маршруту",
		["{npc:1323}, {object:2156} in {object:2100}"] = "{npc:1323}, лавка «{object:2156}» в районе {object:2100}",
		["{npc:1416}: his package for {npc:1343} in {zone:1432}, later on the route"] = "{npc:1416}: его посылка для {npc:1343} (зона {zone:1432}), позже по маршруту",
		["{npc:234} and {npc:821} stand at the top of the stone tower, {npc:491} inside it, {npc:523} the gryphon master on the south side of the hill with {npc:878} beside him. {npc:523} gives you Lewis' note for {npc:1323} with a free flight to {zone:1453}: take it now. In {zone:1453}, {npc:279}'s shop is in the {object:2096} by the gryphons, {npc:1323}'s shop, {object:2156}, in {object:2100}; {npc:1646} stands in {object:2098} on the way back to {npc:352}, the gryphon master."] = "{npc:234} и {npc:821} стоят на вершине каменной башни, {npc:491} – внутри нее, {npc:523}, распорядитель грифонов, – на южной стороне холма, рядом с ним {npc:878}. {npc:523} отдает вам записку Льюиса для NPC {npc:1323} и бесплатный полет в {zone:1453}: летите сейчас. В {zone:1453} лавка NPC {npc:279} находится в районе {object:2096} у грифонов, лавка NPC {npc:1323} – «{object:2156}» – в районе {object:2100}; {npc:1646} стоит на площади {object:2098}, по пути обратно к NPC {npc:352}, распорядителю грифонов.",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} и {npc:821} стоят на вершине каменной башни. {npc:491} – в башне; {npc:878} – на южном склоне холма, рядом с таверной и укротителем грифонов (это {npc:523}).",
		["{npc:235}, inside"] = "{npc:235} – внутри",
		["{npc:237}: Humans may have it already from {npc:963} in Elwynn"] = "{npc:237}: у людей это задание может уже быть – от {npc:963} в Элвинне",
		["{npc:240}: for {npc:234} at {area:108}"] = "{npc:240}: для {npc:234} на {area:108}",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092} – рядом с NPC {npc:878}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it. His tools and Thomas's Prowlers and bears are south of the bridge, on the way back."] = "{npc:261} охраняет мост на дороге на восток; {npc:248265} стоит сразу за ним. Его инструменты, а также бродяги и медведи для Томаса – к югу от моста, по пути обратно.",
		["{npc:278}, inside"] = "{npc:278}, внутри",
		["{npc:279}, {object:2096}, by the gryphons"] = "{npc:279}, {object:2096}, у грифонов",
		["{npc:352}, the gryphon master"] = "{npc:352}, распорядитель грифонов",
		["{npc:491}, inside"] = "{npc:491} – внутри",
		["{npc:491}, inside: back from {zone:1453}"] = "{npc:491}, внутри: по возвращении из {zone:1453}",
		["{npc:523}, on the south side of the hill"] = "{npc:523}, на южной стороне холма",
		["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523}: бесплатный полет, который он предлагает, ведет в {zone:1453}",
		["{npc:5480} trains warriors in {object:2100}, near {npc:1323}'s shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, рядом с лавкой NPC {npc:1323}; трамвай из города {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят там вместе рядом с заведением {object:2152}. {npc:6090} дерется с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите прямо к NPC {npc:6089}: он дает {quest:1639} и без него.",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} продает рыболовные принадлежности у канала, чуть западнее (ориентир: {object:2096}); {npc:267118} рыбачит в гавани, по пути к кораблю.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, Святилище волшебника: {quest:1861}",
		["{npc:5676}: use the {item:6928} at the circle"] = "{npc:5676}: используйте {item:6928} у круга",
		["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171} и {npc:6173} – в Соборе Света; {npc:6174} стоит здесь: {object:2096}; она просит десять шт. {item:2589} (падает с гуманоидов; продается на аукционе).",
		["{npc:6172}, by {area:86} in Elwynn, on the road to Redridge"] = "{npc:6172} – у {area:86} в Элвиннском лесу, на дороге в Красногорье",
		["{npc:7232}, {object:28027}: for his brother in {area:442}"] = "{npc:7232}, {object:28027}: для его брата в {area:442}",
		["{npc:878}, beside {npc:523}"] = "{npc:878}, рядом с {npc:523}",
		["{object:290} stands in the ruined house east of the mine, on the way to the {area:916}.\nCareful: Two Defias stand guard inside, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "{object:290} стоит в разрушенном доме к востоку от рудника, по пути к {area:916}.\nОсторожно: внутри на страже двое членов Братства, один из них — именной противник 15 уровня {npc:502}. Они связаны: нападение на одного привлекает обоих.",
		["{object:290}; inside"] = "{object:290}; внутри",
		["{quest:153} as you go"] = "{quest:153} по пути",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["After using the {item:12347}, kill Xabraxxis, then click his Demon Bag on the ground to collect the talisman. If Xabraxxis despawns before you get it, retake the quest for a new bowl."] = "Использовав {item:12347}, убейте Ксабраксиса, затем щелкните по его сумке демона на земле, чтобы забрать талисман. Если Ксабраксис исчезнет раньше, возьмите задание заново, чтобы получить новую чашу.",
		["Back north-east into the mountains to the crystal."] = "Назад на северо-восток, в горы, к кристаллу.",
		["Bears and the Blackwood camp"] = "Медведи и лагерь Чернолесья",
		["Blackwood furbolgs"] = "Фурболги Чернолесья",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Поднимитесь в горы к востоку (ориентир: {area:447}); {object:175524} лежит на уступе.",
		["Crawler Legs"] = "Ножки краба",
		["Fill the tube at the moonwell in the village"] = "Наполните пробирку у лунного колодца в деревне",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Идите вдоль холмов на север к реке ({area:456}) и вверх к водопаду. Еще два выброшенных на берег останка лежат на северном побережье: у руин ({area:443}) и к северу от руин ({quest:954}).",
		["Grell Earrings"] = "Серьги грелля",
		["Highborne Relics"] = "Реликвии высокорожденных",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Убивайте бешеных колючешерстных медведей на холмах к востоку (ориентир: {area:442}), затем поднимитесь к лагерю фурболгов к юго-востоку от них: убивать там пока никого не нужно.",
		["Moonstalker Fangs"] = "Клыки лунопарда",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Лунопарды рыщут по холмам между руинами ({quest:954}) и башней. {quest:1002} стоит на холме к западу от башни.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "На север вдоль холмов. {npc:3650} ждет в руинах ({quest:954}); там полно диких греллей и коварных греллей, на восточном краю – сатиры из племени Дет'рилл. {quest:1001} стоит у дороги к западу от руин; по пути к нему на берегу лежит существо ({quest:4723}).",
		["Plagued bears"] = "Больные медведи",
		["Read the {object:17188}"] = "Прочитайте: {object:17188}",
		["Read the {object:17189}"] = "Прочитайте: {object:17189}",
		["The WANTED poster outside the inn"] = "Плакат «РАЗЫСКИВАЕТСЯ» у таверны",
		["The bay wrecks"] = "Затонувшие корабли в заливе",
		["The beach"] = "Пляж",
		["The cave and the {npc:6788}"] = "Пещера и {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls."] = "Пещера – к югу от водопада: ножки струпника растут по всей пещере, {item:5270} – в самой глубине. {npc:6788} живет в холмах к югу от водопада.",
		["The flame burns in the south of {area:447}."] = "Пламя горит в южной части руин ({area:447}).",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "Половинки подвески находятся здесь: {zone:1439} и {zone:1436} – дальше по маршруту",
		["The red crystal"] = "Красный кристалл",
		["The skeletal turtle"] = "Скелет черепахи",
		["The {object:16393}"] = "{object:16393}",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Прибрежные крабы снуют по берегу под деревней; {quest:983} стоит на пляже чуть южнее пристани. На мелководье плавают крепкозубы Темного берега. {object:175207} лежит на берегу чуть южнее деревни.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "На дне залива к северу (ориентир: {area:442}) лежат два затонувших корабля; в каждом – сундучок. На этом берегу полно рифовых крабов и покрытых илом крабов.\nОсторожно: мурлоки внутри кораблей стоят близко друг к другу и быстро двигаются. Они часто проплывают сквозь стены и пробоины в корпусе, так что обычно вы будете привлекать лишних мурлоков.",
		["{item:12237} from {npc:2233} and {npc:2235}, by this stop"] = "{item:12237}: с существ {npc:2233} и {npc:2235} рядом с этой точкой",
		["{item:12238}: fish from the pier"] = "{item:12238}: ловите с пристани",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289} – на пляже к западу от пристани; под водой",
		["{item:12349}, at the waterfall"] = "{item:12349} – у водопада",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: у входа в пещеру у водопада",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}: из объекта {object:177785} в озере",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: сатиры из племени Дет'рилл",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: фанатики из клана Темной Нити",
		["{npc:10216}, on the pier"] = "{npc:10216} – на пристани",
		["{npc:3644}, on the pier"] = "{npc:3644} – на пристани",
		["{npc:3649}, north end of the village"] = "{npc:3649} – в северной части деревни",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: для персонажа {npc:1646} ({zone:1453})",
		["{npc:3666}, upstairs in the inn"] = "{npc:3666} – на втором этаже таверны",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: наполните пробоотборник здесь: {area:445}",
} end)()
t.guides["forever/alliance/03-darkshore-return"] = (function() return {
		["Back south"] = "Назад на юг",
		["Back to {npc:11802}"] = "Назад к {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Назад: {npc:11802} ({area:2361}), затем {npc:11800} там же отправит друидов прямо сюда: {area:702}. {npc:11802} стоит на верхнем этаже своего здания: поднимитесь внутри, стрелка не различает этажи.",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Выведите ее из глефы; задание сдается Тересиль ({zone:1440})",
		["Fine Moonstalker Pelts"] = "Прекрасные шкуры лунопарда",
		["Follow the road north."] = "Идите по дороге на север.",
		["From the dock (or the inn, if you used your Hearthstone), up to the north end of the village first ({npc:3649}, {npc:3702} by the moonwell, {npc:2913}), then down the main street: the WANTED poster outside the inn, {npc:3693} at its east end, where the road leaves south. {npc:3694} ({quest:990}) is beside {npc:3693} only for a few minutes at a time: she comes shortly after someone hands in {npc:3692}'s escort and leaves again about 5 minutes later. If she isn't there, don't wait: the guide offers her quest again when you hand in {npc:3692}'s escort to {npc:3693} yourself. Changing layer can also find her."] = "От причала (или от таверны, если вы использовали Камень возвращения) сначала в северную часть деревни ({npc:3649}, {npc:3702} у лунного колодца, {npc:2913}), затем вниз по главной улице: плакат «Разыскивается» у таверны, {npc:3693} в восточном конце улицы, где дорога уходит на юг. {npc:3694} ({quest:990}) стоит рядом с NPC {npc:3693} лишь несколько минут: она приходит вскоре после того, как кто-то сдаст сопровождение NPC {npc:3692}, и уходит примерно через 5 минут. Если ее нет, не ждите: гайд снова предложит ее задание, когда вы сами сдадите сопровождение NPC {npc:3692} персонажу {npc:3693}. Также найти ее может помочь смена слоя.",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Седые колючешерстные медведи бродят по холмам вокруг Рощи; {quest:1003} стоит к западу от нее, среди них.",
		["Moonstalker Sires prowl the woods around the glaive. The {object:12666} sits at the bottom of the crater; {npc:3584} stands on its north side. For {quest:948}'s quest, use the {item:5251} at the bottom of the crater: it makes the {object:10076}, and you hand the quest in to the bowl."] = "Взрослые лунопарды рыщут в лесу вокруг глефы. {object:12666} – на дне кратера; {npc:3584} стоит на его северной стороне. Для задания {quest:948} примените {item:5251} на дне кратера: так появится {object:10076}, и задание сдается чаше.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Только если с послушника или лиходея упал предмет {item:5352}: щелкните по нему правой кнопкой",
		["She gives you the {item:15826}"] = "Она дает вам предмет {item:15826}",
		["The WANTED poster"] = "Плакат «РАЗЫСКИВАЕТСЯ»",
		["The relics of the Barrow Dens"] = "Реликвии Келий Малфуриона",
		["The {area:443}"] = "{area:443}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["Underwater"] = "Под водой",
		["{item:15851} and {item:2449}"] = "{item:15851} и {item:2449}",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: {object:177792} под водой у северного побережья, к западу от руин",
		["{item:15885}: join the halves at the {area:2362}"] = "{item:15885}: соедините половинки здесь: {area:2362}",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: послушники и лиходеи из культа Сумеречного Молота",
		["{npc:10323}'s beach"] = "Пляж: {npc:10323}",
		["{npc:11802}: the welcome from {npc:5504}"] = "{npc:11802}: приветствие от NPC {npc:5504}",
		["{npc:11802}: {quest:5061}, for {npc:4217}"] = "{npc:11802}: {quest:5061}, для NPC {npc:4217}",
		["{npc:3694}, beside {npc:3693} if she is there: for {npc:3691} in {area:415}, in the next guide"] = "{npc:3694} рядом с NPC {npc:3693}, если она там: для NPC {npc:3691} в {area:415}, в следующем гайде",
		["{npc:3694}, once she comes: {quest:990}, for {npc:3691} in {area:415} on your next {zone:1440} visit"] = "{npc:3694}, когда придет: {quest:990}, для NPC {npc:3691} в {area:415} при следующем визите в зону {zone:1440}",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} прячется на островке у руин. Части ключа падают с гигантских лесных долгоногов (верх), мурлоков из племени Серой Мглы (середина) и гневных рифовых крабов (низ).",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} дает это задание, когда сданы все девять выброшенных на берег останков",
} end)()
t.guides["forever/alliance/03-loch-modan"] = (function() return {
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Cathedral of Light"] = "Собор Света",
		["Class trainer"] = "Учитель классовых навыков",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "По поселению {area:20} ходят налетчики и кастетники из Братства Справедливости; проходимцы (17-й уровень) патрулируют парами холмы к югу и востоку от него: выманивайте их поодиночке. Вход в {area:1581} в кузнице ведет в групповое подземелье.\nОсторожно: в лагерях на холмах стоят смешанные группы Братства, при низком уровне легко выманить нескольких сразу.",
		["Druids on Trial of the Sea Lion: from the {area:113}, west to the shore and north along it. The {object:177790} lies on the sea floor off the coast (about 18,33); then back south along the coast to the lighthouse."] = "Друидам на Испытании Морского Льва: от места {area:113} на запад к берегу и вдоль него на север. {object:177790} лежит на морском дне у побережья (примерно 18,33); затем назад на юг вдоль побережья к маяку.",
		["Elder Mountain Boars"] = "Старые горные вепри",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Sell and repair in {area:442} first: the next stretch is a long one."] = "Сначала продайте добычу и почините снаряжение ({area:442}): дальше долгий путь.",
		["Train on the way to the harbour: {object:2100} (Warriors, Rogues), the Cathedral of Light (Paladins, Priests), the {object:2101} (Mages, Warlocks), the {object:28027} (Hunters)."] = "Обучитесь по пути в гавань: {object:2100} (воины, разбойники), Собор Света (паладины, жрецы), {object:2101} (маги, чернокнижники), {object:28027} (охотники).",
		["Use the {item:6866} on {npc:6172}"] = "Используйте {item:6866}. Цель: {npc:6172}",
		["{area:144} flight master"] = "Распорядитель полетов: {area:144}",
		["{area:20} and the Defias hills"] = "{area:20} и холмы Братства Справедливости",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}: из ящиков вокруг поселения {area:20}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: твердозубы из стаи Красногорья",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: волшебники-плуты из Братства Справедливости",
		["{npc:1092} is inside the bunker at the tunnel post: go in by its door on the south-east side."] = "{npc:1092} – внутри бункера у поста у туннеля: входите через дверь с юго-восточной стороны.",
		["{npc:1092}, inside"] = "{npc:1092}, внутри",
		["{npc:1343}: {npc:1416}'s package"] = "{npc:1343}: посылка от {npc:1416}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: письмо Тандриса из места {area:442}",
		["{npc:344}, in the town hall"] = "{npc:344}, в ратуше",
		["{npc:6171}: Redemption"] = "{npc:6171}: Искупление",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "Обратно: {area:69}",
		["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "Летите сюда: {area:108}. Идите на северо-запад к побережью: {object:177790} лежит на морском дне недалеко от берега. Затем идите на восток по дороге через Элвиннский лес.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "Идите по дороге вдоль южного берега озера ({area:68}) к распорядителю полетов. {npc:903} стоит у дороги рядом с ней.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Идите по дороге на северо-запад мимо кладбища к лагерю {npc:311} на дальнем западном краю леса. {npc:893} стоит рядом со {npc:311}.",
		["Greater Tarantulas crawl on the slopes around {quest:98386}, north-east of the lake; their Tarantula Eggs lie on the ground among them: click six."] = "Крупные тарантулы ползают по склонам ({quest:98386}) к северо-востоку от озера; их яйца лежат на земле среди них: соберите шесть.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "Кеешан прячется в самом северном конце долины, у границы зоны {zone:1428}. Проводите его вниз до места {area:69}; по пути на вас нападут орки клана Черной Горы.",
		["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "Мурлоки-трупоеды и мурлоки-волномуты стоят вдоль южного берега ({area:68}), чуть восточнее грифонов и моста. У любого из них может оказаться плавник.",
		["The Wanted poster by the inn"] = "Плакат «Разыскивается» у таверны",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "Хижина отшельника стоит в лесу к северо-востоку от кладбища (ориентир: {area:492}).",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "Холмик рыхлой земли – к югу от фермерского дома, у старого пня.",
		["Your new spells"] = "Ваши новые заклинания",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: любой гнолл из стаи Темношкуров",
		["{item:1130}: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses"] = "{item:1130}: карликовые ядовитые кругопряды, ядовитые кругопряды и зеленые отшельники",
		["{item:15882}: the {object:177790}"] = "{item:15882}: {object:177790}",
		["{npc:2409}, at the north end of town"] = "{npc:2409} – в северной части города",
		["{npc:264}, in the town hall"] = "{npc:264} – в ратуше",
		["{npc:267}, in the town hall"] = "{npc:267} – в ратуше",
		["{npc:268}, in the house behind the town hall"] = "{npc:268} – в доме за ратушей",
		["{npc:341}, beside him"] = "{npc:341}, рядом с ним",
		["{npc:344}, in the town hall"] = "{npc:344}, в ратуше",
		["{npc:345} (level 24) roots around the pen just west of {area:69}, beside {npc:342}'s garden. Pull him away from the other boars and fight at full health."] = "{npc:345} (уровень 24) роется в загоне чуть западнее места {area:69}, рядом с огородом NPC {npc:342}. Выманите его от других кабанов и сражайтесь с полным здоровьем.",
		["{npc:382}, at the north end of the bridge"] = "{npc:382}, у северного конца моста",
		["{npc:663}, by the town hall"] = "{npc:663} – у ратуши",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790} – таверна «Scarlet Raven»",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888} стоит к югу от дороги: {area:245}.",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, у грифонов к югу от моста",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "/lay – лягте рядом с NPC {npc:7207}",
		["Back to {area:42}"] = "Назад: {area:42}",
		["Cathedral of Light"] = "Собор Света",
		["Class trainer"] = "Учитель классовых навыков",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}, северная часть: ребро может выпасть с любого вурдалака. Плотояды и костеглоды (24-27) убиваются легче; распространители чумы и мозгоеды (27-29) тоже их роняют. Среди могил бродит {npc:522}, элита: держитесь от него подальше.\nОсторожно: {npc:948}, умирая, применяет {spell:3428}, что приводит дополнительных противников.",
		["Ghoul Ribs"] = "Ребра вурдалака",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Идите на север через Элвиннский лес в город {zone:1453}; Матиас Шоу – в ШРУ, район {object:2100}.",
		["Head west along the road once more."] = "Еще раз идите по дороге на запад.",
		["Head west to the hermit once more."] = "Еще раз идите на запад к отшельнику.",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "Ее дом стоит на холме к юго-востоку от поселка {area:42}, выше, чем {area:121}.",
		["Inside"] = "Внутри",
		["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "Дальше: обучение, затем полет из города {zone:1453} в {area:150} и дальше в зону {zone:1437}.",
		["Shaman training"] = "Обучение шамана",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "Ужасные скелеты бродят по склону холма к юго-востоку от города, между поселком {area:42} и кладбищем ({area:121}); с них падают цветки гнили.",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Your new spells"] = "Ваши новые заклинания",
		["{item:1946}: the {npc:511} in the cemetery's crypt is level 26; it waits for the {zone:1431} return"] = "{item:1946}: {npc:511} в склепе кладбища – 26-го уровня; ждет возвращения в зону {zone:1431}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, товары для алхимиков",
		["{item:7908}, in the chest"] = "{item:7908}: в сундуке",
		["{npc:267}, in the town hall"] = "{npc:267} – в ратуше",
		["{npc:273}, in the tavern"] = "{npc:273} – в таверне",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288} прячется в доме на западной окраине деревни {area:94}.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: Яды и {item:18160}",
		["{npc:6171}: Redemption"] = "{npc:6171}: Искупление",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, в подвале казарм",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: редкая добыча с существ зоны {zone:1431}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "В городе {zone:1453} нет учителя шаманов: сядьте на поезд ({area:2257}) в месте {object:28027} до города {zone:1455}, обучитесь у NPC {npc:258098}, затем вернитесь на поезде.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back north through the {area:1276}: west of {area:421}, the stardust bushes grow among the ruins."] = "Назад на север через {area:1276}: к западу от места {area:421} среди руин растут кусты, покрытые звездной пылью.",
		["Back west along the road from {npc:3916}, {area:415} is on the way to {npc:3664}: {npc:3894} is inside the building beyond the inn."] = "Назад на запад по дороге от NPC {npc:3916}: {area:415} по пути к NPC {npc:3664}. {npc:3894} в здании за таверной.",
		["Below ground"] = "Под землей",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site. Careful: Highland Lurkers and Horrors, level 28 elites, walk the same cave among them: pull the stalkers one at a time and keep clear of the elites."] = "Пещерные ловцы и ловцы-кровопийцы заполняют {area:1021}, пещеру к юго-востоку от раскопок. Осторожно: среди них по той же пещере ходят горные скрытни и ужасы, элитные противники 28-го уровня: выманивайте ловцов по одному и держитесь подальше от элитных.",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Идите вдоль побережья на север к {area:414}. {npc:3846} стоит лагерем на пляже; берег кишит нагами из клана Зловещего Хвоста.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Идите по дороге на восток сюда: {area:419}; {npc:3916} стоит у лунного колодца.",
		["Head west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Идите на запад к берегу озера ({area:441}). Труп Терониса лежит среди мурлоков из племени Соленой Слюны; с любого мурлока может выпасть {item:5463}.",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "Гноллы и полукровки из стаи Мохошкуров удерживают холмы к юго-востоку от места {area:1025}.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "К северу от Заставы Мейстры вокруг руин ({area:411}) лежат пучки трав. Сектанты из клана Темной Нити удерживают руины чуть южнее: с любого из них может выпасть {item:5366}.",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Только если у вас есть {item:5352} из зоны {zone:1439}: {npc:2786}, {object:32383}",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "К югу от мурлоков {npc:3585} ждет здесь: {area:416}.",
		["The Mosshide gnolls"] = "Гноллы из стаи Мохошкуров",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "Торговая компания вырубает лес ({area:461}). Лесорубы и лесозаготовители работают повсюду; операторы управляют крошшерами, у одного из них чертежи.",
		["The excavation site sits on the hill south of the road."] = "Раскопки находятся на холме к югу от дороги.",
		["The raptor hills"] = "Холмы ящеров",
		["The tears glow on the small isle east of {area:415}."] = "Слезы светятся на маленьком островке к востоку от места {area:415}.",
		["Tram to {zone:1453}"] = "Поезд до {zone:1453}",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, в руинах на берегу",
		["{npc:1239}, in the inn"] = "{npc:1239}, в таверне",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, на пирсе к северу от таверны",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: письмо Тандриса из места {area:442}",
		["{npc:2086}, in the keep"] = "{npc:2086}, в крепости",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} стоит лагерем у дороги; {npc:1244} стоит восточнее, у реки.",
		["{npc:2096}, by the north gate"] = "{npc:2096}, у северных ворот",
		["{npc:3691}, in the inn"] = "{npc:3691}, в таверне",
		["{npc:3693} stands by the flight master, at the east end of the main street. No {quest:990} yet? Give it a minute after the hand-in: {npc:3694} comes to {npc:3693}'s side shortly after Volcor's escort is handed in. Changing layer can also find her. Then back west to the dock."] = "{npc:3693} стоит рядом с распорядителем полетов, в восточном конце главной улицы. Задания {quest:990} еще нет? Подождите минуту после сдачи: {npc:3694} подходит к NPC {npc:3693} вскоре после того, как сдано задание на сопровождение Волкора. Также ее можно найти, сменив слой. Затем возвращайтесь на запад к причалу.",
		["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693}: сопровождение Волкора в конце гайда по зоне {zone:1439}",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: сдается NPC {npc:11401} ({zone:1457}), позже",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: сдается NPC {npc:11406} ({zone:1455}), позже",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: сдается NPC {npc:258785} ({zone:1455}), позже",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: сдается NPC {npc:6244} ({zone:1413}), позже",
		["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164} находится здесь: {object:2101}. Чернокнижникам: {npc:6122} – в его подвале.",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009} ходит по северной оконечности {area:414} со стражами из клана Зловещего Хвоста.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, из пучков трав",
} end)()
t.guides["forever/alliance/06-wetlands"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "Вернитесь в Собор Света: {npc:928} стоит внутри.",
		["Below ground"] = "Под землей",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Cathedral of Light"] = "Собор Света",
		["Dartol's Rod"] = "Жезл Дартола",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Идите по дороге на восток к лагерям сатиров ({area:429}); {npc:3920} прячется на их окраине.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Идите по дороге на восток сюда: {area:419}; {npc:3916} стоит у лунного колодца.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Для Верховного лорда Болвара Фордрагона ({object:2117}): сохраните",
		["For {npc:3649} in {area:442}, on this guide's boat trip: keep it"] = "Для NPC {npc:3649} ({area:442}), во время плавания по этому руководству: сохраните",
		["From {area:413}, east to the Thistlefur camp north of {area:415}: {npc:3987} leads the furbolgs there. Then south to {area:415}.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "От места {area:413} идите на восток к лагерю Чертополоховых к северу от места {area:415}: там фурболгов ведет {npc:3987}. Затем на юг ({area:415}).\nОсторожно: фурболги рядом с ним обычно вступают в бой, когда его выманивают. Убейте сначала тех, что на его пути, чтобы сразиться с ним один на один.",
		["Hearth back to {area:150} if you bound at the {area:2104}, or walk west along the road: {npc:2104} stands on the top floor of {area:2103}, {npc:2094} by the docks on the way to the boat."] = "Используйте камень возвращения, чтобы вернуться сюда: {area:150}, если вы привязаны к таверне ({area:2104}), или идите на запад по дороге: {npc:2104} стоит на верхнем этаже ({area:2103}), {npc:2094} – у причалов по пути к кораблю.",
		["Insane druids"] = "Обезумевшие друиды",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "Убивайте элементалей ради 5 неповрежденных браслетов элементаля, затем используйте {item:5456}",
		["Level 28"] = "28-й уровень",
		["Melyria and {npc:3901}"] = "Мелирия и {npc:3901}",
		["Next: fly to {area:42}."] = "Далее: летите сюда: {area:42}.",
		["Off the boat, {npc:1480} stands beside Menethil's inn, on the way to the flight master."] = "Сойдя с корабля, найдите NPC {npc:1480} у таверны Менетила, по пути к распорядителю полетов.",
		["On the way south-east to {npc:3897}: the Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "По пути на юго-восток к NPC {npc:3897}: фурболги из Гиблолесья живут в лесу к югу от дороги, к юго-востоку от места {area:415}. Логово охраняют дозорный логова и урсы.",
		["Only if you looted {quest:337} in {zone:1431}"] = "Только если вы добыли {quest:337} в зоне {zone:1431}",
		["Raptor valley"] = "Долина ящеров",
		["South from {npc:3987}'s camp to {area:415}: {npc:3691} in the inn, the flight master at the west end."] = "От лагеря NPC {npc:3987} на юг, сюда: {area:415}. {npc:3691} – в таверне, распорядитель полетов – в западном конце.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end. Careful: Terrowulf Fleshrippers and Shadow Weavers (28-30) stand in tight packs around the tome, and the {npc:3792}, a level 32 rare, walks the vale. Pull the wolves one at a time from the tunnel and let the Packlord pass first."] = "Пройдите по туннелю сюда: {area:419}; фолиант лежит в руинах в западной части. Осторожно: потрошители и ткачи теней из стаи Ужасоволков (28-30) стоят плотными группами вокруг фолианта, а по долине ходит {npc:3792}, редкий противник 32-го уровня. Выманивайте волков по одному из туннеля и сначала пропустите вожака стаи.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Сядьте на поезд ({area:2257}) в месте {object:171524} до места {object:28027} ({zone:1453}), затем идите сюда: {object:2098}.",
		["The Bluegill hovels"] = "Хижины Синежабрых",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "{item:5475} у безумных и высохших древняков к северу от лунного колодца; старый сундук, который он открывает, стоит среди них.",
		["The Foulweald"] = "Гиблая Чаща",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "Второй {object:19901} — в долине ({area:428}), по пути на запад.",
		["Tram to {zone:1453}"] = "Поезд до {zone:1453}",
		["Underwater"] = "Под водой",
		["grind on {npc:1418}"] = "убивайте цель {npc:1418}",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there, {npc:221269} a few steps east of her."] = "{area:2358} — застава ночных эльфов в восточном конце дороги: там стоит {npc:3848}, а {npc:221269} — в нескольких шагах к востоку от нее.",
		["{item:2661}: the {object:331}"] = "{item:2661}: {object:331}",
		["{item:279915} lies on the shore just south of {area:150}, a short walk past the town's south end. Then follow the coast north out of town to the hovels."] = "{item:279915} лежит на берегу чуть южнее места {area:150}, недалеко от южной окраины города. Затем идите вдоль побережья на север из города к хижинам.",
		["{npc:1077}, below ground"] = "{npc:1077}, под землей",
		["{npc:1078} and Whelgar"] = "{npc:1078} и Вельгар",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} и {npc:258785} находятся здесь: {object:32386} ({object:32362}).",
		["{npc:1239}, in the inn"] = "{npc:1239}, в таверне",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: для NPC {npc:2104} в крепости",
		["{npc:1646} stands in the {object:2098}."] = "{npc:1646} стоит здесь: {object:2098}.",
		["{npc:1646}: {quest:97914}, {npc:3649}'s letter, if you still carry it"] = "{npc:1646}: {quest:97914}, письмо от NPC {npc:3649}, если оно еще у вас",
		["{npc:221269}, a few steps east"] = "{npc:221269}, в нескольких шагах к востоку",
		["{npc:221269}: her husband's trail in {area:430}, on the way back from the lake"] = "{npc:221269}: следы ее мужа ({area:430}), на обратном пути от озера",
		["{npc:270844}, beside him"] = "{npc:270844}, рядом с ним",
		["{npc:270844}, beside {npc:2094} by the docks"] = "{npc:270844}, рядом с NPC {npc:2094} у причалов",
		["{npc:3649} stands at the north end of {area:442}, up the road from the dock."] = "{npc:3649} стоит в северной части места {area:442}, вверх по дороге от причала.",
		["{npc:3691} stands in the inn, beside the innkeeper."] = "{npc:3691} стоит в таверне, рядом с хозяином таверны.",
		["{npc:3691}: {quest:1025}, the Foulweald on the way to {npc:3897}"] = "{npc:3691}: {quest:1025}, Гиблолесье по пути к NPC {npc:3897}",
		["{npc:3691}: {quest:1054}, {npc:3987} on the way back from {area:413}"] = "{npc:3691}: {quest:1054}, {npc:3987} на обратном пути от места {area:413}",
		["{npc:3691}: {quest:990}, if you still carry it from {zone:1439}"] = "{npc:3691}: {quest:990}, если это задание из зоны {zone:1439} еще у вас",
		["{npc:3694}, once she comes: {quest:990}, for {npc:3691} in {area:415}"] = "{npc:3694}, когда она появится: {quest:990}, для NPC {npc:3691} ({area:415})",
		["{npc:3845} and {npc:3970} stand by {area:415}'s flight master."] = "{npc:3845} и {npc:3970} стоят рядом с распорядителем полетов ({area:415}).",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}, just north of the road to {npc:3897}. Befouled Water Elementals wade in the lake; {npc:12759}, a level 27 water elemental, walks among them and drops the bracers too."] = "{npc:3885} стоит здесь: {area:420}, на восточном берегу ({area:421}), чуть севернее дороги к NPC {npc:3897}. В озере бродят злобные элементали воды; среди них ходит {npc:12759}, элементаль воды 27-го уровня, с нее тоже падают наручи.",
		["{npc:3901}: the {item:5461}"] = "{npc:3901}: {item:5461}",
		["{npc:3920}: {quest:1031}, from {npc:4619} (level 32): a fight for a group at this level"] = "{npc:3920}: {quest:1031}, с NPC {npc:4619} (32-й уровень): на этом уровне бой для группы",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, сырная лавка ({object:2096})",
		["{npc:4959} and {npc:482}"] = "{npc:4959} и {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, в Соборе Света",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: для NPC {npc:3961} ({area:415})",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
		["{zone:1455} priests"] = "Жрецы: {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to {area:42}"] = "Назад: {area:42}",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Для NPC {npc:1212} ({zone:1453}), в следующем гайде",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Для NPC {npc:482} ({zone:1453}), в следующем гайде",
		["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it. {npc:300} is inside the ogre mound's cave: go in by the cave mouth on the mound's west side."] = "Идите на юго-запад от поселка {area:42} к кургану огров. {object:119} лежит в лагере у входа; его охраняют огры из клана Дробящего Кулака. {npc:300} – внутри пещеры кургана: входите через вход в пещеру на западной стороне кургана.",
		["Nightbane Dark Runners"] = "Вестники Тьмы из стаи Ночной Погибели",
		["Nightbane Shadow Weavers"] = "Тенеткачи Ночной Погибели",
		["Nightbane Vile Fangs and Tainted Ones"] = "Ярые Клыки Ночной Погибели и Порченые",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Вестники Тьмы рыщут по лесу к югу от дороги, к западу от поселка {area:42}.",
		["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 quests, but no fight."] = "Могила стоит среди скелетов в северо-западном углу кладбища, по пути к NPC {npc:311}. Ее задание и следующее – только разговоры, с NPC {npc:268} и командиром Алтеей в поселке {area:42}: задания 35-го уровня, но без боя.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Ворги занимают лес Светлой рощи к западу от поселка {area:42} и к северу от дороги. Выманивайте их по одному.",
		["The {npc:511}"] = "{npc:511}",
		["The {npc:511} hides in the small crypt by the {area:121}, south of {area:42}. {npc:663}'s Nightbane Vile Fangs and Tainted Ones (level 29-31) roam the woods around it: they come at the end of this guide, a level later."] = "{npc:511} прячется в маленьком склепе ({area:121}), к югу от поселка {area:42}. Ярые Клыки Ночной Погибели и Порченые (29-31-й уровень) для NPC {npc:663} бродят по лесу вокруг: они будут в конце этого гайда, уровнем позже.",
		["Wait a moment, then speak with her again"] = "Подождите немного, затем поговорите с ней снова",
		["{npc:263}, in the town hall"] = "{npc:263} – в ратуше",
		["{npc:268}, in the house behind the town hall"] = "{npc:268} – в доме за ратушей",
		["{npc:311}'s Camp"] = "Лагерь {npc:311}",
