t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort {npc:5644}"] = "Сопроводите {npc:5644}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Идите по дороге на запад мимо места {area:460} (Орда) и на юго-запад через {area:465} в зону {zone:1443}; {area:608} – на вершине перевала.",
		["For {npc:5638}, at the end of this guide"] = "Для NPC {npc:5638}, в конце этого гайда",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "Ее брат {npc:5643} (36) ходит по крепости с культистами (Пылающий Клинок, 30-33): выманите его одного. {npc:13019} хранит скипетр в главном здании крепости. По пути {npc:5642} просит по четыре культиста каждого вида.",
		["Inside"] = "Внутри",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Выведите {npc:5644} из крепости; когда вы выберетесь, она уйдет сама. Задание принимает {npc:5642} ({area:608}) в конце гайда.",
		["Malem chest"] = "Сундук Малема",
		["Out of Thunder Axe Fortress"] = "Выход из крепости Громового Топора",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Кентавры из племени Колкар бродят по равнинам вокруг места {area:609}; их уши – для NPC {npc:5752}.",
		["The chest lies in the ruins south-west of {area:608}."] = "Сундук лежит в руинах к юго-западу (ориентир: {area:608}).",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "Разбитый корабль лежит чуть к юго-западу от башни {npc:11863}; его сундук стоит рядом с объектом {object:177787}.",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "Лагерь {npc:11596} – на дороге к югу (ориентир: {area:609}), у места {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "Башня {npc:11863} стоит на холме к западу (ориентир: {area:599}): сначала возьмите его задание – нужный ему скипетр находится в крепости.",
		["{npc:5396}, beside {npc:5752}"] = "{npc:5396} – рядом с NPC {npc:5752}",
		["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}: сумка лежит у северо-западного побережья, на южном круге в конце 30-40 (06-badlands): сохраните ее",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: сундук с обломков корабля лежит под башней {npc:11863}, по пути к месту {area:599}",
		["{npc:5643} and the Seer"] = "{npc:5643} и Провидец",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} прячется в крепости клана Пылающего Клинка к юго-западу (ориентир: {area:608}).",
		["{npc:5752}: the Kolkar are at the end of this guide"] = "{npc:5752}: колкары – в конце этого гайда",
		["{object:177787}, beside the chest: keep it, its keys and chest come on {zone:1443}'s south loop at the end of 30-40"] = "{object:177787} рядом с сундуком: сохраните их – ключи и сундук будут на южном круге зоны {zone:1443} в конце 30-40",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Идите по каньонам на восток к соляным равнинам. Гоблины и гномы ({area:2240}) нейтральны и дают задания обеим фракциям.",
		["For {quest:5762} in Stranglethorn, later"] = "Для задания «{quest:5762}» в Тернистой долине, позже",
		["Inside"] = "Внутри",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "По пути на юг через зону {zone:1413}: {npc:6244} стоит лагерем к востоку от дороги, к северо-востоку от места {area:378}; подходите с востока и держитесь подальше от стражей Орды.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Слитки у мурлоков из племени Синежабрых на пляже к юго-западу от Менетила.",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Распорядитель полетов стоит у ворот ({area:514}); {npc:5083} и {npc:4964} – внутри цитадели.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "Обломки «Flying Osprey» лежат на мелководье к югу от крепости.",
		["Theramore"] = "Терамор",
		["{area:976} flight master"] = "Распорядитель полетов: {area:976}",
		["{item:5795}, from the Sparkleshell Tortoises"] = "{item:5795} – с блестопанцирных черепах",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} стоит в таверне ({area:2104}) к югу от крепости, где также ждут {npc:4963} и {npc:5082}.",
		["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Tortoises (30-31) the middle of the flats: hunt them for the shells. Careful: Sparkleshell Snappers (34-35) wander the whole flats, and the Saltstone Gazers (34-35) and Scorpid Terrors (33-34) hold the far south: leave them and keep to the north half."] = "{object:19868} разбросаны по всей равнине. Скорпиды-разорители и солончаковые падальщики бродят в северной половине, блестопанцирные черепахи (30-31) – в середине равнины: бейте их ради панцирей. Осторожно: блестопанцирные крепкохваты (34-35) бродят по всей равнине, а просоленные взорени (34-35) и скорпиды-убийцы (33-34) держат дальний юг: не трогайте их и держитесь северной половины.",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132} – в таверне на севере городка",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: в зоне {zone:1440}, по пути в зону {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: инкуб, рядом с суккубом; {item:190309} – рядом с целью задания «{quest:1738}»",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Назад на юг мимо Эрнестуэя: пантеры и ящеры Тернистой долины бегают по полянам к западу от лагеря в сторону побережья; старые тигры занимают холмы на юго-западе.",
		["Fly to {area:467}"] = "Летите в {area:467}",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Gluggle (37, rare) on the coast west of camp drops the {item:4614}: four levels over you, leave him unless you are grouped"] = "Барабуль (37, редкий) на побережье к западу от лагеря роняет предмет {item:4614}: он на четыре уровня выше вас, не трогайте его без группы",
		["Panthers, raptors and elder tigers"] = "Пантеры, ящеры и старые тигры",
		["Stranglethorn Tigers"] = "Тигры Тернистой долины",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side. Careful: Kurzen Elites and Witch Doctors (36) hold the compound's eastern half, by the cave: stay on its west side."] = "Повстанцы Курцена занимают лагерь к востоку от места {area:99}; действуйте по его внешнему краю, где стоят партизаны и целители Курцена, и обыскивайте ящики с припасами у палаток. Записи для задания «{quest:200}» лежат в хижине в западной части лагеря. Осторожно: элитные бойцы и знахари Курцена (36) удерживают восточную половину лагеря у пещеры: держитесь западной стороны.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Взрослые тигры рыщут по холмам сразу к югу и западу от лагеря.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Старые тигры – позже, на обратном пути от лагеря ({area:99})",
		["The haunted island"] = "Остров духов",
		["Warlocks fly to {area:415} for the {quest:1738}, on the way west."] = "Чернокнижники летят в {area:415} за заданием «{quest:1738}» по пути на запад.",
		["You know the {area:467} flight: it lands closer to {zone:1443} than {area:415} does. From the peak, follow the road south through the mountains to the {area:465}."] = "Вам известен маршрут полета в {area:467}: он ближе к зоне {zone:1443}, чем {area:415}. От пика идите по дороге на юг через горы до места {area:465}.",
		["keep it: the Lashtail Raptors come on the second loop (04b), around {npc:729}'s hill"] = "сохраните его: ящеры-кнутохвосты будут на втором круге (04b), у холма {npc:729}",
		["keep it: the Shadowmaw Panthers (37-38) wait for the 40-50 Stranglethorn guide"] = "сохраните его: тенебрюхие пантеры (37-38) ждут гайда 40-50 по Тернистой долине",
		["keep it: {npc:729} (37) comes in the 40-50 Stranglethorn guide, at about 41"] = "сохраните его: {npc:729} (37) будет в гайде 40-50 по Тернистой долине, примерно на 41 уровне",
		["{item:190309}, north of {area:413}"] = "{item:190309}, к северу (ориентир: {area:413})",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}: из ящика ({object:263})",
		["{npc:2495}, by the bank; inside"] = "{npc:2495} – у банка; внутри",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496} – наверху в таверне",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832} – {object:56910}; наверху",
		["{npc:469}, in the hut"] = "{npc:469} – в хижине",
		["{npc:715}, from {zone:1441}"] = "{npc:715}: из зоны {zone:1441}",
		["{npc:737}'s Bloodscalp ears wait for the second Stranglethorn loop: keep the quest."] = "Уши Кровавого Скальпа для NPC {npc:737} ждут второго круга по Тернистой долине: сохраните задание.",
		["{npc:738}, at the foot of the path"] = "{npc:738} – у подножия тропы",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}: для NPC {npc:773} ({area:35}), позже в этом гайде",
		["{object:661516}, a looted crate west of Nesingwary's camp: the Stolen Shipments lie in the Bloodscalp ruins on the coast, for the second Stranglethorn loop"] = "{object:661516} – разграбленный ящик к западу от лагеря Несингвари: украденные грузы лежат в руинах Кровавого Скальпа на побережье, для второго круга по Тернистой долине",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: просто осмотритесь в лагере охотников",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["East from the ruins to the hilltop south-west of Nesingwary's camp: the Lashtail Raptors run in the jungle around it. Leave {npc:729}, the great tiger (37) on the hilltop, to the 40-50 Stranglethorn guide: you're about 35 here. Then on to the hunters' tents."] = "На восток от руин к вершине холма к юго-западу от лагеря Эрнестуэя: ящеры-кнутохвосты бегают в джунглях вокруг него. Оставьте NPC {npc:729}, большого тигра (37) на вершине, для гайда по Тернистой долине 40-50: здесь у вас около 35-го уровня. Затем идите к палаткам охотников.",
		["For Archmage Ansirem in {zone:1416}"] = "Для верховного мага Ансарема (зона {zone:1416})",
		["For characters of 35 to 36, but several quests here are level 37-38: on purpose, for their experience. The water elementals are 36-37: pull them one at a time."] = "Для персонажей 35-36 уровня, но несколько заданий здесь 37-38 уровня: намеренно, ради опыта. Элементали воды – 36-37 уровня: выманивайте их по одному.",
		["For {npc:4631} in {area:35}, at the end of this loop"] = "Для NPC {npc:4631} ({area:35}), в конце этого круга",
		["Snapjaw Crocolisks"] = "Кроколиски-хрустогрызы",
		["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to {area:35}."] = "Кроколиски-хрустогрызы греются вдоль реки посреди джунглей, по пути на юг в {area:35}.",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals. Careful: Venture Co. Agents (39) walk among them: take the Geologists on the camps' edges, one at a time. Shadowmaw Panthers (37-38) prowl stealthed in the jungle south and east of the lake: keep to the shore camps."] = "От лагеря на юг к озеру ({area:37}): упавшие кристаллы носят геологи Торговой компании из лагерей на его берегу. Осторожно: среди них ходят агенты Торговой компании (39): берите геологов по краям лагерей, по одному. Тенебрюхие пантеры (37-38) в незаметности рыщут в джунглях к югу и востоку от озера: держитесь лагерей на берегу.",
		["The Lashtail raptors"] = "Ящеры-кнутохвосты",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "Остров с призраками лежит у самого берега к западу от второй таблички: из воды вокруг него поднимаются малые элементали воды.",
		["The jungle ruins"] = "Руины в джунглях",
		["The {area:102}"] = "{area:102}",
		["keep it: the Skullsplitter Witch Doctors (41-42) wait for the 40-50 Stranglethorn guide"] = "сохраните его: знахари из племени Дробителей Черепов (41-42) ждут гайда по Тернистой долине 40-50",
		["{item:277957}, from the Bloodscalp trolls"] = "{item:277957} – с троллей Кровавого Скальпа",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496} – наверху в таверне",
		["{npc:4631}, on the docks"] = "{npc:4631} – на пристани",
		["{npc:715}: the Jungle Stalkers come in 40-50"] = "{npc:715}: тропические ловцы будут в гайде 40-50",
		["{npc:773}, upstairs: this optional quest needs four {item:4278}. Mine Lesser Bloodstone Deposits in {zone:1417} with {skill:186} 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore."] = "{npc:773} – наверху: для этого необязательного задания нужно четыре шт. {item:4278}. Добывайте руду из малых месторождений кровавого камня в зоне {zone:1417} с навыком {skill:186} 75, купите ее на аукционе или попросите друга-шахтера. Кобольды ее не роняют; пропустите задание, если не можете достать руду.",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A group stop: two level 40 water elementals ambush {npc:2768}'s escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Остановка для группы: два водных элементаля 40-го уровня нападают на сопровождение NPC {npc:2768}, а наги Колючего Хребта на рифе 38-40-го уровня, среди них есть волшебницы. Лучше собрать группу, поищите напарников. Если вы один, пропустите ее.\nНа юг вдоль западного побережья к бухте гоблинов; Лоло наблюдает со скал над ней.",
		["A {npc:2434} (37-38) lurks stealthed on the edge of {area:271}, and few players find him. Careful: he is a level or two over you; fight him only at full health, or leave him. His contract goes to {npc:2276}. Don't wait for him: the rest of this step doesn't need him."] = "{npc:2434} (37-38) скрывается в незаметности на окраине места {area:271}, и мало кто его находит. Осторожно: он на уровень-два выше вас; сражайтесь с ним только с полным здоровьем или оставьте его. Его контракт примет {npc:2276}. Не ждите его: остальной части шага он не нужен.",
		["Back west through {zone:1430} to {area:42}."] = "Обратно на запад через {zone:1430} сюда: {area:42}.",
		["Below ground"] = "Под землей",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "На восток от места {quest:681} через север нагорья; осколки сверкают на холме у места {area:333}, к северу от места {area:314}.",
		["Fly to {area:144}"] = "Летите сюда: {area:144}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:42}"] = "Летите сюда: {area:42}",
		["Fly to {zone:1453}"] = "Летите сюда: {zone:1453}",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings."] = "Идите по дороге на север из места {area:271} в горы. По склонам бродят горные львы; члены Синдиката в месте {area:280} носят перстни-печатки.",
		["For characters of 35 to 37. {area:327}, where the naga and the professor's water elementals are 38-40, is a group stop: skip it if you are alone."] = "Для персонажей 35-37-го уровня. {area:327}, где наги и водные элементали профессора 38-40-го уровня, – место для группы: пропустите его, если играете в одиночку.",
		["For {npc:1356} in {zone:1455}, at the end of this guide"] = "Для NPC {npc:1356} ({zone:1455}), в конце этого гайда",
		["For {npc:1440} in {zone:1453}: keep it"] = "Для NPC {npc:1440} ({zone:1453}): сохраните",
		["For {npc:2542} in {area:35}: keep it"] = "Для NPC {npc:2542} ({area:35}): сохраните",
		["For {npc:2711} in {area:271}"] = "Для NPC {npc:2711} ({area:271})",
		["From the Syndicate camp, follow the road east over {area:1057} to {area:320}."] = "От лагеря Синдиката идите по дороге на восток через {area:1057} сюда: {area:320}.",
		["From {npc:2712}'s camp, a short way north-east to the {object:2691}, by the shards' hill north of {area:314}. The {object:2702}, where the three keys go, stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "От лагеря NPC {npc:2712} немного на северо-восток: {object:2691}, у холма с осколками к северу от места {area:314}. {object:2702}, куда несут три ключа, стоит к западу от места {area:320}.\nОсторожно: каждый центральный камень охраняют около трех элементалей примерно 39-го уровня, которые нападают вместе, если щелкнуть по камню, не перебив их: пылающие изгои – у западного, грохочущие изгнанники – у внешнего, морские изгои – у восточного.",
		["Lost Ones: Hunters, Muckdwellers, Seers and Riftseekers all count"] = "Заблудшие: засчитываются охотники, грязеземцы, провидцы и искатели разломов",
		["North out of {area:271} to the Syndicate camp on the Alterac border, west of {area:272} (Horde): its Footpads and Thieves are the Syndicate Maleb wants, and the documents lie in the camp. Then back to the road and east to Arathi.\nCareful: a few Syndicate Wizards (34-35) stand among the tents and cast from range: pull them one at a time."] = "На север из места {area:271} к лагерю Синдиката на границе с Альтераком, к западу от места {area:272} (Орда): его разбойники и воры – это тот Синдикат, что нужен Малебу, а документы лежат в лагере. Затем вернитесь на дорогу и идите на восток в Арати.\nОсторожно: среди палаток стоят несколько волшебников Синдиката (34-35), они атакуют издалека: выманивайте их по одному.",
		["North-west of Watcher Biggs, {npc:255597} (level 34) waits by the road: lead him north to the {area:657}, on your way there. Stay close to him and clear what attacks him; if he falls, abandon the quest and go on."] = "К северо-западу от дозорного Биггса у дороги ждет {npc:255597} (34-й уровень): проводите его на север к месту {area:657}, вам все равно туда. Держитесь рядом и убивайте всех, кто на него нападает; если он погибнет, откажитесь от задания и идите дальше.",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "На северо-запад из долины Сухокожих; {npc:2712} и {npc:2713} стоят лагерем на холмах сразу к северу от места {area:314}.",
		["Off the flight, straight to the {area:271} inn. Then {npc:2276} and {npc:2277}, in the town hall, take the Syndicate camp's quests and send you north to {area:280}."] = "После полета сразу в таверну ({area:271}). Затем {npc:2276} и {npc:2277} в ратуше дадут задания по лагерю Синдиката и отправят вас на север сюда: {area:280}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Только если Барабуль дал вам подвеску в Тернистой долине",
		["Phizzlethorpe"] = "Физзлторп",
		["South-east along the loch to the dig site."] = "На юго-восток вдоль озера к раскопкам.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Держитесь рядом с NPC {npc:2713}, пока она пробирается сюда: {area:314} и обратно; по пути на вас нападут орки Орды.\nОсторожно: орки при малом здоровье убегают. {npc:2713} преследует их и может привлечь других противников, так что быстро убивайте или замедляйте беглецов.",
		["Syndicate camp"] = "Лагерь Синдиката",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need {skill:186} 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Кобольды из племени Сухоусов копают в ущелье к востоку от места {area:321} (Орда); обойдите поселение с севера. С них падает «Мощь Мизраэли», а не руда для Кразека. Для малых месторождений кровавого камня нужен навык {skill:186} 75: добудьте четыре куска руды, купите их на аукционе или попросите друга-шахтера. Цель с рудой необязательна; если не можете ее достать, продолжайте с Мизраэлем. Осторожно: все виды кобольдов убегают за подмогой при низком здоровье (кобольды – при 30%, геодезисты и землекопы – при 15%), и так можно привлечь еще больше.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "Курьер с двумя стражами ходит по дороге от места {area:314} на запад через нагорье примерно до 24,45 и обратно: стрелка ведет по дороге на запад, пока вы его не встретите. Выманите их с дороги.",
		["The shards lie at the far end of {area:318}."] = "Радужные осколки лежат в дальнем конце места {area:318}.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Два затонувших корабля лежат в заливе к западу от бухты. Карты и журналы внутри них; самоцветы лежат на морском дне вокруг. Наги из клана Пронзающего Гребня плавают по всему заливу.",
		["The western swamp"] = "Западная часть болота",
		["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "Сундук разбитого каравана стоит в северной части места {area:76}, рядом с клеткой NPC {npc:5391}.\nОсторожно: лагерь полон Заблудших около 38-го уровня. Они стоят связанными группами по 2-3, многие из них заклинатели, и возрождаются они быстро.",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["West along the road to {area:320}."] = "На запад по дороге сюда: {area:320}.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Молодые кроколиски, ткачи скорби и болотные ягуары бродят по болоту вокруг дороги.",
		["{item:258530}, from a {npc:757}"] = "{item:258530}, с NPC {npc:757}",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: огры из клана Раздробленного Хребта",
		["{item:3659}: the {object:1760}, beside Muckrake (40, elite): get it with a group, or abandon {quest:540}; inside"] = "{item:3659}: {object:1760}, рядом с Muckrake (40, элитный): берите его с группой или откажитесь от задания {quest:540}; внутри",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435}: с противников {npc:2572}, {npc:2573} и {npc:2574}, рядом с этой точкой",
		["{item:6071}, the blue crystals by the tents"] = "{item:6071}, синие кристаллы у палаток",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, дорога к месту {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Собор Света",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, королевская библиотека в крепости",
		["{npc:1776}: {npc:255597}'s escort"] = "{npc:1776}: сопровождение NPC {npc:255597}",
		["{npc:1776}: {quest:93464}, for {npc:11863} in {zone:1443}, on the {zone:1443} guide at the end of 30-40"] = "{npc:1776}: {quest:93464}, для NPC {npc:11863} ({zone:1443}), в гайде по зоне {zone:1443} в конце 30-40",
		["{npc:185335}, at the same circle"] = "{npc:185335}, у того же круга",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: три зверька, которых нужно поймать в Нагорье Арати, Пустошах ({zone:1443}) и Тернистой долине",
		["{npc:2276}: the signet rings are in {area:280}"] = "{npc:2276}: перстни-печатки в месте {area:280}",
		["{npc:2434}, if you spot him"] = "{npc:2434}, если заметите",
		["{npc:2705}, below ground"] = "{npc:2705}, под землей",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} и {npc:2713}",
		["{npc:2713}'s errand"] = "Поручение: {npc:2713}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards. Careful: on the walk out the camp's Lost One Riftseekers (37-38) and their pets, with the Lost Ones around them, turn on {npc:5391}: clear the cage and the start of his path first, stay beside him and pull every attacker onto yourself. Many players lose him the first time; if he dies, abandon the quest and take it again at his cage."] = "{npc:5391} заперт в клетке в северной части святилища. Освободите его и не дайте ему погибнуть по пути наружу; затем его сундук будет ждать у дороги. Осторожно: на обратном пути искатели разломов из Заблудших (37-38) из лагеря и их питомцы, вместе с окружающими их Заблудшими, нападают на NPC {npc:5391}: сначала расчистите клетку и начало его пути, держитесь рядом с ним и перетягивайте каждого нападающего на себя. Многие игроки теряют его в первый раз; если он погибнет, откажитесь от задания и возьмите его снова у клетки.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} привязывает инкуба к вам",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}). Используйте {item:6913} у круга призыва и победите призванного суккуба. Если вы взяли задание {quest:65602}, отдайте ему еще и {item:190309}, поставьте ее у того же круга и победите инкуба.",
		["{quest:651} is a group quest at this level: three Cresting Exiles (38-39) guard the {object:2691} and attack together. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "{quest:651} на этом уровне – задание для группы: три морских изгоя (38-39) охраняют {object:2691} и нападают вместе. Лучше собрать группу, поищите напарников. Если вы один, пропустите его.",
		["{quest:65602}, if you took it"] = "{quest:65602}, если вы его взяли",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "На восток от места {area:1877}: {area:346}. {npc:2860} принимает металлолом.",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "Для NPC {npc:4454} ({area:2240}): гайд по зоне {zone:1446} проходит мимо него на 45-м уровне, сохраните задание",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Идите на северо-восток к заброшенным раскопкам; ящик с припасами лежит там среди огров из клана Гнилобрюхов.",
		["Head south to {area:345}."] = "Идите на юг. Цель: {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Идите на запад. Цель: {area:1878}; в ее центре у своих машин работает {npc:2921}.",
		["Rock Elementals"] = "Каменные элементали",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "Следующее поручение Ржанца ведет сюда: {area:1517}. Пропустите его.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Разбитый скелет лежит чуть восточнее огров, на краю лагеря троггов из племени Каменного Свода; хлопья падают с костегрызов и шаманов вокруг. Тельдарин сидит у разрушенного лагеря дальше к югу.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Моллюски – на северо-западном побережье Тернистой долины, в следующем гайде: сохраните задание",
		["The excavation crate"] = "Ящик с раскопок",
		["The {object:126260}"] = "{object:126260}",
		["Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside {area:1517}'s cave mouth, beside level 38 elites: a quest for a group."] = "Тельдарин сидит у разрушенного лагеря к югу от лагеря троггов. Его скрижаль лежит сразу за входом в пещеру ({area:1517}), рядом с элитными противниками 38-го уровня: задание для группы.",
		["To {area:2101}"] = "В таверну: {area:2101}",
		["{item:4630}, from the Dustbelcher Ogres"] = "{item:4630} – с огров из клана Гнилобрюхов",
		["{item:7847}, if you still need one: the Buzzards east of {area:345} drop it only rarely"] = "{item:7847}, если он еще нужен: с канюков к востоку от места {area:345} падает лишь изредка",
		["{npc:4618} and {npc:2817} camp in the {area:1877}, on the road between {area:1517} and {area:345}."] = "{npc:4618} и {npc:2817} стоят лагерем здесь: {area:1877}, на дороге между местами {area:1517} и {area:345}.",
} end)()
t.guides["forever/alliance/30-40/06b-desolace"] = (function() return {
		["A long trip out to Kalimdor"] = "Долгий путь в Калимдор",
		["Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. {npc:5760} (40, elite) walks among the Mage Hunters: pull them out to you."] = "Снова в Ковене по пути на запад: мозги падают с пожирателей маны (37-38) на его северном краю и с охотников на магов (38-39) дальше внутри. {npc:5760} (40, элита) ходит среди охотников на магов: выманивайте их к себе.",
		["Fly to Theramore"] = "Летите на Терамор",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Идите по дороге на север: {area:608}. {npc:5396} стоит в южной части, {npc:5638} – в центре, {npc:1182} – на севере.",
		["Follow the road south to {area:2407}."] = "Идите по дороге на юг: {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Идите по дороге на запад через север зоны {zone:1443} к руинам: {area:2405}. Там на холме стоит башня NPC {npc:11863}, по пути к обломкам корабля.",
		["Kodo bones, demons and lost treasure in south {zone:1443}."] = "Кости кодо, демоны и потерянные сокровища на юге зоны {zone:1443}.",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "Сундук Ракмора лежит чуть юго-восточнее объекта {object:177673}.",
		["Short: about one level of quests"] = "Коротко: примерно один уровень заданий",
		["Stays on the main route"] = "Остается на основном маршруте",
		["The demons gather at the {area:602} in southern {zone:1443}. Nether Maidens (37-38) hold its north-west side and drop the wings; Doomwarder Captains (38) stand at the south end and drop the blood.\nCareful: Nether Sorceresses (39-40) stand beside the Doomwarder Captains, and {npc:5760}, a level 40 elite, walks the coven's middle: pull the captains away from them. Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Демоны собираются в месте {area:602} на юге зоны {zone:1443}. Девы Пустоты (37-38) занимают его северо-западную часть, с них падают крылья; капитаны тюремщиков судеб (38) стоят у южного края, с них падает кровь.\nОсторожно: рядом с капитанами стоят чародейки Пустоты (39-40), а {npc:5760}, элитный моб 40-го уровня, ходит по центру Ковена: выманивайте капитанов от них. Большинство мобов здесь патрулируют, так что легко сагрить лишних.",
		["The ghost magnets"] = "Призрачные магниты",
		["The next guide starts in Theramore."] = "Следующий гайд начинается на Тераморе.",
		["The {area:2657}"] = "{area:2657}",
		["Then on to {zone:1434}"] = "Затем в зону {zone:1434}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:6134}'s magnets draw the Magrami Spectres a few yards from the Magram Necrokhans and Corpsefeeders (45, elite) in the {area:2657}. Skip it if you are alone."] = "Это элитные мобы: лучше собрать группу, поищите спутников. Магниты из задания «{quest:6134}» притягивают призраков Маграм в нескольких метрах от некроханов Маграм и трупоедов (45, элита) в месте {area:2657}. Пропустите, если вы один.",
		["Underwater"] = "Под водой",
		["Use the {item:15848} at its arrow, on the fields' eastern side, to draw the Magrami Spectres; the Necrokhans and Corpsefeeders (45, elite) walk close by: keep the group together."] = "Используйте {item:15848} у его стрелки, на восточной стороне полей, чтобы приманить призраков Маграм; некроханы и трупоеды (45, элита) ходят рядом: держитесь группой.",
		["escort {npc:12277} back toward the graveyard"] = "сопроводите NPC {npc:12277} обратно к кладбищу",
		["for {npc:3980} in {area:271}: keep it"] = "для NPC {npc:3980} ({area:271}): сохраните",
		["for {npc:5637} in {zone:1455}: keep it"] = "для NPC {npc:5637} ({zone:1455}): сохраните",
		["{area:144} flight master"] = "Распорядитель полетов: {area:144}",
		["{area:598}: kill these as you meet them"] = "{area:598}: убивайте их, когда встретите",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, на объекте {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, с наг Скользящего Клинка",
		["{item:6251}, from the Nether Maidens"] = "{item:6251}, с Дев Пустоты",
		["{item:6252}, from the Doomwarder Captains"] = "{item:6252}, с капитанов тюремщиков судеб",
		["{npc:11863}: {quest:93464}, from Magtoor in the {zone:1435}"] = "{npc:11863}: {quest:93464}, от Магтура ({zone:1435})",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} держат в лагере кентавров к западу от кладбища. Освободите ее и сохраните ей жизнь по пути наружу; она останавливается у кладбища.\nОсторожно: заскриптованные группы связаны между собой и появляются только во время сопровождения, так что их нельзя зачистить заранее или выманивать по одной. Но зачистка обычных кентавров на пути перед началом помогает.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} стоит на краю места {area:596}, к юго-западу от места {area:2407}; {object:176751} лежат среди скелетов.",
		["{object:177787} lies beside {object:35251}, if you didn't take it on your first {zone:1443} visit. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} лежат рядом с объектом {object:35251}, если вы не взяли их при первом посещении зоны {zone:1443}. Его серебряный ключ падает с крабов Сухого Щелчка вокруг обломков корабля; золотой – с наг Скользящего Клинка на северо-западном побережье, далее.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley: keep it, for the level-48 {area:35} stop, with Zanzil's village"] = "«Морской Волк» Маккинли: оставьте его до остановки в {area:35} на 48-м уровне, вместе с деревней Занзила",
		["\"Stinky\" Ignatz"] = "«Вонючка» Игнац",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4732} обучает людей ({area:88}, восток зоны {zone:1429}) рядом с лошадьми, которых продает {npc:384}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4753} обучает ночных эльфов (город {zone:1457}) рядом с саблезубами, которых продает {npc:4730}: корабль ({area:17203} – {area:442}), затем полет в {area:702}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено), например у NPC {npc:4732} ({area:88}, зона {zone:1429}). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:4772} обучает дворфов ({area:803}, к востоку от поселка {area:131} по дороге в зону {zone:1432}) рядом с баранами, которых продает {npc:1261}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "На 40-м уровне, имея 100 золотых, можно научиться верховой езде, и при обучении вы получите транспорт. {npc:7954} обучает гномов ({area:189}, сразу к востоку от поселка {area:131}) рядом с механодолгоногами, которых продает {npc:7955}. Возможно, в Forever любая раса может учиться у любого учителя верховой езды (не подтверждено). Все цвета – в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["Bloodsail camp"] = "Лагерь шайки Кровавого Паруса",
		["Bloodsail pirates: kill these as you meet them"] = "Пираты Кровавого Паруса: убивайте их по пути",
		["Boat to {area:35}"] = "Корабль: {area:35}",
		["Cortello's scroll"] = "Свиток Кортелло",
		["Defeat the challengers and {npc:6238}"] = "Победите соперников и NPC {npc:6238}",
		["East from the stalkers' slopes to the ruins of Zul'Mamwe: the Skullsplitter Mystics (39-40) in its northern half carry {npc:739}'s fetishes. Careful: the Witch Doctors, Berserkers and Headhunters (41-44) hold the ruins' southern half: stay north. Then north-west toward the coast: the Shadowmaw Panthers (37-38) prowl the jungle west of the ruins, often stealthed."] = "Идите на восток от склонов охотников к руинам Зул'Мамве: у мистиков из племени Дробителей Черепов (39-40) в северной части руин есть фетиши для NPC {npc:739}. Осторожно: знахари, берсерки и охотники за головами (41-44) занимают южную часть руин: держитесь севера. Затем на северо-запад к побережью: тенебрюхие пантеры (37-38) бродят по джунглям к западу от руин, часто незаметно.",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye: take them from the Raiders and Mages (39-41) at the Bloodsail camp on the beach just north of town, where you found the letter. Leave the {area:43} camp south of town (Warlocks and Swashbucklers 41-43) for the level-48 visit."] = "С каждого пирата Кровавого Паруса падает нюхательный табак, а у одного из них – глаз, который нужен NPC {npc:2493}: добывайте их с налетчиков и магов (39-41) в лагере Кровавого Паруса на пляже чуть к северу от города, где вы нашли письмо. Лагерь к югу от города ({area:43}; чернокнижники и головорезы 41-43) оставьте до визита на 48-м уровне.",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Идите по дороге на восток назад в Терамор. Офицеры – в здании {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Идите по дороге на северо-запад из Терамора к сторожевой башне ({area:503}). По болоту вокруг нее бродят глинистые землеглоты.\n{npc:4967} ждет у подножия башни: осмотревшись, сдайте задание ему прямо там, а не в Тераморе.",
		["Gorilla hills"] = "Холмы горилл",
		["Head back down to town; Shaky stands at the tunnel mouth."] = "Возвращайтесь вниз в город; Трусишка стоит у входа в туннель.",
		["Head east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Идите на восток; перевитые ужасы по пути тоже роняют рассуждения. Обыщите край озера ({area:74}), где из воды поднимаются руины храма.",
		["Head inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets."] = "Идите вглубь суши к холмам горилл Мглистой долины. Потроха падают со старых горилл из Мглистой долины.",
		["Head north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "Идите на северо-восток мимо лагеря Несингвари и по дороге на север к лагерю в верхней части долины.",
		["Head south to the giant's hut in the middle of the marsh."] = "Идите на юг к хижине великана в середине болота.",
		["Jungle Stalkers"] = "Тропические ловцы",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.\nCareful: the Bloodsail Mages and Warlocks here are level 40-43 and cast from range: pull one at a time and fight with your back to the open beach."] = "Выйдите из города через туннель и идите вдоль побережья на север; письмо лежит в лагере шайки Кровавого Паруса на пляже, где ходит «Красавчик» Дункан.\nОсторожно: маги и чернокнижники Кровавого Паруса здесь 40-43 уровня и атакуют издалека: выманивайте по одному и сражайтесь спиной к открытому пляжу.",
		["Level 40 with 100 gold later on? {npc:4732} teaches riding at {area:88} in {zone:1429}: Collectibles, Mounts · Level 40 has the trip."] = "Позже будут 40-й уровень и 100 золотых? {npc:4732} обучает верховой езде ({area:88}, зона {zone:1429}): поездка описана в разделе «Коллекции», «Транспорт · 40-й уровень».",
		["Mirefin murlocs"] = "Мурлоки из племени Болотного Плавника",
		["North-east from the bay toward Nesingwary's camp: {npc:729}, the great tiger (37), lairs on the hilltop just south-west of the camp."] = "От залива на северо-восток к лагерю Несингвари: {npc:729}, огромный тигр (37), обитает на вершине холма чуть к юго-западу от лагеря.",
		["On the way north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "По пути на север в {area:392}: {area:720} лежит у берега ({area:391}) к югу от города, перейдите вброд по отмели. {npc:6236} по одному выпускает против вас четырех соперников, а затем – {npc:6238} (33-й уровень).",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Необязательно: свиток Кортелло лежит на одном из трех кораблей Кровавого Паруса, стоящих на якоре у берега чуть к югу от места {area:35}, на средней или нижней палубе, и не всегда на одном и том же корабле. Команды – пираты 42-45 уровня: расчищайте путь с края по одному и не трогайте капитанов (45-48) – за ними маршрут вернется на 48-м уровне.",
		["Paladin: {quest:1661}"] = "Паладин: {quest:1661}",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Верховая езда и буреноги: {npc:265756}, {area:17684} ({area:16638}) на острове Зефрис.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Seahorn's Bloodsail Buccaneers: keep it for the level-48 {area:35} stop, with the {area:43} camp."] = "«Пираты Кровавого Паруса» от Морского Рога: оставьте до остановки в {area:35} на 48-м уровне, вместе с лагерем ({area:43}).",
		["Seahorn's next errand goes back to Arathi: skip it."] = "Следующее поручение Морского Рога ведет обратно в Нагорье Арати: пропустите его.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Вонючка ждет к западу от усадьбы, на болоте под башней ({area:504}). Отведите его к листьям болотного боба и не подпускайте к нему болотных тварей.",
		["Stormwind City"] = "Штормград",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "Идите по дороге на север к разрушенной усадьбе; Ярл живет в лачуге рядом с ней, а рыхлая земля – у угла дома. Ярлу нужны три предмета ({quest:1218}): если вы проходили мимо NPC {npc:4897}, сначала купите их у нее на Тераморе.",
		["The Jungle Stalkers roam the slopes west of the mine."] = "Охотники джунглей бродят по склонам к западу от шахты.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Мурлоки из племени Болотного Плавника толпятся на северном побережье за усадьбой ({area:497}).",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Дезертиры стоят лагерем к югу от дороги, к западу от хижины {npc:4503}.",
		["The north-west coast"] = "Северо-западное побережье",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "Свиток лежит на болоте к северу от Биггса. С тинобродов к северу от него могут выпасть рассуждения Кадгара.",
		["The sunken temple"] = "Затонувший храм",
		["Theramore"] = "Терамор",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Upstairs"] = "Наверху",
		["Warlock: {quest:4488}"] = "Чернокнижник: {quest:4488}",
		["for Stoley in {zone:1446}: keep it; on the top floor"] = "для Столи (зона {zone:1446}): сохраните; на верхнем этаже",
		["for the {zone:1435} later"] = "для зоны {zone:1435}, позже",
		["for {area:1438}: keep it"] = "для места {area:1438}: сохраните",
		["for {npc:5635} at {area:348}: keep it"] = "для NPC {npc:5635} ({area:348}): сохраните",
		["for {npc:770} at the {area:99}, on the northern loop"] = "для NPC {npc:770} ({area:99}), на северном круге",
		["keep it: the {area:43} camp's charts and Swashbucklers (41-43) wait for the level-48 {area:35} stop"] = "оставьте его: карты и головорезы (41-43) из лагеря ({area:43}) подождут до остановки в {area:35} на 48-м уровне",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "только если у вас есть {item:3853} (изготавливает кузнец)",
		["with the spices from Theramore"] = "со специями из Терамора",
		["{area:702} flight master"] = "Распорядитель полетов: {area:702}",
		["{item:216616}, from the Subchiefs (or the Elites)"] = "{item:216616} – с помощников (или с элитных бойцов)",
		["{item:2466}, from the Skullsplitter Mystics"] = "{item:2466} – с мистиков из племени Дробителей Черепов",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}: для Ярла «Болотного Глаза»",
		["{item:5938}, from the Silt Crawlers"] = "{item:5938} – с иловых крабов",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} готовит в здании {object:2169}; {npc:5384} – {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: другие цвета, 20 з.",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440} – Королевская библиотека ({object:2117})",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, из гайда по Нагорью Арати (30-40)",
		["{npc:2486}'s Stranglethorn Fever ({npc:1514}) waits for the level-48 {area:35} stop: leave it for now."] = "Задание «Странглторнская лихорадка» от NPC {npc:2486} ({npc:1514}) подождет до остановки в {area:35} на 48-м уровне: пока оставьте его.",
		["{npc:2494}: keep it, its naga (43-44) wait for the level-48 {area:35} stop"] = "{npc:2494}: сохраните, его наги (43-44) ждут остановки ({area:35}) на 48-м уровне",
		["{npc:2498}, inside: keep it, Zanzil's village (43-44) waits for the level-48 {area:35} stop"] = "{npc:2498}, внутри: оставьте его, деревня Занзила (43-44) подождет до остановки ({area:35}) на 48-м уровне",
		["{npc:384}: other colours, 20g"] = "{npc:384}: другие цвета, 20 з.",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461} – {object:2164}: задание примет {npc:6251} ({area:392}) в конце следующего гайда",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: другие цвета, 20 з.",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} удерживает башню с несколькими дезертирами. Он нападет на вас: бейте его, пока он не сдастся.\nОсторожно: у Хендела два стражника, которые вступают в бой, когда он становится враждебным. Когда он сдается, стражники убегают.\n{npc:4967} и {npc:4968} ждут рядом с башней: когда он сдастся, сдайте задания обоим на месте.",
		["{npc:4967}, at the tower"] = "{npc:4967}, у башни",
		["{npc:5464}, by the flight master"] = "{npc:5464}, у распорядителя полетов",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637} – в зале Поисковой корпорации у здания {object:32356}, {npc:2786} – {object:32383}.",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171} – в Соборе Света",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Затем {npc:6236} предлагает задание «Ветростраж» (1791): цепочка оружия Вихря с элитным противником в конце описана в классовом гайде воина «Оружие Смерча».",
		["{npc:717}, beside them"] = "{npc:717} – рядом с ними",
		["{npc:718}, beside him"] = "{npc:718} – рядом с ним",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: для задания «{quest:2864}» (зона {zone:1446}), сохраните",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: другие цвета, 20 з.",
		["{quest:1218}: {npc:4897} in Theramore, if you left without them"] = "{quest:1218}: {npc:4897} в Тераморе, если вы ушли без них",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "Задание «{quest:1260}» – у таверны; {npc:4897}, поставщица в нескольких шагах к югу, продает специи, которые нужны Ярлу.",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
} end)()
t.guides["forever/alliance/40-50/01b-riverglades"] = (function() return {
		["About 90 quests in Forever's new zone, from {area:16724}: the level for its port and Western Front."] = "Около 90 заданий в новой зоне Forever, начиная с крепости {area:16724}: уровень для ее порта и Западного фронта.",
		["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "Возвращайтесь на восток через город к ферме Элбрима: кукла и медальон лежат в сгоревшем доме рядом с ней.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Обратно на север вдоль берега: по пути к ползунам сдайте мурлоков и шкуру на причалах.",
		["Back through the port"] = "Обратно через порт",
		["Back to the port, from the north pier west through the docks."] = "Возвращайтесь в порт: от северного пирса на запад через доки.",
		["Back to the port."] = "Возвращайтесь в порт.",
		["Coyote pelts"] = "Шкуры койотов",
		["Down to the port."] = "Спускайтесь в порт.",
		["Fly from {zone:1455} to {area:69} in Redridge, then follow the road north out of town and up through {area:2417}: it comes down into the western {zone:2548} by the {area:16737}."] = "Летите из города {zone:1455} в {area:69} (Красногорье), затем следуйте по дороге на север из города и через {area:2417}: она спускается в западную часть зоны {zone:2548} у местности {area:16737}.",
		["Into the {zone:2548}"] = "В зону {zone:2548}",
		["Level 44.4 on the Eastsea pirates"] = "Уровень 44.4 на пиратах Восточного моря",
		["North up the road to the lumber camp."] = "На север по дороге к лагерю лесорубов.",
		["North up the track towards {area:16729}: the foreman's crate lies by the road."] = "На север по тропе к локации {area:16729}: ящик бригадира лежит у дороги.",
		["One of Benjy's horses ran north up the river, past the farm. Give it the feed, then lead it home."] = "Одна из лошадей Бенджи убежала на север вверх по реке, мимо фермы. Дайте ей корм, затем отведите домой.",
		["Search around the stables south of the farmhouse for the horses' tracks; the bundles of hay lie around the farm."] = "Ищите следы лошадей вокруг конюшен к югу от фермерского дома; связки сена лежат по всей ферме.",
		["South back to {area:16724}."] = "Обратно на юг, в {area:16724}.",
		["The Eastsea pirates"] = "Пираты Восточного моря",
		["The Plains Coyotes roam west and south-west of the keep, towards {area:16725}."] = "Равнинные койоты бродят к западу и юго-западу от крепости, в сторону места {area:16725}.",
		["The Twilight cult"] = "Сумеречный культ",
		["The cathedral"] = "Собор",
		["The coyote den"] = "Логово койотов",
		["The lost horse"] = "Потерявшаяся лошадь",
		["The murlocs, south-west"] = "Мурлоки на юго-западе",
		["The pirates' second wave"] = "Вторая волна пиратов",
		["The pirates' ships"] = "Корабли пиратов",
		["The stables"] = "Конюшни",
		["The western {zone:2548}"] = "Запад зоны {zone:2548}",
		["The {area:16737}"] = "{area:16737}",
		["Train before the {zone:1418}"] = "Обучитесь перед зоной {zone:1418}",
		["grind on {npc:257901}"] = "убивайте: {npc:257901}",
		["the middle ship"] = "средний корабль",
		["the northern ship"] = "северный корабль",
		["the {object:645166} poster"] = "объявление «{object:645166}»",
		["{area:16735} and the river"] = "{area:16735} и река",
		["{item:268505}, the southern ship"] = "{item:268505}, южный корабль",
		["{item:269997}, on the graves"] = "{item:269997} – на могилах",
		["{quest:94879}, for later in this guide"] = "{quest:94879}, понадобится позже в этом гайде",
		["{quest:95122}: for later in this guide"] = "{quest:95122}: на потом, позже в этом гайде",
		["{quest:95123}: for later in this guide"] = "{quest:95123}: на потом, позже в этом гайде",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "С острова Терамор езжайте на север в зону {zone:1413}. Цель: {area:392}; если знаете этот маршрут полета, летите. {npc:6251} обучает в доме у банка.",
		["Raleigh's next errand is in the {area:796}: skip it."] = "Следующее поручение Ролея – здесь: {area:796}. Пропустите его.",
		["Ride back east to {area:1898}."] = "Езжайте обратно на восток. Цель: {area:1898}.",
		["Ride back north to Ironband's camp."] = "Езжайте обратно на север к Раскопкам Сталекрута.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Из места {area:271} езжайте по дороге на северо-восток во {zone:1425}; {area:348} – сразу за границей. {npc:5635} принимает наверху, у птичника – {quest:1450}, у таверны стоит {npc:7884}.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Езжайте на юг из зоны {zone:1432} через перевал в зону {zone:1418}; {npc:2860} стоит лагерем у раскопок.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "Следующее задание Разящего Когтя подождет до более позднего гайда по {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Обжигающие дракончики гнездятся в ущелье к востоку (ориентир: {npc:2888}); опаленных стражей (элита) не трогайте. {item:4612} падает редко: возьмите, если выпадет, пока вы фармите.",
		["The {area:1517} dig"] = "Раскопки: {area:1517}",
		["Theramore"] = "Остров Терамор",
		["Theramore flight master"] = "Распорядитель полетов: Терамор",
		["Warlock: {quest:3631}"] = "Чернокнижник: {quest:3631}",
		["Witherbark villages"] = "Деревни племени Сухокожих",
		["{area:144} flight master"] = "Распорядитель полетов: {area:144}",
		["{npc:1470} is below ground in {area:144}, by the inn, where the flight lands. His mushrooms grow in the {area:1517} dig at the {zone:1418}' northern edge, on this guide's loop back north."] = "{npc:1470} находится под землей в месте {area:144}, у таверны, куда прилетает грифон. Его грибы растут на раскопках ({area:1517}) у северного края зоны {zone:1418}, на обратном пути этого гайда на север.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}: следующее задание не дает опыта, пропустите его.",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}: Синие жемчужины из Тернистой долины",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} стоит лагерем в одиночестве ({area:1898}), к юго-востоку от раскопок.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}: следующее задание – охота на элиту, пропустите его.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} не стоит на месте ({area:342}): он со своими стражами обходит зону {zone:1418} по длинному кругу – от лагеря на западе вдоль юга зоны примерно до 61,69, затем на север примерно до 49,49 и обратно на запад к лагерю. Стрелка ведет по его маршруту на запад отсюда, пока вы его не встретите.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} стоит лагерем на дороге к востоку (ориентир: {area:348}).",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, наверху рядом с распорядителем полетов; внутри",
		["{quest:706}: its {item:4612} is a rare drop, so the work and hand-in are optional too"] = "{quest:706}: {item:4612} – редкая добыча, поэтому выполнение и сдача тоже необязательны",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Вернитесь сюда: {area:1117}. С любой наги из клана Гребня Ненависти там может выпасть чешуя.",
		["Boats to and from the island"] = "Корабли на остров и обратно",
		["Feathermoon's isle, ogres, yetis and the {area:1121}."] = "Остров Лунного Пера, огры, йети и {area:1121}.",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "От места {area:489} езжайте на запад по дороге к лагерю Зловещего Тотема к северу от нее. {npc:7956} ждет снаружи; освободите летучих хамелеонов из загона в центре и сохраните жизнь NPC {npc:7956} и хотя бы шести из них.",
		["Gordunni ogres"] = "Огры из клана Гордунни",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["Grimtotem tauren"] = "Таурены из племени Зловещего Тотема",
		["Grind to 45"] = "Гринд до 45",
		["Hatecrest naga"] = "Наги из клана Гребня Ненависти",
		["Ironfur bears"] = "Медведи-сталемехи",
		["No flight path to {area:489} yet: take the boat back to the coast and ride east along the road to {area:489}, on the {zone:1441} border."] = "Маршрута полета в {area:489} пока нет: плывите на корабле обратно на побережье и езжайте на восток по дороге в {area:489}, на границе зоны {zone:1441}.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.\nCareful: the {npc:5236} are 44-45 and the Warlocks 43-44, casters a level or two over you here: pull them one at a time from the camp's edge, and take the Brutes (42-43) on the slopes first."] = "Езжайте на восток к лагерю Гордунни на холмах к юго-востоку от долины йети: в лагере чернокнижники и шаманы, громилы бродят по склонам вокруг и севернее.\nОсторожно: {npc:5236} – 44-45-го уровня, а чернокнижники – 43-44-го, это заклинатели на уровень-два выше вас: выманивайте их по одному с края лагеря, а сначала займитесь громилами (42-43) на склонах.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Езжайте на север в долину йети. С любого йети со Свирепого Утеса может выпасть толстая шкура; {npc:5346} (уровень 48) рыщет в центре.",
		["Ride north out of {area:1105}: the Ironfur Bears (41-42) at the foot of the {area:1136} drop Rhapsody's last liver.\nCareful: Ironfur Patriarchs (48-49) and the Rage Scar yetis (46-49) roam the hills further north: stay at their edge."] = "Езжайте на север из места {area:1105}: с медведей-сталемехов (41-42) у подножия места {area:1136} выпадет последняя печень для Рапсодии.\nОсторожно: сталемехи-патриархи (48-49) и йети из Яростного Утеса (46-49) бродят по холмам севернее: держитесь на краю.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Езжайте на северо-восток к заставе ночных эльфов на границе зоны {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Езжайте на юго-восток к гноллам из стаи Древолапов; рюкзаки курьера лежат в их южном лагере, а посылка в них начинает доставку в {area:489}. Улей Зуккаш чуть южнее: пробейтесь к коконам, где держат Раскала, освободите его и сохраните ему жизнь на пути наружу.",
		["Ride to {area:489}"] = "Езжайте в {area:489}",
		["Ride west into {area:1105}: its yetis are 43-45. The Rage Scar yetis in the hills to the north are 46-49: leave them. Or, with a group, run the {area:978} dungeon instead."] = "Езжайте на запад: {area:1105}, там йети 43-45-го уровня. Йети из Яростного Утеса на холмах к северу – 46-49-го уровня: не трогайте их. Или, если есть группа, пройдите вместо этого подземелье {area:978}.",
		["Stays on the main route"] = "Остается на основном маршруте",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Плывите на корабле сюда: {area:1108}, и идите вдоль берега на юг к разбитой шлюпке на пляже.",
		["The courier's boat"] = "Лодка курьера",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121} – остров чуть южнее места {area:1120}: плывите туда. Там змеестражи и колдуньи из клана Гребня Ненависти; {npc:8136} (уровень 47) ждет в пещере на южном краю. Сначала выманите его стражу.",
		["Then on to {zone:1446}"] = "Затем в зону {zone:1446}",
		["Two new flight paths for later"] = "Два новых маршрута полета на будущее",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Идите на юг по острову к руинам наг; беседка стоит среди них.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "для Тиранды ({zone:1457}): маршрут приведет вас туда на 47-м уровне",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "гринд: {npc:5292}, {area:1105}, {zone:1444}",
		["{item:11463}, from the backpacks"] = "{item:11463}, из рюкзаков",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "Затем {npc:3936} просит отнести вести в {zone:1457}: пропустите, {area:976} сам отправит вас туда.",
		["{npc:3936}, beside him"] = "{npc:3936}, рядом с ним",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: его ответ ждет в месте {area:702}, позже",
		["{npc:7852}'s next order, Improved Quality, wants Rage Scar hides from yetis of 46-49: skip it."] = "Следующий заказ NPC {npc:7852}, «Повышение качества», требует шкуры йети из Яростного Утеса 46-49-го уровня: пропустите его.",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, на вершине крепости",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} ждет до конца круга по материку.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Class trainer"] = "Учитель классовых навыков",
		["Fly to {area:271}"] = "Лететь сюда: {area:271}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Идите вдоль побережья на юг к пиратской бухте. Пираты Южных морей заполонили пляж и корабли: двигайтесь по краю и выманивайте по одному. {npc:7883} стоит на дальней стороне; украденный груз ({npc:7881}) лежит в лагере.\nОсторожно: рядом с NPC {npc:7883} стоят два-три пирата, а как только начнется бой, к нему присоединятся многие пираты из городка.",
		["For your {area:978} run, later in this guide: {quest:2864} wants scarab shells, {npc:7407}, by the water tower, his {quest:2768} back, and Trenton Lighthammer Troll Temper from the Sandfury trolls."] = "Для подземелья {area:978}, позже в этом гайде: {quest:2864} просит панцири скарабеев, {npc:7407} у водонапорной башни – вернуть его {quest:2768}, а Трентон Легкий Молот – закалку троллей с троллей из племени Песчаной Бури.",
		["Gives the {item:8585}"] = "Дает: {item:8585}",
		["No flight path to {area:348} yet: ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border."] = "Маршрута полета сюда ({area:348}) еще нет: езжайте на северо-восток из места {area:271} по дороге в зону {zone:1425}; {area:348} – сразу за границей.",
		["Pool by {area:979}"] = "Пруд у места {area:979}",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Езжайте обратно на запад к месту {area:976}. По пути дюны занимают бандиты и воры из шайки Скитальцев Пустыни; у любого из них может быть бурдюк с водой.\nОсторожно: разбойники Скитальцев Пустыни (43-44-й уровень) передвигаются в незаметности, так что могут подойти незамеченными.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Езжайте на восток через дюны к гоблинской гавани на северо-восточном побережье.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool to tap it; the trolls stand close, so pull the nearest first.\nCareful: tapping the pool brings Scarabs (level 44-47) out of the sand to attack you: tap it, then step away from the trolls and fight the Scarabs one by one."] = "Езжайте на северо-запад к лагерю троллей из племени Песчаной Бури: {area:979}. Используйте {item:8584} у края пруда, чтобы найти воду; тролли стоят близко, так что выманивайте ближайших первыми.\nОсторожно: из песка вылезают скарабеи (44-47-го уровня) и нападают на вас: используйте устройство, затем отойдите от троллей и бейте скарабеев по одному.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Езжайте на юг к лагерю раскопок: {area:1938}. {npc:7771} дает вам шлем-детектор: наденьте его, чтобы видеть холмики ({quest:3161}); их много в песке вокруг лагеря и к юго-западу, в сторону огров.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Езжайте на юго-восток из места {area:439} в {zone:1446}. {area:976} — сразу за границей.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Пройдите через портал в {zone:1457}. Храм Луны – на юге города.",
		["Take the boat from {area:442}'s dock to {area:702}; {npc:3838}, the hippogryph master, stands on the rise just east of the landing: learn the flight path on the way up to the village."] = "Плывите на корабле от причала ({area:442}) сюда: {area:702}; {npc:3838}, распорядитель гиппогрифов, стоит на возвышении чуть восточнее пристани: откройте маршрут полета по пути наверх в деревню.",
		["Temple of the Moon"] = "Храм Луны",
		["The Wanted poster beside him"] = "Плакат «Розыск!» рядом с ним",
		["The little turtle {npc:5955} hides at the north end of the {quest:3362}: take him from the edge and leave the Thistleshrubs (48-50) alone. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "Маленький черепах {npc:5955} прячется в северной части долины ({quest:3362}): забирайте его с края и не трогайте кактусовых чудищ (48-50). Отведите его домой к жене ({npc:6015}), у воды чуть восточнее места {area:977}: он идет медленно, и звери пустыни нападают на него, так что берегите его.",
		["The pool by {area:979}"] = "Пруд у места {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "То же объявление: {npc:7847} будет гораздо позже, после места {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Более сильные разбойники, темные маги и убийцы из шайки Скитальцев Пустыни стоят лагерем к юго-востоку от места {area:976}, южнее бандитов. {npc:7847} в центре южного лагеря оставьте на потом.\nОсторожно: разбойники Скитальцев Пустыни вне боя остаются в незаметности, так что скрытые разбойники могут вмешаться в бой, начатый вами у лагеря.",
		["The {area:1938}"] = "Место: {area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, Zamek by the goblin camp."] = "{area:2240} находится здесь: {area:439}, на юго-востоке зоны {zone:1441}. {npc:4454} – в лагере гномов у трассы, Замек – у лагеря гоблинов.",
		["The {quest:2768}: {npc:7407}, by the water tower."] = "{quest:2768}: {npc:7407}, у водонапорной башни.",
		["The {quest:3042}: {npc:7804}, in town."] = "{quest:3042}: {npc:7804}, в городе.",
		["Your {area:978} scarab shells: {npc:7876}, on the north side of town."] = "Панцири скарабеев из подземелья {area:978}: {npc:7876}, в северной части города.",
		["keep it: the {area:982}'s Centipaar (48-50) wait for the Un'Goro guide's {area:976} landing at about 49.5"] = "оставьте его: центипаары (48-50) из места {area:982} подождут прибытия в {area:976} по гайду по Ун'Горо, примерно на 49,5 уровне",
		["the book on her table"] = "книга на ее столе",
		["the soil comes from {zone:1449}, later"] = "земля – из зоны {zone:1449}, позже",
		["{area:702} flight master"] = "Распорядитель полетов: {area:702}",
		["{area:976} flight master"] = "Распорядитель полетов: {area:976}",
		["{area:978} is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the pool.\nInside: the Scarabs drop the shells, every Sandfury troll can drop {quest:3042}, and {npc:7604} carries the {quest:2768}."] = "{area:978} – подземелье для группы из пяти игроков; его задания здесь – 45-47-го уровня. Ворота – примерно в 400 ярдах к северу от пруда.\nВнутри: со скарабеев падают панцири, с любого тролля из племени Песчаной Бури может упасть {quest:3042}, а {quest:2768} – у NPC {npc:7604}.",
		["{npc:11758}: keep it, the {area:983} waits for the same landing"] = "{npc:11758}: оставьте, {area:983} ждет того же прибытия",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, на вершине дерева",
		["{npc:5955}'s escort"] = "Сопровождение: {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, у водонапорной башни",
		["{npc:7408}, next to him"] = "{npc:7408}, рядом с ним",
		["{npc:7564}: keep it for the same landing"] = "{npc:7564}: оставьте до того же прибытия",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: его ящик едет в {area:702}, позже",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, в таверне порта; внутри",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} стоит этажом выше, над NPC {npc:7916}: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "Следующее поручение NPC {npc:7907} ведет в зону {zone:1446}: пропустите его.",
		["{npc:7916}: the feathers lie in the {zone:1425}, next"] = "{npc:7916}: перья лежат в зоне {zone:1425}, далее",
		["{quest:2768}: {npc:7604}, inside"] = "{quest:2768}: {npc:7604}, внутри",
		["{quest:2864}, north side of town"] = "{quest:2864}, северная часть городка",
		["{quest:2864}: keep it, the {quest:3362} waits for the Un'Goro guide's {area:976} landing"] = "{quest:2864}: оставьте его, задание «{quest:3362}» ждет прибытия в {area:976} по гайду по Ун'Горо",
		["{quest:2865}: the Scarabs, inside"] = "{quest:2865}: скарабеи, внутри",
		["{quest:3042}: the Sandfury trolls, inside"] = "{quest:3042}: тролли из племени Песчаной Бури, внутри",
		["{zone:1457} first, while you are on this side of the sea: Troyas' answer, {npc:7763}'s crate, Tyrande and the soil errand, then the boat from {area:442} to {area:150} and the gryphon to {area:348}."] = "Сначала город {zone:1457}, пока вы на этой стороне моря: ответ Тройаса, ящик NPC {npc:7763}, Тиранда и поручение с землей, затем корабль из места {area:442} в {area:150} и грифон до места {area:348}.",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["\"Sea Wolf\" MacKinley, if the Stranglethorn guide didn't give it"] = "«Морской Волк» Маккинли, если гайд по Тернистой долине его не выдал",
		["Class trainer"] = "Учитель классовых навыков",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {area:42}"] = "Летите в {area:42}",
		["Gorilla hills"] = "Холмы горилл",
		["Inside"] = "Внутри",
		["Leave town by the tunnel and ride north along the coast past the Bloodsail camp: the naga comb the beaches beyond it and drop the reeds."] = "Выйдите из города через туннель и езжайте на север вдоль побережья мимо лагеря Кровавого Паруса: дальше по пляжам бродят наги, с них падают тростники.",
		["MacKinley's next task sends you after elite ogres: skip it."] = "Следующее задание Маккинли отправляет вас к элитным ограм: пропустите его.",
		["Naga Explorers"] = "Наги-исследователи",
		["Ride back down to town."] = "Езжайте обратно вниз, в город.",
		["Ride back south-east to the Mistvale gorilla hills above {area:35}. {npc:1449} sits among the gorillas: take ten Gorilla Fangs from the Elder Mistvale Gorillas first."] = "Езжайте обратно на юго-восток к холмам горилл из Мглистой долины над местом {area:35}. {npc:1449} сидит среди горилл: сначала добудьте десять клыков гориллы со старых горилл из Мглистой долины.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Езжайте на север, в центр края {zone:1425}: {area:351}. Вокруг ползают зеленые слякочи и нефритовые слизнюки.\nОсторожно: по округе в незаметности бродят пантеры.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}."] = "Сначала езжайте дальше на восток по дороге к крепости: {item:6091} пропадет через час после места {area:42}.",
		["Ride on north along the coast to Zanzil's village. Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Езжайте дальше на север вдоль побережья к деревне Занзила. Мешанина может выпасть с любого последователя Занзила; {npc:2537} ходит в южной части лагеря.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Езжайте на юго-восток к месту {area:355}, ступенчатому храму племени Порочной Ветви на юге края {zone:1425}, и поднимитесь на вершину. Квиага и {npc:8636} (элита, 50) стоят наверху: коснитесь вершины и сразу спускайтесь.\nОсторожно: верхнюю площадку охраняют элитные тролли, в том числе {npc:7996} и {npc:8636}, а также несколько прорицателей из племени Порочной Ветви. Прорицатели применяют заклинания и связаны с остальной группой.",
		["The Bloodsail captains"] = "Капитаны шайки Кровавого Паруса",
		["The bloodmages"] = "Маги крови",
		["The charts and orders lie in the pirate camp on the {area:43}, just south of {area:35}; its Swashbucklers walk the shore. The Warlocks and Swashbucklers (41-43) are under you now."] = "Карты и приказы лежат в пиратском лагере на месте {area:43}, чуть южнее места {area:35}; его головорезы ходят по берегу. Чернокнижники и головорезы (41-43) теперь ниже вас по уровню.",
		["Tram to {zone:1453}"] = "Поезд до {zone:1453}",
		["Unbagwa's ritual"] = "Ритуал Унбагвы",
		["Wildkin feathers"] = "Перья диких совухов",
		["Zanzil's village"] = "Деревня Занзила",
		["for {npc:2616} in Theramore: keep it, the Un'Goro guide lands there"] = "для NPC {npc:2616} в Тераморе: сохраните, гайд по Ун'Горо начинается там",
		["for {quest:2990} at {area:1438}, later"] = "для NPC {quest:2990} ({area:1438}), позже",
		["{area:1537} inn"] = "Таверна: {area:1537}",
		["{npc:2487}, top floor"] = "{npc:2487} – верхний этаж",
		["{npc:2487}, top floor, if the Stranglethorn guide didn't give it"] = "{npc:2487}, верхний этаж, если гайд по Тернистой долине его не выдал",
		["{npc:2494}, if the Stranglethorn guide didn't give it"] = "{npc:2494}, если гайд по Тернистой долине его не выдал",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "Следующее поручение {npc:2498} про Занзила начинается в зоне {zone:1441}: пропустите его.",
		["{npc:2498}, inside, if the Stranglethorn guide didn't give it"] = "{npc:2498}, внутри, если гайд по Тернистой долине его не выдал",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} и {npc:2536}",
		["{npc:2535} and {npc:2536} stand together in the hills just north of Zanzil's village."] = "{npc:2535} и {npc:2536} стоят вместе в холмах чуть севернее деревни Занзила.",
		["{npc:7505}: keep the five, their beasts (48-53) wait for the level-52 {zone:1419} stop"] = "{npc:7505}: оставьте все пять заданий, их звери (48-53) подождут остановки в зоне {zone:1419} на 52-м уровне",
		["{npc:7916}'s Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam: pick them up as you ride between the altar and {area:351}."] = "Перья диких совухов для NPC {npc:7916} лежат на земле по всей зоне {zone:1425}, к югу и востоку от места {area:348}, где бродят совухи: подбирайте их, проезжая между алтарем и местом {area:351}.",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "Следующее поручение {npc:8022}, {item:9471}, — задание для подземелья {area:978}: пропустите.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, на вершине крепости",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Для NPC {npc:8256} ({zone:1455}), в конце этого гайда",
		["Four rune rubbings in {zone:1447}: keep it"] = "Четыре оттиска рун в локации {zone:1447}: сохраните задание",
		["Golems and elementals"] = "Големы и элементали",
		["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Тяжелые боевые големы патрулируют дно Котлована под NPC {npc:8479}; среди них плавают элементали магмы. Масло падает с големов и элементалей, сердца – с элементалей.",
		["Searing Lava Spiders"] = "Опаляющие лавовые пауки",
		["The Grimesilt outhouse"] = "Нужник Карьера Грязнули",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "Следующее задание пленника, «Учетная книга из Танариса» ({zone:1446}), ведет в {zone:1435} и {zone:1445}: пропустите.",
		["The {object:179827} board"] = "Доска: {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:8436} stands inside the Twilight camp at {area:1442}, west of {area:1446}, among Twilight Fire Guards, Idolaters and Geomancers (level 48-49 elites), with {npc:8282} (level 51, rare elite) beside him: {quest:3377} needs a group of 4. Skip it if you are alone."] = "Это элитные противники: лучше собраться в группу, поищите, с кем пойти. {npc:8436} стоит в лагере Сумеречного Молота ({area:1442}), к западу от места {area:1446}, среди стражей огня, идолопоклонников и геомантов из культа Сумеречного Молота (элитные противники 48-49 уровня), а рядом с ним – {npc:8282} (51-й уровень, редкий элитный): для задания «{quest:3377}» нужна группа из 4 человек. Если вы один, пропустите его.",
		["Xiggs waits in the {object:32359}."] = "Ксиггс ждет в районе {object:32359}.",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} открывается на севере Котлована. Тайные планы лежат на его верхнем уступе; пламезавры плавают в лавовых озерах дальше внутри, так что выманивайте их к краю. Держитесь подальше от NPC {npc:14621} и его элитной стражи в глубине.",
		["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479} стоит на краю Котлована, к югу от места {area:1446}. Выслушайте его историю.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: слизни водятся в локации {zone:1448}, сохраните задание",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Back east to {npc:9619} with the glands."] = "Обратно на восток к NPC {npc:9619} с железами.",
		["Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."] = "Скопления кристаллов есть по всему кратеру. Смоляные господины в ямах (53-54) и слизни вокруг них (50-54) сильнее вас: собирайте кристаллы на северо-восточной окраине джунглей, среди хлыстунов и молодых зверей (48-50).",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Завершается у NPC {npc:9298} (зона {zone:1452}): сохраните",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["For characters of 49 to 50, but most quests here are level 51-53: on purpose, for their experience. This first visit keeps to the crater's eastern half, where the beasts are 48-52, so pull them one at a time; the pylons, the bones and the hive wait for the later Un'Goro visit at about 56."] = "Для персонажей 49-50 уровня, но большинство заданий здесь 51-53 уровня: намеренно, ради опыта. Этот первый визит ограничен восточной половиной кратера, где звери 48-52 уровня, так что выманивайте их по одному; пилоны, кости и улей подождут следующего визита в Ун'Горо примерно на 56 уровне.",
		["For {npc:7740} in {zone:1457}, at the end of the {zone:1428} guide: keep it"] = "Для NPC {npc:7740} ({zone:1457}), в конце гайда по зоне {zone:1428}: сохраните",
		["For {npc:7775} in {zone:1444}: keep it"] = "Для NPC {npc:7775} (зона {zone:1444}): сохраните",
		["Lar'korwi Mates and the raft"] = "Самки Лар'корви и плот",
		["Ride back north-east to {area:976}: {npc:11758} stands on the east side of town."] = "Езжайте обратно на северо-восток в {area:976}: {npc:11758} стоит в восточной части города.",
		["Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and {quest:3764}. Crystal clusters stand all over the crater, many around the foot of {area:537}: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of {area:537}, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\n{npc:9998}'s scales: the {npc:9165} (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."] = "Езжайте на восток в восточные джунгли: с кровоцветов-хлыстунов и молотильщиков (48-50) падают лепестки и {quest:3764}. Скопления кристаллов есть по всему кратеру, многие – у подножия хребта ({area:537}): возьмите по несколько лишних каждого цвета.\nОсторожно: по вершине хребта ({area:537}) ходят Живые пламена (54-55), а кровоцветы-живодеры и ловцы (51-53) занимают юг джунглей: собирайте кристаллы у подножия хребта, а лепестки – на севере.\nЧешуя для NPC {npc:9998}: {npc:9165} (48-50) парят над северо-востоком джунглей, а рядом пасутся молодые деметродоны (49-50). Их всего десять: деметродоны (51) на западной окраине джунглей, чуть западнее молотильщиков, тоже дают чешую. Они на уровень выше вас: бейте их по одному.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Езжайте на юг мимо места {area:1938} к месту {area:981} – туннелям Хаззали; снаряжение Холстомера лежит глубоко внутри.\nОсторожно: снаряжение охраняет один жук. По туннелям патрулирует много жуков, некоторые из них 50-го уровня, так что в бою часто привлекаются лишние противники.",
		["Ride south to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Езжайте на юг к лагерю огров. Он полон громил и силовиков (46-48); {npc:12046} (49) стоит в центре с охраной: сначала разберитесь с ней.",
		["Ride west into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley.\nCareful: the thistleshrubs wander a lot, so you can easily pull extra mobs."] = "Езжайте на запад к месту {quest:3362}. Железы падают с собирателей росы; полные бывают не всегда, так что берите наполненную. В долине также бродят бугристые шипошкуры и корнеформовщики.\nОсторожно: шипошкуры много бродят, так что легко нацеплять лишних мобов.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Езжайте на запад из города {area:976} к длинному спуску в зону {zone:1449}. {npc:9619} стоит лагерем у подножия спуска, в юго-восточном углу кратера.",
		["Ride west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Езжайте на запад к улью сентипааров в дюнах. С любого сентипаара могут выпасть части насекомых.\nОсторожно: членистоноги-сентипаары призывают {npc:4196} и в бою, и вне боя – появляются мелкие помощники, которые прерывают вас.",
		["Still short of level 49.79 after the refuge's hand-ins? Top up on the Bloodpetal Lashers and Threshers (48-50) of the eastern jungle, where you took the petals, before you leave the crater."] = "После сдачи заданий в лагере все еще не хватает до уровня 49.79? Доберите опыт на кровоцветах-хлыстунах и молотильщиках (48-50) в восточных джунглях, где собирали лепестки, прежде чем покинуть кратер.",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Самки Лар'корви рыщут по джунглям к западу от {npc:9619}. Разбитый плот лежит там на берегу озера; маленький рюкзак – в воде рядом с ним. Компас, карту и ключ сохраните для NPC {npc:8737}. С любого зверя в кратере может выпасть {item:11116}: щелкните по нему правой кнопкой.",
		["The dead Threshadon lies by the water north of {npc:9619}.\nCareful: Venomhide Ravasaurs (50-51) hunt along the water there: pull them one at a time before you loot the carcass.\nAny ravasaur may drop a {item:280459}: right-click it, {npc:9619} takes it."] = "Мертвый молотильщик лежит у воды к северу от NPC {npc:9619}.\nОсторожно: там у воды охотятся ядовитые равазавры (50-51): выманивайте их по одному, прежде чем обыскать тушу.\nС любого равазавра может выпасть {item:280459}: нажмите на нее правой кнопкой, {npc:9619} ее примет.",
		["The flight from Theramore lands in {area:976}."] = "Полет из Терамора приземляется в городе {area:976}.",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 56"] = "Шкуры носят гориллы на плато ({area:1943}): сохраните для второго визита в Ун'Горо, около 56-го уровня",
		["The {zone:1455} quests were taken at the end of the {zone:1427} guide: fly straight on to {zone:1440} for {zone:1447}."] = "Задания из зоны {zone:1455} были взяты в конце гайда по зоне {zone:1427}: летите сразу дальше в зону {zone:1440}, чтобы попасть в зону {zone:1447}.",
		["Theramore flight master"] = "Распорядитель полетов: Терамор",
		["To {zone:1455}"] = "В таверну: {zone:1455}",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Вы пропустили это при прошлом посещении этих мест по маршруту: теперь это идёт первым. Это быстро и открывает следующие задания.",
		["{area:537} and the eastern jungle"] = "{area:537} и восточные джунгли",
		["{area:541} flight master"] = "Распорядитель полетов ({area:541})",
		["{item:11316}, from the Lashers and Threshers"] = "{item:11316} – с хлыстунов и молотильщиков",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: для Огтинка (зона {zone:1447}), сохраните",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} стоит на причале, куда прибывает корабль.",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737} – в глубине лагеря",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117} – в глубине пещеры; под землей",
		["{npc:9272}, {npc:9271}, {npc:9270} and {npc:9618} have quests among mobs of 51-55: leave them for the later Un'Goro visit, at about 56."] = "У NPC {npc:9272}, {npc:9271}, {npc:9270} и {npc:9618} есть задания на мобов 51-55 уровня: оставьте их на следующий визит в Ун'Горо, около 56-го уровня.",
		["{npc:9998}: his scales come from the young beasts of the eastern jungle"] = "{npc:9998}: его чешуя падает с молодых зверей восточных джунглей",
		["{quest:3764}, from the Threshers and the dirt piles"] = "{quest:3764} – с молотильщиков и из куч земли",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Аркессон стоит рядом с королем Магни ({object:171709}).",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Аркессон стоит рядом с королем Магни ({object:171709}): реликвии, которые вы прочли в Пылающих степях, – для него.",
		["Ardalan is inside {area:1438}."] = "Ардалан находится внутри крепости ({area:1438}).",
		["Back to the {zone:1419}"] = "Назад в зону {zone:1419}",
		["Below ground"] = "Под землей",
		["Bloodmages' camp"] = "Лагерь магов крови",
		["East along the road to {area:1235}"] = "На восток по дороге: {area:1235}",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Завершается заданием «{quest:4808}» ({area:2255}, {zone:1452}): сохраните",
		["Fly to {area:1438}"] = "Летите в {area:1438}",
		["Fly to {area:144}"] = "Летите сюда: {area:144}",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Fly to {area:1537}"] = "Лететь в {area:1537}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:69}"] = "Летите сюда: {area:69}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Идите по дороге на запад, затем поднимитесь на север к лагерю гоблинов: {area:251}.",
		["For {npc:5594} in {area:976}, on the {zone:1422} guide: keep it"] = "Для NPC {npc:5594} ({area:976}) из гайда по зоне {zone:1422}: сохраните задание",
		["For {zone:1453}: keep it"] = "Для города {zone:1453}: сохраните задание",
		["From {area:415}, ride east along the road past {area:2358} into {zone:1447}: {area:1235} lies just over the border, in {zone:1447}'s south-west corner."] = "Из города {area:415} езжайте на восток по дороге мимо места {area:2358} в зону {zone:1447}: {area:1235} – сразу за границей, в юго-западном углу зоны {zone:1447}.",
		["Hearth back to {zone:1455}'s inn."] = "Вернитесь камнем возвращения в таверну ({zone:1455}).",
		["Into {zone:1447}"] = "В зону {zone:1447}",
		["Level 51.3 on the way north"] = "Уровень 51.3 по пути на север",
		["Level 52 at {area:249}"] = "Уровень 52 у места {area:249}",
		["Listen to his tale, then ride back south to Kum'isha."] = "Выслушайте его рассказ, затем езжайте назад на юг к Кум'ише.",
		["Mosshoof Coursers"] = "Мохоногие олени",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "Откройте {item:10569} из зоны {zone:1427}, чтобы достать {item:10575}, затем скажите NPC {npc:9459}, что принесли доказательство своих подвигов: сражаться с драконом не придется.",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Ride back east along the road to the Vigil."] = "Езжайте по дороге назад на восток к Дозору.",
		["Ride back south to the camp."] = "Езжайте назад на юг к лагерю.",
		["Ride east out of {area:69} and up the pass into the {zone:1428}: {area:2418} stands at the top."] = "Езжайте на восток из места {area:69} и вверх по перевалу в зону {zone:1428}: {area:2418} – наверху.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Езжайте на север из зоны {zone:1419} в зону {zone:1435}: {npc:10996} стоит у дороги, ведущей из зоны {zone:1419}. Держитесь подальше от места {area:75} – это город Орды на северо-востоке.",
		["Ride north to the bloodmages' camp beside the road into the {zone:1419}."] = "Езжайте на север к лагерю магов крови у дороги в зону {zone:1419}.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Езжайте от святилища на северо-восток: {npc:8405} стоит лагерем здесь – {area:1224}, в холмах над дорогой.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Доплывите до островка у южной оконечности зоны {zone:1447}. Если NPC {npc:8392} там нет, подайте ему сигнал из предмета {item:10444} и дождитесь, пока он приземлится.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side.\nCareful: Escaped Core Hounds (level 60) roam the Steppes, a few on the slopes west and south of {area:249}: pull the ogres on the rock itself and look around before each pull."] = "Огры из клана Огненного Чрева занимают большую скалу к северу от Дозора, громилы – на ее восточной стороне.\nОсторожно: по Степям бродят сбежавшие гончие Недр (60-й уровень), несколько – на склонах к западу и югу от места {area:249}: выманивайте огров на самой скале и осматривайтесь перед каждым нападением.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s runes stand among the ruins: use his {item:10445} on each. The naga here are the ones the top-up below asks for, so these kills count towards it."] = "Наги из клана Бича Злобы ({area:1221}) носят предмет {item:13815}. Руны, которые нужны NPC {npc:8507}, стоят среди руин: используйте на каждой его {item:10445}. Здешние наги – те самые, которых требует добор опыта ниже, так что эти убийства засчитываются.",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "Вторая ступень заданий магов крови платит за те же части предметом-усилением без опыта: пропустите.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south.\nCareful: the Mosshoof Coursers are 52-53, a level or two over you here: pull them one at a time from the herd's edge."] = "Ближайшие мохоногие олени пасутся в холмах к северо-востоку от места {area:1224}, в сторону места {area:1219}; стадо побольше бродит по открытой местности на юге.\nОсторожно: мохоногие олени – 52-53 уровня, на уровень-два выше вас: выманивайте их по одному с края стада.",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "Портал в деревне {area:702} ведет наверх, в город {zone:1457}: {npc:9047} ждет в анклаве ({area:1658}) на севере города.",
		["The relics are in the {zone:1428}: keep it"] = "Реликвии – в зоне {zone:1428}: сохраните",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered. Take the ones on the ruins' southern edge, nearest {area:251}.\nCareful: the ruins' War Reavers and Thaurissan Firewalkers are 53-55, and {npc:8978} (57) holds the {object:147516} camp south-west of {area:251}: take the relics at the edge of the ruins, pull one at a time, and keep away from the camp."] = "Реликвии – резные камни, разбросанные по месту {area:250} вокруг места {area:251}: нажимайте на них, пока сведения не будут восстановлены. Берите те, что на южном краю руин, ближе к месту {area:251}.\nОсторожно: боевые разорители и огнеходы Тауриссана – 53-55 уровня, а {npc:8978} (57) занимает лагерь ({object:147516}) к юго-западу от места {area:251}: берите реликвии с края руин, выманивайте по одному и держитесь подальше от лагеря.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "Святилище лежит в юго-западном углу зоны {zone:1447}, к югу от заставы ({area:3137}).",
		["The wildkin are in {zone:1452}: keep it"] = "Дикие совухи – в зоне {zone:1452}: сохраните",
		["The {area:1221}"] = "{area:1221}",
		["To {zone:1455}"] = "В таверну: {zone:1455}",
		["Top up first to level 52 on the Firegut Ogres (50-51) on the near side of {area:249}, north of the Vigil: the Brutes on its east side are 52-53. Or, with a group, run the {area:1417} dungeon instead."] = "Сначала доберите опыт до уровня 52 на ограх из клана Огненного Чрева (50-51) на ближней стороне места {area:249}, к северу от Дозора: громилы на восточной стороне – 52-53 уровня. Или, с группой, пройдите вместо этого подземелье {area:1417}.",
		["Top up to level 51.3 on the Spitelash Myrmidons (50-51) of the ruins between {npc:8395}'s camp and the north: the blood elves at {npc:8420}'s camp are 51-53. Or, with a group, run the {area:1417} dungeon instead."] = "Доберите опыт до уровня 51.3 на мирмидонах из клана Бича Злобы (50-51) в руинах между лагерем NPC {npc:8395} и севером: эльфы крови в лагере NPC {npc:8420} – 51-53 уровня. Или, с группой, пройдите вместо этого подземелье {area:1417}.",
		["Upstairs"] = "Наверху",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves.\nCareful: a {npc:8981} (level 56, rare) walks the slopes by the broodlings, and the {npc:7040} and Wyrmkin around them are elite: use the Incarcinatrix on a broodling at the edge and look around before each pull."] = "Используйте {item:12284} на существе {npc:7047} на склонах к востоку от места {area:251} прямо перед его смертью, затем заберите оставшуюся эссенцию.\nОсторожно: {npc:8981} (56-й уровень, редкий) ходит по склонам у детенышей, а {npc:7040} и драконы вокруг них – элитные: используйте инкарцинатор на детеныше с краю и осматривайтесь перед каждым нападением.",
		["Your Hearthstone is set at {zone:1455} (the {zone:1425} guide binds it there): hearth back to the inn."] = "Ваш камень возвращения привязан к городу {zone:1455} (его привязывает там гайд по зоне {zone:1425}): вернитесь в таверну.",
		["grind on {npc:7033}"] = "охота: {npc:7033}",
		["keep it: the {area:199} cauldron waits for the {zone:1452} guide's Chillwind stop, at about 55"] = "сохраните: котел ({area:199}) ждет остановки в лагере Промозглого Ветра в гайде по зоне {zone:1452}, примерно на 55",
		["{area:144} flight master"] = "Распорядитель полетов: {area:144}",
		["{item:10575}, from the hoard"] = "{item:10575}, из клада",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, около 10%",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "Призрак {npc:10778} бродит у дома ({area:199}) к западу от места {area:200}; ее посылка лежит внутри.",
		["{npc:7740} stands beside Tyrande in the Temple of the Moon, in the south of the city."] = "{npc:7740} стоит рядом с Тирандой в Храме Луны, на юге города.",
		["{npc:7740}: {quest:162}, from {area:976}"] = "{npc:7740}: {quest:162}, из места {area:976}",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} стоит наверху, над NPC {npc:7916}: поднимитесь внутри здания, стрелка не различает этажи.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, в анклаве ({area:1658})",
		["{npc:9177}' next tasks ({npc:9176}, and fifty Blackrock Medallions) send you among the Blackrock orcs of 55-58 at the foot of {area:254}: skip them."] = "Следующие задания NPC {npc:9177} ({npc:9176} и пятьдесят медальонов Черной горы) отправят вас к оркам Черной горы 55-58 уровня у подножия места {area:254}: пропустите их.",
		["{quest:3701} is a group quest at this level: its relics stand among War Reavers and Firewalkers of 53-55, with {npc:8978} (57) close by, two to five over you, and the route has no later {zone:1428} visit. Grouping up is encouraged, look for people to do it with. Skip it if you are alone."] = "«{quest:3701}» на этом уровне – групповое задание: реликвии стоят среди боевых разорителей и огнеходов 53-55 уровня, рядом {npc:8978} (57), на два-пять уровней выше вас, а в зону {zone:1428} маршрут больше не вернется. Лучше собрать группу, поищите, с кем пойти. Если вы один, пропустите.",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
		["{zone:1455} has no druid trainer"] = "В городе {zone:1455} нет учителя друидов",
		["{zone:1455} inn"] = "Таверна: {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Под землей",
		["Careful: {npc:9454} (54) stands at the back of the {area:2481}, at about 32.2,67.1, with Shadowstalkers around him: clear them one at a time, then pull him alone at full health."] = "Осторожно: {npc:9454} (54) стоит в глубине руин ({area:2481}), около 32.2,67.1, а вокруг него – крадущиеся в тени: убивайте их по одному, затем выманите его одного при полном здоровье.",
		["Ends in the {zone:1413}: keep it"] = "Завершается здесь: {zone:1413} – сохраните задание",
		["First crater"] = "Первый кратер",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them.\nCareful: an {npc:7136} (53, elite) stands among the craters: walk round it."] = "Идите по дороге на север в долину с кратерами и обойдите каждый кратер, убивая по пути энтропических зверей и энтропических ужасов.\nОсторожно: среди кратеров стоит {npc:7136} (53, элитный): обойдите его.",
		["Ride north up the road from the Sanctuary, all the way to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Езжайте от Святилища по дороге на север, до самого входа в пещеру ({area:1769}); его охраняет {npc:15395}.",
		["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {zone:1448}."] = "Езжайте на юго-восток ({area:1763} → {area:2479}) к лагерю друидов у дороги на юге зоны {zone:1448}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Сальфа стоит у выхода из туннеля в зону {zone:1452}: сохраните задание",
		["Second crater"] = "Второй кратер",
		["Step into the cave: {npc:11558} stands just inside."] = "Войдите в пещеру: {npc:11558} стоит сразу у входа.",
		["Still short of level 52.9 after the {area:2479}'s hand-ins? Top up on the Entropic Beasts in {area:1766}, the next stop north."] = "После сдачи заданий ({area:2479}) все еще не хватает до уровня 52.9? Доберите опыт на энтропических зверях здесь: {area:1766}, следующая остановка к северу.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Фурболги из племени Мертвого Леса живут в деревне чуть юго-западнее (ориентир: {npc:11554}); сохраняйте перья из головного убора Мертвого Леса, которые с них падают.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. Keep killing them until one drops a {quest:8470}, about one kill in thirty, then right-click it: {npc:11558} in {area:1769} takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 58.\nCareful: Den Watchers are level 53-54 and the Avengers 54-55; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Фурболги Мертвого Леса из места {area:1762} заполняют холмы к западу от пещеры. Убивайте их, пока с одного не упадет {quest:8470} (примерно один на тридцать), затем щелкните по нему правой кнопкой: {npc:11558} ({area:1769}) примет его, когда Древобрюхи станут к вам равнодушны – сейчас, если уже, или когда последний гайд снова пройдет мимо пещеры на 58-м уровне.\nОсторожно: стражи логова – 53-54 уровня, мстители – 54-55; при здоровье ниже 50% они зовут союзников в радиусе 25 м, а ниже 15% убегают за помощью.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Сатиры из племени Нефритового Пламени занимают долину к западу от дороги; {npc:9454} – в ее глубине.\nОсторожно: ночные охотники из племени Нефритового Пламени (51–52-й уровень) используют Крадущийся шаг и {spell:7992} и находятся в незаметности, поэтому часто вмешиваются в бой.\nПроклятые слизнюки ползают по ручьям долины: убивайте их и используйте на останках пустой флакон, полученный у Лариса.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "{item:11503} носят древни-криводревы ({area:1767}, к востоку от места {area:2618}).",
		["The vial is filled in {zone:1457}: keep it; inside"] = "Склянка наполняется здесь: {zone:1457} – сохраните задание; внутри",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "Третий кратер",
		["{area:1763} again"] = "Снова: {area:1763}",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}.\nCareful: {npc:10648} (55) stands at the valley's far end with Hellcallers (53-54) around him: clear them one at a time before you pull him."] = "{area:2618} – долина сатиров на северо-западе; {npc:10648} – в ее дальнем конце. С него падает {quest:939}; с любого сатира из племени Нефритового Пламени может упасть {item:11674}.\nОсторожно: {npc:10648} (55) стоит в дальнем конце долины, а вокруг него – призыватели ада (53-54): убейте их по одному, прежде чем выманивать его.",
		["{area:702} flight master"] = "Распорядитель полетов: {area:702}",
		["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}: нечистые слизнюки ползают по озерам скверны ({area:1763})",
		["{npc:10924}: for {npc:11079} in {zone:1452}, keep it"] = "{npc:10924}: для NPC {npc:11079} в зоне {zone:1452}, сохраните",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Фурболг {npc:11554} стоит у дороги чуть южнее места {area:2479}.",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}: Древобрюхи разговаривают с вами только начиная с уровня «Равнодушие»; ходит здесь: ищите внутри круга на карте",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} ждет в северной части зоны {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528} – в руинах чуть восточнее (ориентир: {npc:11554})",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Any furbolg here can drop an {item:12771} (about one in ten: it comes within the kills these quests need) and a {quest:8471} (about one in thirty): right-click whichever drops. Keep the {item:14047} the furbolgs drop for Meilosh."] = "С любого фурболга здесь может выпасть {item:12771} (примерно один из десяти: попадется за то число убийств, что нужно для этих заданий) и {quest:8471} (примерно один из тридцати): щелкните правой кнопкой мыши по выпавшему. Сохраните {item:14047}, которая падает с фурболгов, для Мелиоша.",
		["Back to the hills: only the Ice Thistle Matriarchs (56-57) and Patriarchs (57-58) carry the horns.\nCareful: take the Matriarchs at the edge of the hills, one at a time, and leave the Patriarchs: their horns drop from both."] = "Обратно на холмы: рога есть только у матриархов (56-57) и патриархов (57-58) ледополохов.\nОсторожно: бейте матриархов на краю холмов по одному, а патриархов не трогайте: рога падают с обоих.",
		["Back to {npc:11053} at {area:3197}."] = "Вернитесь к NPC {npc:11053} ({area:3197}).",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Fly to {area:3197}"] = "Летите сюда: {area:3197}",
		["Follow the road east across the zone to the chapel."] = "Идите по дороге на восток через всю зону к часовне.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Идите по дороге на запад к лагерю {npc:9298} у горячих источников.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Идите по южной дороге на восток в зону {zone:1423}; руины ({area:2262}) лежат к югу от нее. Призрак {npc:10926} играет у разрушенного дома в южной части.",
		["For Kernda in {area:1769}: keep it"] = "Для Кернды ({area:1769}): сохраните",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}.\nCareful: the Ice Thistle Yetis are 55-56 and the Chimaeras 55-57: take the Rogue Ice Thistles (53-55) and the Fledgling Chillwinds (53-55) at the edge of the hills, and leave the Chillwind Ravagers (57-59) alone."] = "Йети с Холмов ледополоха живут на холмах к югу от места {area:2244}, хладноветрые химеры — в долине по пути к месту {area:2255}.\nОсторожно: йети с Холмов ледополоха 55-56-го уровня, а химеры 55-57-го: бейте ледополохов-разбойников (53-55) и стылодыхов-слетков (53-55) на краю холмов, а хладновеев-опустошителей (57-59) не трогайте.",
		["Inside"] = "Внутри",
		["Its jars are filled on the {zone:1451} guide's Un'Goro visit: keep it"] = "Банки наполняются во время визита в Ун'Горо по гайду {zone:1451}: сохраните",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Сохраните: Греган ({zone:1444}) позже сварит эликсир",
		["Level 55 at {area:2246}"] = "55-й уровень у места {area:2246}",
		["North-west out of the camp to {area:199}, west of Andorhal: {npc:11075} (53) guards the cauldron among the Jabbering Ghouls (54)."] = "Из лагеря на северо-запад, сюда: {area:199}, к западу от Андорала: {npc:11075} (53) охраняет котел среди болтливых вурдалаков (54).",
		["On the road east out of {area:3197}, {npc:10927}'s farmhouse stands on {area:197}: her {quest:5142} goes to the same ghost in {area:2262}."] = "На дороге на восток от места {area:3197} стоит дом NPC {npc:10927} ({area:197}): ее задание {quest:5142} ведет к тому же призраку ({area:2262}).",
		["On {npc:10978}, by the inn"] = "Взяв задание у NPC {npc:10978}, у таверны",
		["Pristine Yeti Horns"] = "Нетронутые рога йети",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Чистое Сердце, Дума, Доблестный Кулак и Макдоннел стоят в центре лагеря, у распорядителя полетов.",
		["Scare {npc:10978} with {item:12928}"] = "Напугайте {npc:10978} с помощью предмета {item:12928}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "Котел Мертвого Леса ({zone:1448}): сохраните",
		["The next guide starts here and flies to {area:3197}."] = "Следующий гайд начинается здесь и ведет полетом сюда: {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Руины окружают замерзшее озеро к югу от места {area:2253}. Подберите четыре фрагмента реликвий, лежащих в руинах, и светолунные перья на земле там, где бродят дикие совухи.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Три части куклы лежат в разрушенных домах ({area:2262}); если подобрать одну, могут появиться призраки. Соедините их в куклу.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Top up here first to level 55 on its Pathfinders (53-54) at the camp's edge: the Den Watchers inside are 55-56. Killing them raises your Timbermaw reputation and fills your bags with {item:14047} for Meilosh. Or, with a group, run {area:1584} or {area:2577} instead."] = "Западный лагерь племени Зимней Спячки стоит на холмах между NPC {npc:11556} и {npc:9298}. Сначала доберите здесь 55-й уровень на следопытах (53-54) на краю лагеря: дозорные логова внутри — 55-56-го уровня. Их убийство повышает репутацию у Древобрюхих и наполняет сумки предметом {item:14047} для Мелиоша. Или, если есть группа, пройдите вместо этого {area:1584} или {area:2577}.",
		["To {zone:1455}"] = "В таверну: {zone:1455}",
		["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56. Grind the Winterfall furbolgs camped by {area:2246} (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through {area:1769} need, one of them drops the {quest:8471}, and they fill your bags with the thirty Runecloth Meilosh asks for. Or, with a group, run {area:1584} or {area:2577} instead."] = "Доберите здесь 55.05 уровня перед сдачей заданий в месте {area:2255}: они поднимут вас до 56-го. Убивайте фурболгов Зимней Спячки у места {area:2246} (следопытов, тотемщиков, дозорных логова): это повышает репутацию у Древобрюхих, нужную для здешних заданий и прохода через {area:1769}, с одного из них падает {quest:8471}, а еще они наполнят сумки тридцатью рунными тканями для Мелиоша. Или, если есть группа, пройдите вместо этого {area:1584} или {area:2577}.",
		["Your Hearthstone is not set at {zone:1455} (the {zone:1425} guide binds there, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "Ваш камень возвращения не привязан к месту {zone:1455} (гайд по зоне {zone:1425} привязывает вас там, и этот гайд покидает зону {zone:1452} через него): вместо этого привяжитесь здесь ({area:2255}), чтобы возвращаться в город.",
		["Your Hearthstone is still set at {zone:1455}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "Ваш камень возвращения все еще привязан к месту {zone:1455}: оттуда полет на грифоне сюда ({area:3197}) примерно на десять минут быстрее, чем перелет отсюда ({area:2255}) на Терамор и корабль.",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Зельдарр — элитный: лучше собрать группу. Он ждет на самом дне ({area:2261}) — склепа на юго-западе зоны.",
		["{area:199} cauldron"] = "Котел: {area:199}",
		["{area:2255}'s inn"] = "Таверна ({area:2255})",
		["{npc:10431}: keep it for the Plaguelands; inside"] = "{npc:10431}: сохраните для Чумных земель; внутри",
		["{npc:10926}'s doll"] = "Кукла {npc:10926}",
		["{npc:10927}: keep it for {area:2262}"] = "{npc:10927}: сохраните для места {area:2262}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} и {npc:10977} будут позже",
		["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038}: Заэльдарр – элитный противник 54-го уровня",
		["{npc:11063}'s next task, at {area:2264}, is among Scourge of 57-60: skip it."] = "Следующее задание NPC {npc:11063} ({area:2264}) — среди Плети 57-60-го уровня: пропустите его.",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} стоит прямо у выхода туннеля ({area:1769}) в край {zone:1452}, там, где вы выходите.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: термиты будут позже, здесь: {area:2627}",
		["{npc:9616} works in the {object:32356}: hand him {zone:1448}'s ooze jars now, on your way through."] = "{npc:9616} работает в месте {object:32356}: отдайте ему банки со слизью из зоны {zone:1448} сейчас, по пути.",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, {zone:1422}: сохраните",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
		["{zone:1455} inn"] = "Таверна: {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["After the farm's keys: the {object:177289} stands just south-west of the farmhouse, and its Cauldron Lord beside it carries the key."] = "После ключей фермы: {object:177289} стоит чуть к юго-западу от фермерского дома, а ключ у его повелителя котла рядом.",
		["Andorhal"] = "Андорал",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Назад в лагерь {npc:7775}, чуть к юго-востоку от {npc:7765}: за {item:11242} вы получите три эликсира Видере. Сохраните их: {npc:9298} берет один, а {npc:9299} ({area:976}) показывается только тому, кто выпил эликсир.",
		["Below ground"] = "Под землей",
		["Bones and equipment"] = "Кости и оборудование",
		["Careful: the Frenzied Plaguehounds are 57-58: pull them one at a time."] = "Осторожно: бесноватые чумные псы 57–58-го уровня, выманивайте их по одному.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Перейдите реку на восток к {area:2261} – склепу на юго-западе зоны. {object:177667} лежит внутри: ключ от него у персонажа {npc:12248} на дальнем северо-востоке, это будет в следующем гайде.\nОсторожно: вместе с Меркуцио появляются около четырех неэлитных помощников. Они идут к могиле, а не появляются на месте.",
		["Cross the river west to {npc:1855}'s hut."] = "Перейдите реку на запад к хижине {npc:1855}.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Пересеките юг кратера и вернитесь к {npc:9619} у спуска.",
		["Diseased Grizzlies"] = "Болезненные гризли",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Землечерпы роются в дюнах к северо-западу от крепости; повсюду бродят камнехвостые скорпиды и песчаные пауки-быстроноги.",
		["Eastern Pylon and the crate"] = "Восточный пилон и ящик",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Завершается у NPC {npc:9298} (зона {zone:1452}): сохраните",
		["Escort {npc:9999}"] = "Сопроводите NPC {npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Летите из места {area:976} сюда: {area:541}. {npc:8737} стоит в глубине убежища; {npc:9117} – в пещере за ним.\nДруг {npc:9997}, {npc:9999}, пропал.",
		["Fly to Theramore"] = "Лететь на остров Терамор",
		["Fly to {area:2268}"] = "Летите сюда: {area:2268}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:392}"] = "Летите сюда: {area:392}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["For the druids of {zone:1457}: keep it"] = "Для друидов ({zone:1457}): сохраните задание",
		["For {area:3197}: keep it"] = "Для места {area:3197}: сохраните задание",
		["For {zone:1448}: keep it"] = "Для зоны {zone:1448}: сохраните задание",
		["For {zone:1451}: keep it"] = "Для зоны {zone:1451}: сохраните задание",
		["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "Из Терамора езжайте на запад ({zone:1413}) и на север вдоль побережья сюда: {area:392}.",
		["From {area:702}, fly to {area:1116}."] = "Летите: {area:702} → {area:1116}.",
		["Hearth to {area:392} (bound there earlier on this guide), then fly on to {area:976}."] = "Используйте камень возвращения ({area:392}, вы привязались там ранее в этом гайде), затем летите дальше: {area:976}.",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "Череп Хоргуса лежит здесь: {area:2624}, а меч Мардука – здесь: {area:2623}; оба там, где сражаются призраки. На равнинах между ними охотятся взрослые чумные псы.",
		["Inside"] = "Внутри",
		["Into {zone:1451}"] = "В зону {zone:1451}",
		["Listen to his story"] = "Выслушайте его историю",
		["MacDonnell's next task, {area:201}'s cauldron, waits for the {zone:1451} guide's Plaguelands leg: take it then."] = "Следующее задание Макдонелл, котел ({area:201}), ждет части гайда {zone:1451} в Чумных землях: возьмите его тогда.",
		["Mark {npc:10902} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "Отметьте предметом {item:12815}: {npc:10905}",
		["More watches"] = "Еще часы",
		["North to the refuge, for the quests the first Un'Goro visit left: {npc:9618} stands just outside and {npc:9117} in the cave at the back; the expedition's other three wait for your next stop here."] = "На север к убежищу – за заданиями, оставшимися с первого визита в Ун'Горо: {npc:9618} стоит прямо у входа, а {npc:9117} – в пещере в глубине; трое других членов экспедиции подождут вашей следующей остановки здесь.",
		["Northern Pylon"] = "Северный пилон",
		["On {npc:7583}"] = "У персонажа {npc:7583}",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Ranshalla in {zone:1452}: keep it"] = "Раншалла ({zone:1452}): сохраните задание",
		["Ride back south to the camp."] = "Езжайте назад на юг к лагерю.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Езжайте обратно на юго-запад к башне ({area:2742}, {area:2738}); поднимитесь на нее и убейте засаду, которая появляется ради покрытого коркой предмета.",
		["Ride back to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Езжайте обратно сюда: {area:3425}. {npc:15189} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Езжайте на восток к пограничной реке: {npc:1855} живет в маленькой хижине на берегу.",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Езжайте на восток: {area:1943}, где робот стоит среди горилл. Не заходите там в глубокую пещеру.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Езжайте на восток к вулкану ({area:537}), поднимитесь на него и используйте {npc:10541} у лавовых отдушин у вершины.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Езжайте на север по восточной стороне к плато горилл. {npc:9622}, горилла 55-го уровня, сидит в самой глубокой пещере: сначала перебейте горилл у входа.",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.\nCareful: the Frenzied Plaguehounds north-east of the hut are 57-58, a level or two over you: pull them one at a time."] = "Скачите на север сюда: {area:2627}. {npc:12384} живет в разрушенной хижине, а его книга расписок лежит в разрушенной таверне поблизости.\nОсторожно: бесноватые чумные псы к северо-востоку от хижины 57-58-го уровня, на уровень-два выше вас: атакуйте их по одному.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Езжайте по дороге на север к Лесопилке Северного Кряжа; {npc:11610} прячется на краю лагеря.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Езжайте на северо-запад к ферме Далсона. Дневник лежит в амбаре; ключ от нужника носит бродячий скелет, а {npc:10836} ждет в нужнике с ключом от шкафчика.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Езжайте на северо-запад: {area:2276}, на краю зоны {area:2277}.",
		["Ride on west to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Езжайте дальше на запад: {area:3425}. {npc:15189} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["Ride south-west to the camp."] = "Езжайте на юго-запад к лагерю.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Езжайте на юго-запад к лагерю ({npc:7771}): {area:1938}.",
		["Ride west along the road to the hot springs."] = "Езжайте по дороге на запад к горячим источникам.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Езжайте на запад в Руины Воронова Ветра: {npc:7774} прячется в маленьком круглом здании в глубине. Откройте сундук рядом с ней ради предмета {item:9189}: он действует 15 минут, как и задание.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Езжайте на запад: {area:2627}. По лесам бродят карликовые чумные псы, чумные нетопыри и личинки-падальщики; наполните предмет {item:15042} у больших термитников и убейте бесноватых чумных псов дальше к северу.",
		["Scare {npc:7583} with {item:12928}"] = "Напугайте {npc:7583} с помощью предмета {item:12928}",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones while you wear the {quest:5401} (equip it as a trinket first).\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Скелеты-живодеры и слюнявые вурдалаки бродят по полям к северу от лагеря; вся Плеть здесь роняет камни Плети, пока на вас {quest:5401} (сначала наденьте его как аксессуар).\nОсторожно: эта нежить замечает вас издалека, а другая нежить рядом вступает в бой, когда вы атакуете одного.\nОсторожно: {npc:10411} (3 места появления, возрождение 15 мин) невидимо вне боя и призывает горгулий Крыла Скалы, как только начинается бой.",
		["Take the boat to the mainland and ride north-east past the {area:1119} to {npc:7775}'s camp. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "Плывите на корабле на материк и езжайте на северо-восток мимо места {area:1119} к лагерю {npc:7775}. Он варит {item:11243} из предмета {item:11242}: возьмите его поручение ради него.",
		["Ten {item:11040} from the {item:11020}"] = "Десять шт. {item:11040} из предмета {item:11020}",
		["The Andorhal watchtowers"] = "Сторожевые башни Андорала",
		["The Gorishi hive"] = "Улей Гориши",
		["The Scarlet Crusade"] = "Алый орден",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Медики, охотники, рыцари и маги из Алого ордена патрулируют лесопилку и дорогу к месту {area:190}.",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Смоляные чудища и смоляные повелители барахтаются здесь: {area:538} – к югу от убежища, по пути вниз в кратер.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "Котел стоит у фермы {npc:10739}: {area:202}.",
		["The crater"] = "Кратер",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Гориллы живут здесь: {area:1943}, чуть к востоку от пилона. Соберите шкуры для {npc:9619} сейчас, пока вы наверху. Не заходите в самую глубокую пещеру: {npc:9622} – 55-го уровня.\nОсторожно: гориллы Ун'Горо (50–51-го уровня), потеряв 75% здоровья, зовут на помощь союзников в радиусе 20 ярдов. В этой местности есть пещера, полная обезьян, и бой там привлечет много противников.",
		["The pelts come from the gorillas on {area:1943}"] = "Шкуры – с горилл на плато: {area:1943}",
		["The pylon stands on the eastern cliffs above {npc:9684}'s lair; the expedition's {item:11113} sits at the abandoned camp in the eastern jungle."] = "Пилон стоит на восточных утесах над логовом зверя {npc:9684}; {item:11113} экспедиции – в заброшенном лагере в восточных джунглях.",
		["The pylon stands on the western cliffs."] = "Пилон стоит на западных утесах.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Истерзанные друиды и часовые бродят по разрушенной деревне к юго-западу от {npc:13220}.",
		["The wooden sign beside {npc:9997}"] = "Деревянная табличка рядом с NPC {npc:9997}",
		["The {area:2742} tower"] = "Башня: {area:2742}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "{item:11242} растет внутри разрушенного здания к северу от {npc:7765}: заберитесь внутрь через пролом в стене с уступа рядом.",
		["Umber in {area:493}: keep it"] = "Умбер ({area:493}): сохраните задание",
		["Upstairs"] = "Наверху",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}.\nCareful: the Temporal Parasites are 55-57, and Skeletal Warlords and Flesh Golems (57, elites) walk the streets: draw the parasites out by the silos, one at a time, and let the elites pass."] = "Используйте {item:12627} у зернохранилищ, чтобы выманить временных паразитов. {quest:5154} – один из пыльных томов в ратуше. С каждого скелета в городе падает {quest:5537}.\nОсторожно: временные паразиты 55-57-го уровня, а по улицам ходят скелеты-вожди и мясные големы (57, элита): выманивайте паразитов у зернохранилищ по одному и пропускайте элиту.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp.\nCareful: Skeletal Warlords and Flesh Golems (57, elites) walk Andorhal's streets, and the {npc:7572} (59, elite) wanders between Andorhal and Northridge: keep to the towers at the town's edge and let them pass."] = "Используйте {item:12815} у подножия каждой из четырех сторожевых башен по краю Андорала, к северу от лагеря.\nОсторожно: скелеты-вожди и мясные големы (57, элита) ходят по улицам Андорала, а {npc:7572} (59, элита) бродит между Андоралом и Северным Кряжем: держитесь башен на краю города и пропускайте их.",
		["Walk into {area:1769} and take the {area:493} branch of the tunnel to {area:2361}."] = "Войдите сюда: {area:1769} – и идите по ответвлению туннеля в зону {area:493}, до места {area:2361}.",
		["West across the south of the crater: Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from the Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "На запад через южную часть кратера: кости динозавров лежат на земле на юго-западе, среди стегодонов. Они элитные: подбирайте кости вокруг них, а остальные добудьте с диметродонов. {item:11112} экспедиции лежит в юго-западных джунглях.",
		["West along the south of the crater: the Gorishi hive fills it. Use the Scraping Vial on a hatchery, a chamber with hanging larvae."] = "На запад вдоль южной части кратера: ее занимает улей силитидов Гориши. Используйте пузырек для соскоба в инкубаторе – камере со свисающими личинками.",
		["Western Pylon"] = "Западный пилон",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."] = "Вы пропустили это при прошлом посещении этих мест по маршруту: теперь это идёт первым. Это быстро и открывает следующие задания.",
		["their trainers are in {zone:1457} too"] = "их учителя тоже в городе {zone:1457}",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: убивайте их по пути",
		["{area:202} cauldron"] = "Котел: {area:202}",
		["{area:702} flight master"] = "Распорядитель полетов: {area:702}",
		["{area:976} flight master"] = "Распорядитель полетов: {area:976}",
		["{item:12841}: wear the {quest:5401} while you kill"] = "{item:12841}: убивайте, надев {quest:5401}",
		["{item:12894}, at the monument"] = "{item:12894} – у памятника",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} лежит в ратуше ({area:190}) к западу от {npc:1855}: стражи Алого ордена стоят плотно.",
		["{item:14613}, from {npc:11886} (57, elite): grouping up is advised"] = "{item:14613}, с NPC {npc:11886} (57, элитный): лучше собрать группу",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} ждет в разрушенной таверне в западной части Андорала.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} и {npc:7740} стоят у Храма Луны; наполните {item:11682} у лунного колодца внутри.",
		["{npc:10897}, {area:493}'s flight master, stands south of the lake, outside {area:2361}: learn the flight path now; the {zone:2482} guide flies to {area:493}, and the {zone:1451} guide comes back here."] = "{npc:10897}, распорядитель полетов зоны {area:493}, стоит к югу от озера, за пределами места {area:2361}. Откройте маршрут полета сейчас: гайд по зоне {zone:2482} летит сюда ({area:493}), а гайд по зоне {zone:1451} возвращается сюда.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "Дом {npc:10927} стоит на холме к востоку от лагеря; памятник ({npc:10936}) – чуть севернее.",
		["{npc:11610}'s next task, {npc:11613} and {npc:11611}, waits for the {zone:1451} guide's Plaguelands leg: take it then."] = "Следующее задание NPC {npc:11610}, {npc:11613} и {npc:11611}, ждет части гайда {zone:1451} в Чумных землях: возьмите его тогда.",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} – элитный противник: лучше собрать группу",
		["{npc:15189}'s and {npc:15191}'s next tasks (the Stonelash scorpids and the Dredge Crushers) wait for the {zone:1451} guide's {area:3425} stop: take them then."] = "Следующие поручения {npc:15189} и {npc:15191} (скорпиды Каменного Хлыста и земляные сокрушители) ждут остановки в месте {area:3425} в гайде по зоне {zone:1451}: возьмите их тогда.",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} – элитный противник 61-го уровня",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} ({area:976}): сохраните задание",
		["{npc:5901}, on the coast north of town"] = "{npc:5901} – на побережье к северу от города",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: сохраните задание для места {area:976}",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: сохраните задание для зоны {zone:1446}",
		["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496}: сохраните задание для Кратера Ун'Горо; внутри",
		["{npc:8598}, 170 yd north-east"] = "{npc:8598} – 170 ярдов к северо-востоку",
		["{npc:9299} in {area:976}: keep it"] = "{npc:9299} ({area:976}): сохраните задание",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299} – призрак на кладбище чуть к востоку от городка: выпейте там {item:11243} (он вас убьет), освободите дух и поговорите с ним в облике призрака. Затем бегите обратно к телу, чтобы ожить: надгробие стоит неподалеку.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Логово зверя {npc:9684} – в джунглях к северу от {npc:9619}, под восточными утесами: используйте там {item:11568}. {npc:9684} – 56-го уровня: начинайте бой с полным здоровьем.",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} сидит на юго-восточном склоне вулкана ({area:537}) в середине кратера.",
		["{object:175924}, in the farmhouse; inside"] = "{object:175924} – в доме; внутри",
		["{quest:3444} is in {area:392}"] = "{quest:3444} – здесь: {area:392}",
		["{quest:4291}, if you still carry it from the first visit"] = "{quest:4291}, если оно еще осталось с первого визита",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210} ({area:2268}): сохраните задание",
		["{quest:6762} in {area:493}: keep it"] = "{quest:6762} ({area:493}): сохраните задание",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, где следующий гайд посещает учителей, не имеет учителя друидов",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Андорал",
		["Angerclaw bears and Felpaw wolves"] = "Медведи злобных когтей и волки-сквернолапы",
		["Araj is elite: grouping up is advised."] = "Араж – элитный противник: лучше собрать группу.",
		["Below ground"] = "Под землей",
		["Boat to {area:150}"] = "Корабль: {area:150}",
		["Bronzebeard's Encampment"] = "Лагерь Бронзоборода",
		["Careful: Ancient Irontree Walkers, level 59 elites, stand among the {quest:5086}: work the Horrors at the camp's north-east tip (about 50.6,22.4), one at a time, and look for a walker before each pull."] = "Осторожно: древние железнолесные ходоки, элитные противники 59-го уровня, стоят среди целей задания «{quest:5086}»: бейте ужасов на северо-восточной оконечности лагеря (около 50.6,22.4) по одному и перед каждым нападением высматривайте ходока.",
		["Careful: the Twilight Keepers are level 60, a level or two over you: clear the cultists around each one first and fight the keeper at full health.\n{npc:11803} holds the cultists' camp in the far south-west."] = "Осторожно: Сумеречные хранители 60 уровня, на уровень-два выше вас: сначала перебейте культистов вокруг каждого и сражайтесь с хранителем при полном здоровье.\n{npc:11803} занимает лагерь культистов на дальнем юго-западе.",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Поднимитесь в центре кратера: {area:537} – и используйте {item:14644} у лавового озера наверху, имея в сумках два ториевых слитка. Наполните чистые флаконы для образцов от {npc:9616} на первобытных слизнюках в водоемах вокруг гряды.",
		["Cross the river east of {npc:1855}'s hut into {area:2627}: {npc:11140} stands by Augustus' ruined hut."] = "Перейдите реку к востоку от хижины NPC {npc:1855}: {area:2627}. {npc:11140} стоит у разрушенной хижины Августа.",
		["Fly from {area:541} to {area:392}."] = "Летите: {area:541} → {area:392}.",
		["Fly to {area:150}"] = "Летите сюда: {area:150}",
		["Fly to {area:1537}"] = "Лететь сюда: {area:1537}",
		["Fly to {area:271}"] = "Летите сюда: {area:271}",
		["Fly to {area:3137}"] = "Летите сюда: {area:3137}",
		["Fly to {area:3425}"] = "Летите сюда: {area:3425}",
		["Fly to {area:442}"] = "Летите сюда: {area:442}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["Fly to {area:976}."] = "Летите сюда: {area:976}.",
		["Fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Летите сюда: {area:976}. Купите здесь на аукционе два ториевых слитка для задания «{quest:5801}».",
		["Fly to {zone:1453}"] = "Лететь в {zone:1453}",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north.\nCareful: Ancient Irontree Walkers, level 59 elites, stand among the treants in the middle of {area:1767}: take the Stompers on the north side (about 48,21)."] = "Идите по дороге на север: {area:1767}. Сердце носят топотуны Железнолесья; когти доберите с гризли злобных когтей и опустошителей-сквернолапов на севере.\nОсторожно: древние железнолесные ходоки, элитные противники 59-го уровня, стоят среди древней в центре ({area:1767}): бейте топотунов на северной стороне (примерно 48,21).",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Следуйте указаниям {npc:9298} ко входу сюда: {area:2256}, мимо великанов ледяного молота: проходите мимо них по одному.",
		["For {npc:10778}: keep it"] = "Для персонажа {npc:10778}: сохраните задание",
		["For {npc:11053} at {area:3197}, at the end of this guide"] = "Для персонажа {npc:11053} ({area:3197}), в конце этого гайда",
		["From the hold, west into the sands: Dredge Crushers dig there; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "От крепости на запад в пески: там копают земляные сокрушители; в тех же песках охотятся камнехвостые клешневики, живодеры и скальные пауки-скакуны.",
		["From {area:3137} ride into {zone:1448}: the {area:2479} is the druids' camp on the road just past the {zone:1440} border."] = "От места {area:3137} езжайте в {zone:1448}: {area:2479} – лагерь друидов на дороге сразу за границей зоны {zone:1440}.",
		["Hand him the ten texts you kept"] = "Отдайте ему десять сохраненных текстов",
		["Havunth's camp sits just west of {area:3425}.\nCareful: Havunth is level 60: clear his camp first and fight him at full health."] = "Лагерь Хавунта находится чуть западнее (ориентир: {area:3425}).\nОсторожно: Хавунт 60 уровня: сначала зачистите его лагерь и сражайтесь с ним при полном здоровье.",
		["Inside"] = "Внутри",
		["Irontree Stompers"] = "Топотуны Железнолесья",
		["Its jars are filled on the Un'Goro visit"] = "Его флаконы наполняются при посещении Кратера Ун'Горо",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Сохраните {item:11169}, когти и сердце, которые он вернет",
		["Lots of flying between zones"] = "Много перелетов между зонами",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Подберите припасы вокруг повозки и заберите амулет {npc:10301} у совухов поблизости.",
		["Portal to {zone:1438}"] = "Портал: {zone:1438}",
		["Radley and Durgen"] = "Рэдли и Дурген",
		["Ride back south along the road to the Sanctuary."] = "Езжайте по дороге назад на юг к Святилищу.",
		["Ride back south-east to the hermit."] = "Езжайте назад на юго-восток к отшельнику.",
		["Ride back south-west to {area:3197}."] = "Езжайте назад на юго-запад: {area:3197}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Езжайте на восток в холмы. Используйте {item:11169}, чтобы призвать: {quest:4005}, затем победите его ради тотема.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Езжайте на восток к руинам ({area:2738}). {object:179565} лежит среди разрушенных зданий под охраной истерзанных часовых.",
		["Ride north along the west side to Mayna's small camp.\nCareful: Mayna is level 60: clear her camp first and fight her at full health."] = "Езжайте на север вдоль западного края к небольшому лагерю Майны.\nОсторожно: Майна 60 уровня: сначала зачистите ее лагерь и сражайтесь с ней при полном здоровье.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Езжайте на север к деревне фурболгов из племени Мертвого Леса у входа в пещеру ({area:1769}).",
		["Ride north to the {area:2277}'s north-eastern edge.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Езжайте на север к северо-восточному краю места {area:2277}.\nОсторожно: тролли на пути к месту {area:2273} – 57-59-го уровня. При малом здоровье они убегают и зовут на помощь, поэтому часто приводят подкрепление.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Езжайте на север: {area:541}. Используйте {npc:10980} рядом с персонажем {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Езжайте по дороге на север к лесопилке и поставьте бочку с термитами в ее центре.",
		["Ride north-west up the road to {area:2253}."] = "Езжайте на северо-запад вверх по дороге: {area:2253}.",
		["Ride south out of {zone:1448} toward {area:3137}: {npc:3848}'s camp at {area:2358} is just over the {zone:1440} border, on the way."] = "Езжайте на юг из зоны {zone:1448} к месту {area:3137}: лагерь NPC {npc:3848} ({area:2358}) – сразу за границей зоны {zone:1440}, по пути.",
		["Ride south-east from the lake to the chapel."] = "Езжайте на юго-восток от озера к часовне.",
		["Ride south-east to {area:201}: {npc:11078} guards the cauldron, and {item:12955} lies east of the barn."] = "Езжайте на юго-восток: {area:201}. {npc:11078} охраняет котел, а {item:12955} лежит к востоку от амбара.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand south-east of the camp, where Deathclasp, an elite scorpid, patrols: grab it while he is away."] = "Езжайте на юго-запад к лагерю дворфов у южных гор и расспросите: {npc:15171} и {npc:15170}. Сумка {npc:15190} лежит в песке к юго-востоку от лагеря, где патрулирует Deathclasp, элитный скорпид: заберите ее, пока его нет рядом.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Езжайте на юго-запад: {area:2261}. Холмик земли – внутри. {npc:11886} – элитный противник: лучше собрать группу.\nОсторожно: вместе с Меркуцио появляются около четырех неэлитных помощников. Они идут к могиле, а не появляются на месте.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Езжайте на юго-запад к лагерю ({npc:7771}): {area:1938}.",
		["Scourge Champions"] = "Воители Плети",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Воители Плети (59) бродят здесь: {area:2270}, к северу от места {area:2268}. Проводите предметом {item:13156} {npc:11063} над каждым убитым: нужны ему черепа, которые резонируют. Выманивайте по одному.",
		["Stays on the main route"] = "Остается на основном маршруте",
		["Take the portal up to {zone:1457}."] = "Поднимитесь через портал: {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Спуститесь по дороге на запад в кратер и езжайте к месту {area:540} – пещере силитидов на юге. {npc:10041} ждет в самом дальнем зале.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Войдите в туннель ({area:1769}) со стороны зоны {zone:1452}, к западу от {npc:9298}, и идите по ответвлению ({area:493}) до места {area:2361}. {npc:11939} занимается исследованиями на берегу озера.",
		["Takes you all the way to 60"] = "Ведет вас до самого 60-го уровня",
		["Ten more for {quest:8323}"] = "Еще десять для задания «{quest:8323}»",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later.\nCareful: take the texts from the Twilight Avengers and Geolords; leave the Twilight Flamereavers (60) and stay out of the hive's mouth, where the {area:2742} elites (59-60) wait."] = "Раскопки культа Сумеречного Молота занимают северо-западный угол: фрагменты табличек лежат на земле, их также носят пылевихри и пустынные грохотуны. С любого культиста может упасть {item:20404}: сохраните двадцать – десять для персонажа {npc:15306} и десять позже для персонажа {npc:15194}.\nОсторожно: добывайте тексты с мстителей и геолордов из культа Сумеречного Молота; не трогайте пламехватов из культа Сумеречного Молота (60) и не подходите к входу в улей, где ждут элитные мобы ({area:2742}, 59-60).",
		["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "Полет заканчивается здесь: {area:702}. {npc:7916} стоит недалеко к северо-западу от распорядителя полетов.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "Отшельник прячется среди скал к юго-востоку (ориентир: {area:2738}).",
		["The {area:2479}"] = "{area:2479}",
		["The {area:3098}"] = "{area:3098}",
		["Theramore flight master"] = "Распорядитель полетов: Терамор",
		["Tram to {zone:1455}"] = "Поезд до {zone:1455}",
		["Twilight Tablet Fragments"] = "Фрагменты Сумеречной таблички",
		["Twilight's Hammer cultists"] = "Культисты Сумеречного Молота",
		["Underwater"] = "Под водой",
		["Upstairs"] = "Наверху",
		["Use the jars on slain oozes"] = "Используйте флаконы на убитых слизнюках",
		["Wait a moment for {npc:9116}"] = "Подождите немного {npc:9116}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "убивайте мобов ({npc:14564}): {area:2627}, {zone:1423}",
		["{area:1770} braziers"] = "Жаровни: {area:1770}",
		["{area:190} overlook"] = "Обзорная точка: {area:190}",
		["{area:493} flight path on the way"] = "По пути – маршрут полета ({area:493})",
		["{area:541} flight master"] = "Распорядитель полетов ({area:541})",
		["{area:702} flight master"] = "Распорядитель полетов: {area:702}",
		["{area:976} flight master"] = "Распорядитель полетов: {area:976}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}: с воителей Плети",
		["{npc:10300} waits at {area:2250}, south of {area:2255}.\nProtect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "{npc:10300} ждет здесь: {area:2250}, к югу от места {area:2255}.\nЗащищайте персонажа {npc:10300}, пока она зажигает факелы по пути сюда: {object:177404}.",
		["{npc:10301}'s camp"] = "Лагерь {npc:10301}",
		["{npc:10301}'s supplies"] = "Припасы {npc:10301}",
		["{npc:10667} in Andorhal: keep it"] = "{npc:10667} в Андорале: сохраните задание",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} ждет в разрушенной таверне в западной части Андорала – разрушенного города к северу от лагеря. {npc:1852} охраняет свою филактерию в центре города.",
		["{npc:10667} waits upstairs in the ruined inn on the west side of Andorhal, on the way back to {area:3197}."] = "{npc:10667} ждет на верхнем этаже разрушенной таверны в западной части Андорала, по пути обратно сюда: {area:3197}.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "Призрак {npc:10778} бродит у дома ({area:199}) к западу от Андорала. Вторую половину амулета носят болтливые вурдалаки на поле: соедините обе половины.",
		["{npc:10897}, {area:493}'s flight master, stands south of the lake, outside {area:2361}: learn the flight path from him. The flight master in {area:2361} itself flies only Druids, from her gossip, and has no flight path to learn."] = "{npc:10897}, распорядитель полетов ({area:493}), стоит к югу от озера, за пределами зоны {area:2361}: откройте у него маршрут полета. Распорядитель полетов в самой зоне {area:2361} перевозит только друидов (через диалог), и маршрута полета у нее не открыть.",
		["{npc:11038}, by the graves south of the chapel: {npc:11140} is in {area:2627}, keep it"] = "{npc:11038}, у могил к югу от часовни: {npc:11140} – здесь: {area:2627}, сохраните",
		["{npc:11053}: {area:201}'s cauldron, on this loop"] = "{npc:11053}: котел ({area:201}), на этом круге",
		["{npc:11556}'s {quest:8464} waited for this visit: the furbolg village lies just east of {area:2255}, with Shaman (56-57), Den Watchers (55-56) and Ursa (57-58). Kill the Shaman first, they heal. {npc:10738} in the cave at the back is elite: stay out."] = "Задание {quest:8464} ({npc:11556}) ждало этого визита: деревня фурболгов лежит чуть восточнее (ориентир: {area:2255}), там шаманы (56-57), стражи логова (55-56) и урсы (57-58). Сначала убивайте шаманов, они лечат. {npc:10738} в пещере в глубине – элита: не заходите туда.",
		["{npc:11558}, just inside the cave: walks around here: look inside the circle on the map"] = "{npc:11558} – сразу у входа в пещеру: ходит здесь, ищите внутри круга на карте",
		["{npc:11610} hides at the Northridge lumber camp's edge."] = "{npc:11610} прячется на краю лесопилки Северного хребта.",
		["{npc:11610} hides at the lumber camp's edge."] = "{npc:11610} прячется на краю лесопилки.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} ходит по лагерю Северного Кряжа к востоку от {npc:11610}; {npc:11611} охраняет башню на южных подступах (ориентир: {area:190}).\nОсторожно: у подножия башни стоят стражи, и еще один патрулирует вокруг нее. Перебейте их, прежде чем нападать на Дургена, чтобы они не вмешались в бой.",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "Дом ({npc:11801}) стоит здесь: {area:2361}, к востоку (ориентир: {npc:11939}).",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722} – здесь: {object:2096}",
		["{npc:15181}: Bronzebeard's Encampment comes later, on the way south"] = "{npc:15181}: Лагерь Бронзоборода – позже, по пути на юг",
		["{npc:15183}: the tablet fragments come from the Twilight dig"] = "{npc:15183}: фрагменты табличек добываются на раскопках Сумеречного Молота",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15189}, upstairs"] = "{npc:15189} – наверху",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} стоит наверху в своем здании: поднимитесь внутри, стрелка не различает этажи.",
		["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190} – наверху, рядом с {npc:15189}",
		["{npc:15306}: his Twilight texts come from the dig after the next stop here"] = "{npc:15306}: его Сумеречные тексты добываются на раскопках после следующей остановки",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} стоит лагерем у западного улья ({area:2743}). Возьмите силитист у одного из красных гейзеров поблизости и отнесите его в экстрактор Альянса в его лагере.\nОсторожно: вы теряете силитист, если садитесь на транспорт, входите в незаметность, используете {spell:642}, {spell:5384} или «Исчезновение». «Скачок» и {spell:17} его не сбрасывают.",
		["{npc:17082}, at the Alliance tents: for {npc:17080} at {area:2743}"] = "{npc:17082} – у палаток Альянса: для персонажа {npc:17080} ({area:2743})",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} – элитный противник 61-го уровня",
		["{npc:1855} (optional)"] = "{npc:1855} (по желанию)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} живет в маленькой хижине у пограничной реки, к северо-востоку от лесопилки. Сдайте задание «{quest:5781}», если выполнили его.",
		["{npc:332}, in SI:7"] = "{npc:332} – в здании ШРУ",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516} – наверху ({area:1658})",
		["{npc:3520}, who walks the canals"] = "{npc:3520} – ходит вдоль каналов",
		["{npc:4155}, in the bank"] = "{npc:4155} – в банке",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} ({zone:1457}): сохраните задание",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740} – в Храме Луны",
		["{npc:8496}, inside"] = "{npc:8496}, внутри",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737} – в глубине лагеря",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive.\nCareful: Three {quest:5086} ambush you soon after the escort starts."] = "{npc:9598} ждет здесь: {area:1767}. Выведите ее из леса, не дав погибнуть.\nОсторожно: вскоре после начала сопровождения на вас нападают трое ({quest:5086}).",
		["{npc:9616}'s jars went to {zone:1455} on the {zone:1452} guide's {zone:1455} stop: fly straight to {area:976}."] = "Банки NPC {npc:9616} вы отвезли в {zone:1455} на остановке «{zone:1455}» в гайде по зоне {zone:1452}: летите прямо сюда: {area:976}.",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} ({zone:1452}), сохраните задание",
		["{quest:5845}: the route takes it and fetches the Symbol, so its hand-in holds"] = "{quest:5845}: маршрут берет его и добывает Символ, поэтому сдача этого задания остается в маршруте",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} ({area:3197}): сохраните задание",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} и Чумные земли",
		["{zone:1451}, {zone:1448}, {zone:1452} and the Plaguelands."] = "{zone:1451}, {zone:1448}, {zone:1452} и Чумные земли.",
		["{zone:1453} has no shaman trainer"] = "В городе {zone:1453} нет учителя шаманов",
		["{zone:1455} flight master"] = "Распорядитель полетов ({zone:1455})",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Вернитесь на восток через {area:131}: {npc:1252} у костра Эрика примет отчет «{quest:287}», а {npc:1269} — шестеренки и зубчатки. Задание шаманов здесь доступно с 10-го уровня: если шаману его не хватает, добейте уровень на медведях-ледолапах (7-8), снежных леопардах и больших скальных вепрях на полях чуть южнее места {area:131}.",
		["Back to {area:77}"] = "Обратно: {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Вернитесь к NPC {npc:257446} ({area:77}). Он даст вам {item:6635}: идите по отмеченной камнями тропе, которая поднимается на запад с юга долины к камню духов на гребне, выпейте сапту рядом с ним и поговорите: {npc:5891}, затем принесите Тео {item:6656}.",
		["Back to {npc:257597}"] = "Вернитесь: {npc:257597}",
		["Brewnall: kill these as you meet them"] = "Пивоварня: убивайте их по пути",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Скальные вепри и молодые черные медведи бродят по полям от лагеря Громобоя на северо-восток до места {area:131} и депо: убивайте их на обратном пути.",
		["Druid trainer"] = "Учитель друидов",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Каждое задание Грифа Дикое Сердце дает вам {item:15908}: используйте его на названном звере, затем верните жезл ему в кузницу ({area:131}). Большие скальные вепри, снежные леопарды и медведи-ледолапы бродят по полям чуть южнее и восточнее места {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Фарсен стоит лагерем на гребне, откуда с запада видно {area:134}. Поговорите с ним, чтобы получить его дальнее зрение.",
		["Feather Charms, from the Frostmane Novices"] = "Обереги из перьев, с новобранцев племени Мерзлогривов",
		["Firewood"] = "Дрова",
		["Follow the road east past the depot to {area:138}."] = "Идите по дороге на восток мимо депо сюда: {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Идите по дороге на северо-восток из места {area:131} к депо под дорогой в город {zone:1455}.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Тролли-подростки из племени Мерзлогривов заполняют склоны к югу и востоку от лагеря {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Гретхен стоит лагерем у самого входа в пещеру вендиго ({area:136}) к юго-западу (ориентир: {area:131}). Логово – после зоны {area:137}, когда его вендиго-старейшины и шаманы 8 уровня уже не будут выше вас.",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Медведи-ледолапы, старые скальные вепри и снежные леопарды бродят по холмам вокруг озера и места {area:137}.",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Подвески медведя-ледокогтя, с троллей-подростков из племени Мерзлогривов на склонах над лагерем",
		["Inside {area:77}"] = "Внутри: {area:77}",
		["Level 4 spells"] = "Заклинания 4-го уровня",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Косматые молодые волки бродят по снегу чуть южнее места {area:77}.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Душители из племени Каменной Челюсти у места {area:212}, к северу от карьера, и хребтоломы Каменной Челюсти дальше на восток оставляют {quest:95214}. Шпионы Черного Железа крадутся по берегу озера к востоку от карьера; один из них оставляет {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Головоломы, костоломы и душители из племени Каменной Челюсти населяют карьер и склоны к северу от него; душители оставляют {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Троггы и сильные троггы из племени Каменной Челюсти копают по всему дну долины к югу от места {area:77}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Малые скальные вепри пасутся вокруг лагеря {npc:714} и вдоль западной стороны долины.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Снежные леопарды и вепри бродят по снегу между ранчо и карьером. Кузнецы: медные слитки получают выплавкой ({item:2770}) или покупают у торговцев.",
		["The Fire Spirit Stone"] = "Камень духа огня",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Жгучая бражка действует пять минут: идите прямо на север к NPC {npc:836} внутри места {area:77}.",
		["The boars"] = "Вепри",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Дрова лежат в снегу вокруг замерзшего озера у приюта.",
		["The troggs"] = "Троггы",
		["The troll cave"] = "Пещера троллей",
		["The tunnel"] = "Туннель",
		["The {area:133} road"] = "Дорога к месту {area:133}",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269} в подвале",
		["Tram to {zone:1453}"] = "Поезд до {zone:1453}",
		["Upstairs"] = "Наверху",
		["Use the {item:6866} on {npc:6177}"] = "Используйте {item:6866} на NPC {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Вы начинаете перед местом {area:77} — каменным залом в северной части долины. {npc:658} ждет у двери.",
		["{area:131} and the depot"] = "{area:131} и депо",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, в лагере",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: {quest:98326}, в дальней части",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} — у замерзшего озера, среди ледяных элементалей.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: лепрогномы",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: лепрогномы",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: геоманты-туннельщики",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, рядом с камнем духов",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, рядом с камнем духов",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: ясновидцы из племени Камнедробов",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: шпионы из клана Черного Железа",
		["{npc:10090} in {zone:1455} takes it"] = "Сдается NPC {npc:10090} ({zone:1455})",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: приручите с помощью предмета {item:15908}",
		["{npc:11406}: {quest:5639}, his own copy of the letter"] = "{npc:11406}: {quest:5639}, его собственный экземпляр письма",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: приручите с помощью предмета {item:15908}",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: приручите с помощью предмета {item:15908}",
		["{npc:1231}, at the smithy"] = "{npc:1231}, у кузницы",
		["{npc:12738}, next to him"] = "{npc:12738}, рядом с ним",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: на время, пять минут, чтобы добраться до {npc:836} ({area:77})",
		["{npc:1377}, beside him"] = "{npc:1377}, рядом с ним",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: только для кузнецов",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} охраняет туннель из долины к востоку от места {area:77}; {npc:6782} стоит рядом с ним у входа.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, в карьере",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, внутри: {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} и ваш {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} ждет в пещере над фермой к северо-западу от места {area:806}; тропа наверх начинается за фермой.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: сдается NPC {npc:257597} у Южных ворот",
		["{npc:460}, inside {area:77}"] = "{npc:460}, внутри: {area:77}",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, рядом с лавкой Осрика; поезд из зоны {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят вместе у таверны ({object:2152}). {npc:6090} сражается с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите сразу к NPC {npc:6089}: он дает задание {quest:1639} и без него.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: сдается NPC {npc:6122} ({zone:1453})",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}).",
		["{npc:6179}: Redemption"] = "{npc:6179}: Искупление",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: руна для NPC {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: прочитайте {quest:98581}",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, рядом со {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Лагерь {npc:714} — в западной части долины. {item:10438} лежит в снегу к югу от него, сундук Феликса — у пещеры троллей, а феликсово ведро с гайками — к востоку от пещеры: подберите их по пути.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} и {npc:12738} стоят лагерем на юго-западной окраине долины, под пещерой троллей.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} находится внутри пещеры троллей к востоку от лагеря {npc:786}, а не на холме над ней: войдите в устье и идите по туннелю до конца.",
		["{npc:837}, the priest trainer"] = "{npc:837}, учитель жрецов",
		["{npc:895}, the hunter trainer"] = "{npc:895}, учитель охотников",
		["{npc:916}, the rogue trainer"] = "{npc:916}, учитель разбойников",
		["{npc:926}, the paladin trainer"] = "{npc:926}, учитель паладинов",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, у почтового ящика ({object:171524})",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Вернитесь на восток через {area:131}: {npc:1252} у костра Эрика примет отчет «{quest:287}», а {npc:1269} — шестеренки и зубчатки. Задание шаманов здесь доступно с 10-го уровня: если шаману его не хватает, добейте уровень на медведях-ледолапах (7-8), снежных леопардах и больших скальных вепрях на полях чуть южнее места {area:131}.",
		["Back to {area:77}"] = "Обратно: {area:77}",
		["Back to {npc:257597}"] = "Вернитесь: {npc:257597}",
		["Brewnall: kill these as you meet them"] = "Пивоварня: убивайте их по пути",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Скальные вепри и молодые черные медведи бродят по полям от лагеря Громобоя на северо-восток до места {area:131} и депо: убивайте их на обратном пути.",
		["Druid trainer"] = "Учитель друидов",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Фарсен стоит лагерем на гребне, откуда с запада видно {area:134}. Поговорите с ним, чтобы получить его дальнее зрение.",
		["Feather Charms, from the Frostmane Novices"] = "Обереги из перьев, с новобранцев племени Мерзлогривов",
		["Firewood"] = "Дрова",
		["Follow the road east past the depot to {area:138}."] = "Идите по дороге на восток мимо депо сюда: {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Идите по дороге на северо-восток из места {area:131} к депо под дорогой в город {zone:1455}.",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Тролли-подростки из племени Мерзлогривов заполняют склоны к югу и востоку от лагеря {npc:786}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}. The den comes after {area:137}, once its level 8 Elder Wendigos and Shamans are no longer above you."] = "Гретхен стоит лагерем у самого входа в пещеру вендиго ({area:136}) к юго-западу (ориентир: {area:131}). Логово – после зоны {area:137}, когда его вендиго-старейшины и шаманы 8 уровня уже не будут выше вас.",
		["Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake and {area:137}."] = "Медведи-ледолапы, старые скальные вепри и снежные леопарды бродят по холмам вокруг озера и места {area:137}.",
		["Inside {area:77}"] = "Внутри: {area:77}",
		["Level 4 spells"] = "Заклинания 4-го уровня",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Косматые молодые волки бродят по снегу чуть южнее места {area:77}.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Душители из племени Каменной Челюсти у места {area:212}, к северу от карьера, и хребтоломы Каменной Челюсти дальше на востоке оставляют {quest:95214}. Шпионы из клана Черного Железа крадутся по берегу озера к востоку от карьера; один из них оставляет {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Головоломы, костоломы и душители из племени Каменной Челюсти населяют карьер и склоны к северу от него; душители оставляют {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Троггы и сильные троггы из племени Каменной Челюсти копают по всему дну долины к югу от места {area:77}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Малые скальные вепри пасутся вокруг лагеря {npc:714} и вдоль западной стороны долины.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Снежные леопарды и вепри бродят по снегу между ранчо и карьером. Кузнецы: медные слитки получают выплавкой ({item:2770}) или покупают у торговцев.",
		["The Fire Spirit Stone"] = "Камень духа огня",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "Жгучая бражка действует пять минут: идите прямо на север к NPC {npc:836} внутри места {area:77}.",
		["The boars"] = "Вепри",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Дрова лежат в снегу вокруг замерзшего озера у приюта.",
		["The troggs"] = "Троггы",
		["The troll cave"] = "Пещера троллей",
		["The tunnel"] = "Туннель",
		["The {area:133} road"] = "Дорога к месту {area:133}",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "{object:269} в подвале",
		["Tram to {zone:1453}"] = "Поезд до {zone:1453}",
		["Upstairs"] = "Наверху",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите владение посохами у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Вы начинаете перед местом {area:77} — каменным залом в северной части долины. {npc:658} ждет у двери.",
		["{area:131} and the depot"] = "{area:131} и депо",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}, в лагере",
		["{item:280426}: {quest:98326}, at the back"] = "{item:280426}: {quest:98326}, в дальней части",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325} — у замерзшего озера, среди ледяных элементалей.",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: лепрогномы",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: лепрогномы",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: геоманты-туннельщики",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, рядом с камнем духов",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, рядом с камнем духов",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: ясновидцы из племени Камнедробов",
		["{npc:12738}, next to him"] = "{npc:12738}, рядом с ним",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: на время, пять минут, чтобы добраться до {npc:836} ({area:77})",
		["{npc:1377}, beside him"] = "{npc:1377}, рядом с ним",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: только для кузнецов",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} охраняет туннель из долины к востоку от места {area:77}; {npc:6782} стоит рядом с ним у входа.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, в карьере",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} ждет в пещере над фермой к северо-западу от места {area:806}; тропа наверх начинается за фермой.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: сдается NPC {npc:257597} у Южных ворот",
		["{npc:258785}: {quest:94817}, her own copy of the letter"] = "{npc:258785}: {quest:94817}, ее собственный экземпляр письма",
		["{npc:460}, inside {area:77}"] = "{npc:460}, внутри: {area:77}",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480} обучает воинов здесь: {object:2100}, возле лавки Осрика; поезд из зоны {zone:1455} прибывает сюда: {object:28027}, к северу от него. {npc:6089} и {npc:6090} стоят вместе у таверны ({object:2152}). {npc:6090} сражается с вами за свою кружку. Если {npc:5480} не предлагает задание {quest:1638}, идите сразу к NPC {npc:6089}: он дает задание {quest:1639} и без него.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} стоит в башне магов ({object:2101}); она дает вам флягу для водопада ({quest:1861}).",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: сдается NPC {npc:6122} ({zone:1453})",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} ждет в подвале здания {object:2164} ({object:2101}).",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, рядом со {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "Лагерь {npc:714} — в западной части долины. {item:10438} лежит в снегу к югу от него, сундук Феликса — у пещеры троллей, а феликсово ведро с гайками — к востоку от пещеры: подберите их по пути.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} и {npc:12738} стоят лагерем на юго-западной окраине долины, под пещерой троллей.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} находится внутри пещеры троллей к востоку от лагеря {npc:786}, а не на холме над ней: войдите в устье и идите по туннелю до конца.",
		["{npc:837}, the priest trainer"] = "{npc:837}, учитель жрецов",
		["{npc:912}, the warrior trainer"] = "{npc:912}, учитель воинов",
		["{npc:916}, the rogue trainer"] = "{npc:916}, учитель разбойников",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, учитель магов, внутри: {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, у почтового ящика ({object:171524})",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Тетушка\" Бернис Стоунфилд",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Назад к {npc:6122}. Используйте {item:6928} у круга призыва в подвале ({object:2164}) и победите призванного демона Бездны.",
		["Billy plays in the {area:64}, east of the mine."] = "Билли играет здесь: {area:64}, к востоку от рудника.",
		["Chunks of Boar Meat"] = "Куски кабанины",
		["Class trainer"] = "Учитель классовых навыков",
		["Crystal Kelp Fronds"] = "Ветки хрустального фукуса",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Лиходеи из Братства Справедливости стоят лагерем на поляне к востоку от аббатства и вдоль восточного края долины.",
		["Druid trainer"] = "Учитель друидов",
		["Follow the hills south to the tower, on the road west."] = "Идите по холмам на юг к башне, по дороге на запад.",
		["Follow the hills south to the tower."] = "Идите по холмам на юг к башне.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Идите по тропе на север к руднику. Снаружи кишат кобольды-рабочие; {object:83763} может упасть с любого кобольда в долине.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Идите по дороге на восток мимо места {area:91} к мосту. Добейте лесных хищников и молодых лесных медведей у реки к югу от него.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Идите по дороге на север от места {area:87} в город {zone:1453}. {npc:5497} стоит в башне ({object:2101}); она даст вам флягу для водопада ({quest:1861}).",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Идите по дороге на север от места {area:87} в город {zone:1453}. {npc:6122} ждет в подвале ({object:2164}, {object:2101}).",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Идите по дороге на юг из места {area:87}. Цель: {area:64}. {npc:251} ждет у дома.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Идите по дороге на юг. Цель: {area:120}, по пути в зону {zone:1436}. {npc:963} стоит у казарм; {npc:955} – внутри. Задание {quest:91738} есть у него, только пока у вас {item:247824}: поговорите с ним, и оно сразу перейдет к сдаче.",
		["He stands by the river west of the farm."] = "Он стоит у реки к западу от фермы.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Возвращайтесь через {area:87} и на восток вдоль дороги к {area:62}. {npc:881} (9 уровня) стоит у фермерского домика.",
		["Heal and fortify {npc:12423}"] = "Исцелите и укрепите: {npc:12423}",
		["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Если вы пропустили {quest:91752}, убивайте монстров здесь до уровня 5.77, чтобы не отстать от маршрута.",
		["Inside"] = "Внутри",
		["Inside {area:34}"] = "Внутри: {area:34}",
		["It lies by the river north-west of the logging camp."] = "Оно лежит у реки к северо-западу от лесозаготовок.",
		["Large Candles"] = "Большие свечи",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Выйдите из города {zone:1453} через главные ворота. Водопад ({quest:1861}) – к юго-западу от ворот, по пути на запад в зону {zone:1436}: наполните {item:7207} у его подножия.",
		["Level 5.77"] = "Уровень 5.77",
		["Lost Books: Kobold Miners and Tunnelers"] = "Потерянные книги: кобольды-шахтеры и кобольды-проходчики",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Маги: {npc:198}, учитель магов, стоит на втором этаже аббатства: поднимитесь по лестнице внутри, стрелка не различает этажи.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Мурлоки и речные мурлоки-бегуны занимают восточный берег; груды мусора лежат в их лагере. Осторожно: мурлоки стоят близко друг к другу, поэтому в бою легко привлечь сразу двух-трех: выманивайте их по одному с края лагеря и не преследуйте убегающего до следующей группы.",
		["Painted Gnoll Armbands"] = "Раскрашенные поручи гнолла",
		["Red Burlap Bandanas"] = "Красные холщовые банданы",
		["Red Linen Bandanas"] = "Красные льняные банданы",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Недоростки и гонцы стаи Речной Лапы занимают холмы к югу от гарнизона, вдоль границы с зоной {zone:1436}.",
		["Shaman trainer"] = "Учитель шаманов",
		["She stands by her cart at the vineyard east of the Abbey."] = "Она стоит у своей тележки на винограднике к востоку от аббатства.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Спелые красные яблоки: продает {npc:894}, для задания {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Сядьте (/sit) у его костра, пока не получите эффект «{spell:1229451}»",
		["South down the road to the {area:64}."] = "По дороге на юг. Цель: {area:64}.",
		["Subdue the voidwalker"] = "Одолейте демона Бездны",
		["Tame {npc:1922}"] = "Приручить: {npc:1922}",
		["Tame {npc:524}"] = "Приручить: {npc:524}",
		["Tame {npc:822}"] = "Приручить: {npc:822}",
		["The Defias camp"] = "Лагерь Братства Справедливости",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "Ферма Стоунфилдов – к западу от рудника. Мамаша и \"Тетушка\" Бернис стоят у дома.\nОна сидит в доме на ферме.",
		["The bridge"] = "Мост",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Ящики с виноградом лежат на виноградниках за Братством Справедливости. {npc:103} ждет у хижины в восточном конце долины.",
		["The kobold camp"] = "Лагерь кобольдов",
		["The lake shore"] = "Берег озера",
		["The vineyards and {npc:103}"] = "Виноградники и {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736} стоит к северу от места {area:120}. Щелкните по нему, имея в сумках четыре спелых красных яблока: он заберет их и сразу даст {item:247824} (задание не появляется в журнале заданий). Сохраните сидр для NPC {npc:955}: не пейте его.",
		["Walk into the mine"] = "Войдите в рудник",
		["Walk through the mine"] = "Пройдите через рудник",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Раз уж вы здесь: изучите посохи у NPC {npc:11867} ({object:2096}, 10 серебра); при прокачке посох дает больше характеристик для заклинаний, чем одноручное оружие.",
		["Wolves"] = "Волки",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Вы начинаете перед аббатством. {npc:823} стоит у подножия лестницы, {npc:197} – в зале, {npc:951} и {npc:247229} – в библиотеке справа, {npc:196} – снаружи у северо-западного угла.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Молодые и лесные волки бродят по полям прямо вокруг аббатства.",
		["grind on {npc:113}"] = "убивайте: {npc:113}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "его следопыт по кобольдам показывает, на каких кобольдов щелкать по дороге (цель: {area:87})",
		["talk to the trainer"] = "поговорите с учителем",
		["{area:18}: kill these as you meet them"] = "{area:18}: убивайте их по пути",
		["{area:34}: kill these as you meet them"] = "{area:34}: убивайте их по пути",
