t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["Back at {area:256}"] = "Снова здесь: {area:256}",
		["Back to the moonwell."] = "Назад к лунному колодцу.",
		["Befouled Webwoods"] = "Оскверненные тенетники",
		["Below ground"] = "Под землей",
		["Bloodfeather harpies"] = "Гарпии из стаи Кровавого Пера",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Каждое задание Дазалара дает вам предмет {item:15908}: примените его на названном звере, затем верните жезл ему ({area:186}). Чащобные тенетники ползают вокруг деревни, ночные саблезубы-охотники и совы-крикуны бродят по лесу к югу от нее.",
		["East along the road to {area:186}."] = "На восток по дороге к месту {area:186}.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Выведите из обители: {npc:275744}; отчет принимает {npc:2081} ({area:186}).",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Шишки Скверны лежат под деревьями вокруг места {area:186} и NPC {npc:2150}: подбирайте их на дороге на восток и отдайте NPC {npc:2150} по пути к NPC {npc:7234}.",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Летите обратно сюда: {area:702} – от {npc:3841}, отдайте {item:16263}: {npc:10118} на пристани, затем летите обратно ({area:442}).",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Идите по дороге на юго-запад из {area:188}. {npc:2150} сидит у дороги чуть восточнее места {area:186}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Душители из племени Кривой Сосны прячутся вдоль дороги к западу от места {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Мистики из племени Кривой Сосны и {npc:7234} стоят лагерем к северо-востоку от места {area:260}. С NPC {npc:7234} падает {item:8049}: откройте его, чтобы достать самоцвет.\nОсторожно: {npc:7234} ждет у костра в окружении мистиков, так что выманить его одного трудно.",
		["Gnarlpine Shamans"] = "Шаманы из племени Кривой Сосны",
		["Grells"] = "Грелли",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "{item:3297} носят грелли (2-3-го уровня) в лесу к западу от древа, у тотемов. Дальше к северу – {npc:1989} 3-4-го уровня: хватит греллей у тотемов.",
		["Heal and fortify {npc:12429}"] = "Исцелите и укрепите: {npc:12429}",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Покиньте долину ({area:188}) по тропе к юго-востоку от древа ({area:256}): {npc:6780} стоит рядом с ней, где она спускается к дороге на Доланаар ({area:186}).",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Облезлые ночные саблезубы и щетинистые вепри бродят к северу от древа ({area:256}), по пути к пещере. {npc:1994} – в ее глубине. {npc:8584} ждет среди деревьев к западу от входа в пещеру.",
		["Nightsabers"] = "Ночные саблезубы",
		["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "Ночные саблезубы, совы и чащобные тенетники бродят по всей округе ({area:186}) и вдоль дороги на восток; с тенетников также падают паучьи лапки для рецепта. Лунный колодец – на западном краю деревни ({area:260}).",
		["North to {area:257}"] = "На север: {area:257}",
		["Priest trainer"] = "Учитель жрецов",
		["Sentinel Arynia again"] = "Снова часовой Арания",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "К юго-востоку от Доланаара: {npc:2080}. Вокруг него на берегу бродят плеточники-ростки.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "К юго-западу от Звездного Бриза, к югу от NPC {npc:2150}. {npc:2080} ухаживает за своими саженцами на берегу; вокруг бродят плеточники-ростки и древесники, а среди них растут ростки ({quest:919}).",
		["South-west of the barrow. The moonwell sits by the pools."] = "К юго-западу от обители. Лунный колодец – у озер.",
		["The WANTED poster outside the inn"] = "Плакат «РАЗЫСКИВАЕТСЯ» у таверны",
		["The grells west of the tree"] = "Грелли к западу от древа",
		["The moonwell"] = "Лунный колодец",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "Лунный колодец – в центре поляны. {object:6752} растет в ее северной части.",
		["The road to {zone:1457}"] = "Дорога в город {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "Дорога на запад ({area:264}) проходит через {area:186}: по пути отдайте самоцвет: {npc:3567}.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Учителя стоят наверху внутри древа ({area:256}), вдоль пандуса, вьющегося вверх: {npc:3593} и {npc:3594} – на первом ярусе, {npc:3595} – выше, {npc:3596} и {npc:3597} – на вершине. Стрелка не различает ярусы.",
		["The {area:478}"] = "{area:478}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} лежат в глубине пещеры ({area:257}): идите по центральному проходу, на развилке налево, вверх до высокого уступа. Гиацинтовые грибы падают с греллей, лунные лилии растут у прудов к северу от древа ({area:256}).",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752} растет по пути, в северной части поляны: затем на север вдоль северного края острова у озера ({area:266}) – там затаилась {npc:7319}, паучиха 12-го уровня.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Прибрежные крабы снуют по берегу под деревней; {quest:983} стоит на пляже чуть южнее пристани. На мелководье плавают крепкозубы Темного берега. {object:175207} лежит на берегу чуть южнее деревни.",
		["Upstairs"] = "Наверху",
		["Use the {item:18152} at the moonwell"] = "Используйте {item:18152} у лунного колодца",
		["Use the {item:5185} at the moonwell"] = "Используйте {item:5185} у лунного колодца",
		["Use the {item:5619} at the moonwell"] = "Используйте {item:5619} у лунного колодца",
		["Use the {item:5621} at the moonwell"] = "Используйте {item:5621} у лунного колодца",
		["Walk Lynessa out and keep her alive"] = "Выведите Линессу, не дав ей погибнуть",
		["Webwood Lurkers"] = "Чащобные тенетники",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Вы начинаете у подножия великого древа ({area:256}, {area:188}).",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "Вокруг древа ({area:256}) бродят молодые ночные саблезубы и молодые щетинистые вепри (1-2-го уровня): начните с них. Тотемы племени Кривой Сосны стоят в лесу к западу от древа, где бродят грелли (2-3): займитесь ими, когда закончите со зверями.",
		["{area:186} again"] = "Снова здесь: {area:186}",
		["{area:258}'s mouth"] = "Вход: {area:258}",
		["{area:736}, outside the barrow"] = "{area:736} – снаружи обители",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159}: продает {npc:6736}, для персонажа {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371}: продает {npc:3614}, рядом с персонажем {npc:6094}",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} лежит раненая на камнях у северного края озера ({area:259}), по пути обратно ({area:186}); над ней нет значка задания. Примените на нее «{spell:613}» (2-й уровень), затем «{spell:1243}»: 1-й уровень заклинания «{spell:613}» не засчитывается. Когда оба заклинания сработают, она убегает и возвращается примерно через 5 минут.",
		["{npc:1992}, south of the tree"] = "{npc:1992} – к югу от древа",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: приручите его с помощью предмета {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: приручите его с помощью предмета {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} ждет в пещере, внизу или наверху на уступе; держитесь правой стороны.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: приручите его с помощью предмета {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077} – у тропы",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: знак для персонажа {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: задание принимает {quest:922} ({zone:1457})",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082} – на пандусе древа",
		["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} стоит наверху в доме в деревне, к востоку от лунного колодца: поднимитесь внутри, стрелка не различает этажи. {object:126158} – в доме на холме в восточной части деревни.",
		["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150} сидит у дороги чуть восточнее места {area:186}, между местами {area:186} и {area:260}.",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} патрулирует дорогу к западу от деревни: если ее нет у стрелки, идите по дороге, пока не встретите ее.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151} – на дороге к западу от деревни",
		["{npc:265811}, by the campfire"] = "{npc:265811} – у костра",
		["{npc:3514}, at the top of the tree"] = "{npc:3514} – на вершине древа",
		["{npc:3519}, by the moonwell"] = "{npc:3519} – у лунного колодца",
		["{npc:3593}, the warrior trainer; inside"] = "{npc:3593} – учитель воинов; внутри",
		["{npc:3594}, the rogue trainer"] = "{npc:3594} – учитель разбойников",
		["{npc:3595}, the priest trainer, on the second level of {area:256} on the way down: {npc:3600} in {area:186} takes it"] = "{npc:3595} – учитель жрецов, на втором ярусе древа ({area:256}) по пути вниз: задание принимает {npc:3600} ({area:186})",
		["{npc:3595}, the priest trainer: in at the tree's front entrance and up the ramp"] = "{npc:3595} – учитель жрецов: войдите в древо через главный вход и поднимитесь по пандусу",
		["{npc:3596}, the hunter trainer"] = "{npc:3596} – учитель охотников",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597} – учитель друидов ({area:256})",
		["{npc:3600}: heal {npc:12429} by {area:259}"] = "{npc:3600}: исцелите персонажа {npc:12429} у озера ({area:259})",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: задание принимает {npc:11401} ({zone:1457})",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: задание принимает {npc:4217} ({zone:1457})",
		["{npc:3649}, north end of the village"] = "{npc:3649} – в северной части деревни",
		["{npc:4146} in {zone:1457} takes it"] = "Задание принимает {npc:4146} ({zone:1457})",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146} ({area:1658}): {spell:5149}",
		["{npc:4241}, on the {area:1659} just inside the city"] = "{npc:4241} – {area:1659}, сразу у входа в город",
		["{npc:7318} (level 10), {npc:7317}'s soulless body, walks around {area:736} in the den: kill him, then use {npc:7317}'s {item:8149}."] = "{npc:7318} (10-й уровень), бездушное тело NPC {npc:7317}, бродит в логове ({area:736}): убейте его, затем используйте {item:8149} (владелец: {npc:7317}).",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999} – выше, над персонажем {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583} – к востоку от древа",
		["{quest:917} and the antidote"] = "{quest:917} и противоядие",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: примените «{spell:1259799}» и «Слиться с тенью», затем сдайте задание: {npc:3595}",
} end)()
t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north to {area:447}: the flame burns in the south of the ruins."] = "Обратно на север в {area:447}: пламя горит в южной части руин.",
		["Bears and the Blackwood camp"] = "Медведи и лагерь Чернолесья",
		["Blackwood furbolgs"] = "Фурболги Чернолесья",
		["Class trainer"] = "Учитель классовых навыков",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Поднимитесь в горы к востоку (ориентир: {area:447}); {object:175524} лежит на уступе.",
		["Druid trainer"] = "Учитель друидов",
		["Fill the tube at the moonwell in the village"] = "Наполните пробирку у лунного колодца в деревне",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Идите вдоль побережья на юг мимо руин ({area:447}): одно существо ({quest:4728}) лежит на берегу к западу от Рощи, другое – южнее, рядом с местом {area:450}. Еще три останка лежат дальше на юго-западе среди оракулов и волноловов из племени Серой Мглы (18–20): гайд оставляет их на последний круг, когда вы будете ближе к их уровню.",
		["Grell Earrings"] = "Серьги грелля",
		["Highborne Relics"] = "Реликвии высокорожденных",
		["North along the hills to {npc:3650}, then west down to {area:442}."] = "На север вдоль холмов к NPC {npc:3650}, затем на запад вниз в {area:442}.",
		["Rabid Thistle Bears roam the hills south of {area:442}: use {item:7586} on one to capture it. Then walk up to the furbolg camp just east of them: nothing to kill yet."] = "Бешеные косолапы бродят по холмам к югу от {area:442}: используйте {item:7586} на одном из них, чтобы поймать его. Затем поднимитесь к лагерю фурболгов чуть восточнее: пока никого убивать не нужно.",
		["Read the {object:17188}"] = "Прочитайте: {object:17188}",
		["Read the {object:17189}"] = "Прочитайте: {object:17189}",
		["Shaman trainer"] = "Учитель шаманов",
		["The WANTED poster outside the inn"] = "Плакат «РАЗЫСКИВАЕТСЯ» у таверны",
		["The red crystal"] = "Красный кристалл",
		["The skeletal turtle"] = "Скелет черепахи",
		["The southern beaches"] = "Южные пляжи",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Раз уж вы здесь: изучите владение мечами у NPC {npc:11867} ({object:2096}, 10 серебра); с мечом в правой руке разбойник стабильно качается.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Раз уж вы здесь: изучите {spell:202} у NPC {npc:11867} ({object:2096}, 10 серебра); с двуручным оружием воин качается быстрее всего.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Вы пропустили это при прошлом посещении этих мест по маршруту: теперь это идёт первым. Это быстро и открывает следующие задания.\nКорабль причаливает к западу от деревни. Распорядитель полетов стоит на холме к югу от таверны; дающие задания – вдоль главной улицы.",
		["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289} – на пляже к западу от пристани; под водой",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: сатиры из племени Дет'рилл",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} ({zone:1426}); {area:87}: учителя шаманов нет",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} – {zone:1453}; в {area:87} нет учителя друидов",
		["{zone:1453} flight master"] = "Распорядитель полетов: {zone:1453}",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Ал'акетские ловцы бурь и пехотинцы стоят лагерем чуть севернее {npc:257944}; с них падает реликвия. С визгунов к западу от нее падают перья и когти; {item:265105} растет вдоль ручья к западу от нее.",
		["Back east out of the den to the grove."] = "Возвращайтесь из логова на восток, в рощу.",
		["Back to the Hermit"] = "Назад к отшельнику",
		["Back to {area:16622}"] = "Назад: {area:16622}",
		["Bandit Highwaymen"] = "Придорожные бандиты",
		["Below ground"] = "Под землей",
		["Desperate times"] = "Отчаянные времена",
		["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Лагерь Филлиона – к северо-западу от него, а визгуны-матриархи гнездятся чуть западнее лагеря.",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Идите на север: {area:16631}. {npc:257944} стоит лагерем в восточной части леса.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "Идите на северо-запад к гнездам гиппогрифов на западных утесах. {item:263493} лежит вокруг гнезд; среди них патрулирует гиппогриф-матриарх.\nПровидцы-новички упражняются на поляне к западу от Шен'дара, по пути обратно в деревню.",
		["Inside"] = "Внутри",
		["Level 4 spells"] = "Заклинания 4-го уровня",
		["Listen to {npc:252448}'s story"] = "Выслушайте историю: {npc:252448}",
		["Listen to {npc:257554}"] = "Выслушайте {npc:257554}",
		["North-west of Valanaar along the road, past {npc:273017}: the dead cultist lies just north of him."] = "К северо-западу от Валанаара по дороге, за NPC {npc:273017}: мертвый культист лежит чуть севернее него.",
		["Prideclaws and Galestriders"] = "Когти прайда и буреноги",
		["Prideclaws and Galestriders roam the grasslands around the village. Galestriders drop both the eggs and the meat: most players get the eggs from the ones just west of the village."] = "Когти прайда и буреноги бродят по лугам вокруг деревни. С буреногов падают и яйца, и мясо: большинство игроков добывают яйца с тех, что чуть западнее деревни.",
		["Raw Windstones and the {npc:251404}"] = "Ветрокаменное сырье и {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Спелые буреяблоки и голодные бандиты – в саду у фермы, {quest:92683} – на полях к северо-востоку от нее, задиристые буреноги – повсюду. {npc:250929} стоит на поле к северо-востоку от фермы.",
		["Search the dead cultist"] = "Обыщите мертвого культиста",
		["Search the wardrobe"] = "Обыщите шкаф",
		["Shen'dar turn-ins"] = "Сдача заданий в Шен'даре",
		["Skyhoppers"] = "Небопрыги",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Небопрыги кишат на полях к западу от места {area:16638}.",
		["Standing our ground"] = "Держим оборону",
		["Tame {npc:254588}"] = "Приручите: {npc:254588}",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Придорожные бандиты занимают холмы к северу от фермы.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp.\nCareful: the bandits stand in close groups and players often died in this camp: pull them one at a time from the edge."] = "Бандиты нагорья стоят лагерем к северо-востоку от деревни. Бенник-Баламут ждет в дальней северной части их лагеря.\nОсторожно: бандиты стоят плотными группами, и игроки часто гибли в этом лагере: выманивайте их по одному с края.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "Ветрокаменное сырье блестит на земле чуть южнее рощи. {quest:92463} парит над лугом дальше к востоку, по пути к NPC {npc:249363}.",
		["The Windstone Formations"] = "Огромные ветрокамни",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "Огромные ветрокамни стоят на возвышенности к западу от лагеря Филлиона.",
		["The bounty board"] = "Доска объявлений о награде",
		["The class trainers stand together in the grove"] = "Учителя классов стоят вместе в роще",
		["The dead cultist"] = "Мертвый культист",
		["The eastern watchtower"] = "Восточная сторожевая башня",
		["The missing scholar"] = "Пропавший ученый",
		["The road to {area:16638}"] = "Дорога: {area:16638}",
		["The {item:254871}"] = "{item:254871}",
		["The {object:581822}"] = "{object:581822}",
		["Underwater"] = "Под водой",
		["Upstairs"] = "Наверху",
		["Village quests"] = "Задания деревни",
		["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round."] = "Если вы изучили профессию, {npc:263664} также предлагает свое задание «Основы походной жизни», которое сдается учителю этой профессии здесь: {area:16624}, во время обхода деревни.",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Вы просыпаетесь здесь: {area:16622}. {npc:251362} стоит рядом с вами; {npc:251361} – в нескольких шагах к западу, {npc:251368} – у южного края рощи.",
		["{area:16622} turn-ins"] = "Сдача заданий: {area:16622}",
		["{area:16624} again"] = "Снова здесь: {area:16624}",
		["{area:16638} turn-ins"] = "Сдача заданий: {area:16638}",
		["{area:16638}, the turncoat"] = "{area:16638}: предатель",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} и назойливые щетинистые осы бродят по лугу чуть юго-восточнее рощи.",
		["{npc:251964}, in the watchtower"] = "{npc:251964} – в сторожевой башне",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} удерживает западный дозор к юго-западу от Фалаата. {npc:256966} и павшие стражи лежат чуть южнее нее.",
		["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}, рядом с NPC {npc:257006}: {npc:257196} удерживает Бастион здесь: {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} удерживает сторожевую башню к северу от места {area:16638}. Ал'акетский лагерь – чуть западнее башни, его целители – около 65,68 и 65,65; {npc:252666} стоит в его северной части. С тамошних ал'акетцев падают ал'акетские ветрокаменные талисманы.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} и {npc:252476} стоят в северной части города ({area:16638}), {npc:252475} и {npc:253204} – в южной.",
		["{npc:252800} again"] = "Снова {npc:252800}",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} управляет фермой в юго-западной низине.",
		["{npc:255853} waits by the falls just north of the watchtower. {npc:258443} prowls the {area:16623} south-west of the dead cultist, where you go after {area:16638}."] = "{npc:255853} ждет у водопада чуть севернее сторожевой башни. {npc:258443} рыщет здесь: {area:16623}, к юго-западу от мертвого культиста – туда вы отправитесь после места {area:16638}.",
		["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853} у водопада к северо-востоку от места {area:16638}, по пути на север: {spell:5487}",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} ждет у входа в деревню ({quest:92529}) к югу от Шен'дара. {spell:1254832} позволяет вам ходить среди верующих.",
		["{npc:257944} again"] = "Снова {npc:257944}",
		["{npc:257944}, the missive"] = "{npc:257944}: послание",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443} – на нагорье к юго-западу от культиста",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} живет к западу от {npc:257944}. Бризошишки лежат в лесу между его хижиной и {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["Take the portal up to {npc:4217} in the {area:1658}. {quest:31}: swim fast and breathe underwater."] = "Поднимитесь через портал к {npc:4217}. Локация: {area:1658}. {quest:31}: быстро плавайте и дышите под водой.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Водный облик для путешествий: быстрое плавание и дыхание под водой, а заодно пояс и идол.",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877} из контейнера в озере ({object:177785})",
		["{item:15882}, from the {object:177844}"] = "{item:15882}, из ящика ({object:177844})",
		["{item:15883}, from the {object:177794}"] = "{item:15883}, из ящика ({object:177794})",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: соедините половинки у святилища",
		["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033} стоит в хижине друидов здесь: {area:1639}.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "На 10-м уровне вас зовет друид: {npc:3064} ({area:222}) или {npc:6746} ({zone:1456}; подойдет и письмо: {npc:6929}, {zone:1454}). Любой из них отправляет вас к NPC {npc:3033} ({area:1639}, {zone:1456}).",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "На 10-м уровне вас зовет друид: {npc:3602} ({area:186}), Денатарион ({zone:1457}) или Теридан ({zone:1453}). Любой из них отправляет вас к NPC {npc:4217} (Анклав Кенария, Дарнасс).",
		["Back to {npc:255853} by the falls."] = "Вернитесь: {npc:255853}, у водопада.",
		["Back to {npc:3033} on {area:1639}."] = "Вернитесь: {npc:3033} ({area:1639}).",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here ({npc:12740} for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "Примените {spell:18960}: вы окажетесь у здания, где наверху стоит {npc:11802} ({area:2361}). Заодно откройте маршрут полета {area:493} ({npc:12740} для Орды, к юго-западу от озера; {npc:10897} для Альянса, к югу от него).",
		["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path ({npc:12740}, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Примените {spell:18960}: вы окажетесь у здания, где наверху стоит {npc:11802}. {quest:5930} находится в лесу к северо-западу. Поговорите с ним и пройдите весь разговор (что он олицетворяет, сила тела, сила сердца, затем попросите благословения): разговор и есть задача, боя нет. Он сливается с землей, над ним нет знака задания, и он слабо светится серо-голубым у группы из трех деревьев: от места {area:2361} идите на запад вдоль подножия северных гор, через проход между деревьями и холмами. Если по возвращении NPC {npc:11802} нет, выйдите наружу и снова примените {spell:18960}. Откройте маршрут полета {quest:5922} ({npc:12740}, к юго-западу от озера); {npc:11798} в месте {area:2361} доставляет друидов в {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Летите обратно в {area:702} и поднимитесь через портал к {npc:4217}.",
		["Skyboat from {area:279}"] = "Небесный корабль: {area:279}",
		["Skyboat from {zone:1456}"] = "Небесный корабль: {zone:1456}",
		["Speak with the {quest:5929}"] = "Поговорите: {quest:5929}",
		["Speak with the {quest:5930}"] = "Поговорите: {quest:5930}",
		["The {object:177525}"] = "Объект: {object:177525}",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Ваш облик танка: в Forever {spell:5487} больше не изучают у учителя, его дают эти задания. Также открывает {area:493}.",
		["or whichever of the three letters you carry"] = "или любое из трех писем, что у вас есть",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} стоит здесь: {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} и {npc:258443}",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; письма Палы и Гришки ведут туда же",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; письма Денатариона и Теридана ведут туда же",
		["{spell:5487} and {area:493}"] = "{spell:5487} и {area:493}",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Вернитесь к Землепроходцу {npc:9619} в юго-восточный угол кратера: {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "Примените {spell:18960}. {npc:12042} стоит здесь: {area:2361}; ваш учитель класса ({npc:3033}, {npc:4217} или Теридран в городе {zone:1453}) дает то же задание.",
		["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "Опыт в Кратере Ун'Горо на 50-м уровне и два лечебных зелья; в Forever выбора предмета из Classic может не быть.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Летите сюда: {area:976}. Скачите на запад к длинному спуску в {zone:1449}: {npc:9619} разбил лагерь у его подножия, в юго-восточном углу кратера.",
		["Gorishi Stings and {item:22434}"] = "Жала Гориши и {item:22434}",
		["The {area:1417}"] = "{area:1417}",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: уколите его ({item:22432})",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "Назад к {npc:11802}",
		["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}, чтобы оказаться рядом с {npc:11802} ({area:2361}) – на острове Зефрас задание небеснорожденных никто не принимает. Затем летите с помощью персонажа {npc:11798} сюда: {area:1638}. {npc:11802} стоит наверху в своем доме: поднимитесь внутри, стрелка не различает этажи.",
		["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}, чтобы оказаться рядом с {npc:11802} ({area:2361}) – на острове Зефрас задание небеснорожденных никто не принимает. Затем летите с помощью персонажа {npc:11800} сюда: {area:702}. Она стоит в центре локации {area:2361} и доставляет туда друидов, маршрут полета не нужен. {npc:11802} стоит наверху в своем доме: поднимитесь внутри, стрелка не различает этажи.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}. {npc:11802} стоит наверху в своем доме, здесь: {area:2361}. Поднимитесь внутри: стрелка не различает этажи.",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "Примените {spell:18960}. {npc:11802} стоит наверху в своем здании ({area:2361}): поднимитесь внутри, стрелка не различает этажи. Еще нет маршрута полета в {area:493}? Изучите его у NPC {npc:10897} к югу от озера: Распорядитель полетов в {area:2361} возит только друидов (через диалог) и маршрута для изучения не дает.",
		["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "Поднимитесь через портал к {npc:4217}, наверх ({area:1658}): он обучит вас заклинанию {spell:768}.",
		["The relics of the Barrow Dens"] = "Реликвии Келий Малфуриона",
		["The {area:2363}"] = "{area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Ваш облик для скрытности и ближнего боя: в Forever {spell:768} на 20-м уровне дает эта цепочка, а не учитель.",
		["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{npc:3033} ({area:1639}) обучит вас заклинанию {spell:768}.",
		["{npc:3033} stands in the druids' hut on {area:1639}. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:3033} стоит в хижине друидов ({area:1639}). Еще нет {spell:1066}? Возьмите у него и «Необходимый урок»: оно тоже ведет к NPC {npc:11802}, а следующее за ним «Испытание озера» (гайд по {spell:1066}) – там же ({area:493}).",
		["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {spell:1066} yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the {spell:1066} guide) is in the same {area:493}."] = "{npc:4217} стоит здесь: {area:1658}. Небеснорожденным вдали от города {zone:1457}: используйте {spell:18960} и летите с NPC {npc:11800} из центра поселения {area:2361} (она доставляет друидов сюда: {area:702}, маршрут полета не нужен), затем поднимитесь через портал. Еще нет {spell:1066}? Возьмите у него и «Необходимый урок»: оно тоже ведет к NPC {npc:11802}, а следующее за ним «Испытание озера» (гайд по {spell:1066}) – там же ({area:493}).",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960} и поговорите: {npc:11802}. Затем летите с помощью персонажа {npc:11798} сюда: {area:1638}. {npc:11802} стоит наверху в своем здании: поднимайтесь внутри, стрелка не различает этажи.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960} и поговорите: {npc:11802}. Затем летите с помощью персонажа {npc:11800} из центра места {area:2361} (она отвозит друидов сюда: {area:702}, маршрут полета не нужен) и поднимитесь через портал: {zone:1457}. {npc:11802} стоит наверху в своем здании: поднимайтесь внутри, стрелка не различает этажи.",
		["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "Примените {spell:18960}: {npc:11802} стоит наверху в здании рядом с вами. Он вручит вам {item:15842}. {npc:11798} отвозит друидов сюда: {area:1638}; оттуда летите дальше к Перекрестку.",
		["Sickly Gazelles"] = "Больные газели",
		["{item:15851} and {item:2449}"] = "{item:15851} и {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} и рога кодо",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}; травники собирают его на равнинах",
		["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{npc:3033} ({area:1639}) обучит вас заклинанию {spell:8946}.",
		["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448} стоит на Перекрестке. Нет навыка {skill:182}? {npc:3490} в нескольких шагах, у распорядителя полетов, продает {item:2449} по 80 медных за штуку – по три штуки, пока не пополнит запас.",
		["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{npc:4217}, наверху ({area:1658}), обучит вас заклинанию {spell:8946}.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "В Forever учитель больше не обучает заклинанию «{spell:8946}»: ему учит эта цепочка, а по пути вы получите сумку с лекарствами.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "Обратно к Древним",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "В Forever не подтверждено. В Classic {item:18707}, использованный с предметом {item:18724} в сумках, превращался в Рок-Делар, а если еще раз поговорить с Вартусом, он давал {item:18715} без дополнительной платы.",
		["Onyxia"] = "Ониксия",
		["Rhok'delar and Lok'delar"] = "Рок-Делар и Лок-Делар",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "Цепочка заданий на эпический лук охотника: в Classic посох и сухожилие становились Рок-Деларом и Лок-Деларом (в Forever не подтверждено).",
		["The {item:18703}"] = "{item:18703}",
		["from the {item:18703}"] = "из предмета {item:18703}",
		["{item:18705}, from Onyxia"] = "{item:18705} с Ониксии",
		["{item:18707}, by Vartrus"] = "{item:18707}, от Вартуса",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Лок-Делар в Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: колчан, последний в этом гайде",
		["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {spell:13809}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}, гном, бродит у врат ({area:3428}) на крайнем юго-западе зоны {zone:1451}. Поговорите с ним, и он превратится: {npc:14530}. Превращаясь, он впадает в исступление ({spell:23272}): поставьте {spell:13809}, примените {spell:5384}, и он сбросится без исступления. {spell:2974} надолго обездвиживает его; пока он обездвижен, он пугает вас и насылает жуков ({npc:14761}): быстро убивайте их ловушками и {spell:2643}, пока они вас не измотали.",
} end)()
