t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Сфера для левой руки или посох для уровней ближе к 40, на ваш выбор.",
		["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. The reward window shows the {item:9527} and the {item:9531}."] = "На 40-м уровне у учителей магов, которые отправляют вас к NPC {npc:6546} ({npc:5497}, Бинк, {npc:4568}, {npc:5885}), есть и задание {quest:2861}, которое может выполнить любой класс. Затем {npc:6546} просит добыть {quest:2846}: ее носит {npc:7795}, элитная нага 46-го уровня в подземелье троллей {area:978} на северо-западе зоны {zone:1446}: группа из пяти человек, 44-54 уровень. В окне награды – {item:9527} и {item:9531}.",
		["Back at {npc:6546}'s. Hand in the orb now; {quest:1955} waits for level 40. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "Снова у NPC {npc:6546}. Сдайте сферу сейчас; {quest:1955} ждет 40-го уровня. Сначала убейте зверьков вокруг хижины: они вступают в бой. Когда вы берете {quest:1955}, запускается 3-минутный таймер, и {npc:6546} вызывает в своем саду противника {npc:6549}: элитного противника 40-го уровня, устойчивого ко многим заклинаниям, обездвиживанию и замедлению. Лучше собрать группу: магу 40-го уровня может понадобиться помощь или зелья, примерно с 45-го его можно убить в одиночку. Его можно выманить издалека с причала. Таймер продолжает идти после его смерти, поэтому сдайте задание сразу. Если время вышло, откажитесь от задания и возьмите его снова; она снова вызовет демона.",
		["{area:1517} is a dungeon in the northern {zone:1418}: a group of five, from level 40 here. Go in by the rear entrance, a cave in {area:1898} south-east of the main entrance (elite dragons fly nearby): the {npc:7023} (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an {npc:7209}, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back."] = "{area:1517} – подземелье на севере зоны {zone:1418}: группа из пяти человек, здесь с 40-го уровня. Входите через задний вход – пещеру ({area:1898}) к юго-востоку от главного входа (рядом летают элитные драконы): {npc:7023} (элитный, 42-й уровень) стоит сразу за первой дверью. На 80, 60, 40 и 20 процентах здоровья от него откалывается {npc:7209}, тоже элитный; пока жив осколок, оба отражают направленные заклинания, так что бейте их заклинаниями по области и жезлом. Хитрость для одиночки: каждый раз, когда появляется осколок, выходите за ближайшую границу зоны; часовой лечится, но продолжает уменьшаться. Источник энергии падает всегда, а возрождается часовой через 2 часа.",
		["{area:978}, the troll dungeon in north-western {zone:1446}, needs a group of five; the guide waits for level 46. {npc:7795} is one of the bosses by the sacred pool, and the tiara always drops."] = "{area:978}, подземелье троллей на северо-западе зоны {zone:1446}, требует группы из пяти человек; гайд ждет 46-го уровня. {npc:7795} – один из боссов у священного водоема, и тиара падает всегда.",
		["{item:7515} and Stave"] = "{item:7515} и Небесный посох",
		["{npc:5497} at the top of the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497} на вершине Святилища волшебника ({zone:1453}, {object:2101}) отправляет вас обратно к NPC {npc:6546}; Бинк ({zone:1455}) дает то же задание.",
		["{npc:5885}, one of {zone:1454}'s mage trainers in {object:173161}, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, один из учителей магов ({zone:1454}, {object:173161}), отправляет вас обратно к NPC {npc:6546}; {npc:4568} ({zone:1458}) и {npc:3048} ({zone:1456}) дают то же задание.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}; come in from the west road, the elites roam its east side."] = "Хижина NPC {npc:6546} находится глубоко в болотах к западу от острова Терамор, чуть севернее места {area:508}; подходите с западной дороги, элитные противники бродят с восточной стороны.",
		["{quest:2846} in {area:978}"] = "{quest:2846} ({area:978})",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Вернитесь: {npc:8395}, затем наверх в башню.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Вернитесь: {npc:8395}, он телепортирует вас в башню.",
		["Experience"] = "Опыт",
		["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Опыт на 50-м уровне через зону {zone:1447} и {area:1417}; на Forever выбора предмета из классики может не быть.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like."] = "Летите в {area:3137} (Альянс) или {area:1237} (Орда). {npc:8395} разбил лагерь под башней своего учителя, недалеко к востоку от места {area:1237}: от развилки главной дороги зоны {zone:1447} у места {area:1221} идите прямо на север к скалам. Слезьте с транспорта, прежде чем он телепортирует вас наверх, иначе телепорт может не сработать. Тропа без противников ведет к NPC {npc:8379} на вершине башни; служитель наверху отправит вас вниз, сколько угодно раз.",
		["Morphaz"] = "Морфаз",
		["The {item:20085}"] = "Предмет: {item:20085}",
		["{item:20085}: Morphaz"] = "{item:20085}: Морфаз",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, верховный маг, стоит в святилище магов ({zone:1453}, {object:2101}); Динк ({zone:1455}) дает то же задание.",
		["{npc:7311}, one of {zone:1454}'s mage trainers in {object:173161}, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "Его дает {npc:7311}, один из учителей магов ({zone:1454}, {object:173161}); а также {npc:4567} ({zone:1458}) и {npc:3047} ({zone:1456}).",
		["{npc:8379} again"] = "{npc:8379}, снова",
		["{npc:8379}, in the tower"] = "{npc:8379}, в башне",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "Посох или сфера для левой руки на 10-м уровне: орки и тролли — здесь: {area:368}, нежить — на ферме в Тирисфале.",
		["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "На 10-м уровне {npc:2128}, учитель магов (локация: {area:159}) на втором этаже таверны {area:2119}, отправит вас к NPC {npc:4568} (зона: {zone:1458}). Взяв это задание, вы закроете себе задание {quest:1884}; если в журнале заданий есть {quest:1883} (из зоны {zone:1454} или {zone:1456}), сначала откажитесь от него, иначе {npc:2128} не даст вам это задание. (Тролль, взявший это задание здесь: {area:159}, следует шагам про Балнир; нежить, взявшая {quest:1884} в Сен'джине, — шагам про {area:368}.)",
		["Back to Un'thuwa"] = "Назад к Ун'Туве",
		["Ley or {item:9514} or Orb (Horde)"] = "Лей, {item:9514} или сфера (Орда)",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Ун'Тува",
} end)()
