t.guides["forever/class/mage/polymorph-pig"] = (function() return {
		["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Новый вид заклинания «{spell:118}»: цель становится свиньей, а не овцой.",
		["Back to {npc:8395} and up to the tower."] = "Вернитесь: {npc:8395}, затем наверх в башню.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "Летите в {area:3137} (Альянс) или {area:1237} (Орда). {npc:8395} разбил лагерь под башней, где живет {npc:8379}, недалеко к востоку от места {area:1237}: от развилки главной дороги зоны {zone:1447} у места {area:1221} идите прямо на север к скалам. Слезьте с транспорта, и он телепортирует вас наверх; тропа ведет к верховному магу на вершине башни.",
		["Polymorph Clones"] = "Клонированные овцы",
		["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}: {spell:118} (свинья)",
		["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "{npc:8408} (55-й уровень, не элитный, «Удар» и {spell:99}) прячется за стражей из клана Бича Злобы здесь: {area:1223}, самое большое здание в центре места {area:1221}. С него всегда падает {item:23250}, и он возрождается через 5 1/2 минуты после убийства. Сначала покиньте рейдовую группу: рейду убийство не засчитывается, обычной группе – засчитывается.",
} end)()
