t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "Назад в крепость",
		["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "Назад через всю долину. Цель: {area:16602}. Билмут внизу примет планы, затем {npc:246378}, снова наверху в крепости, научит вас: {spell:7328}.",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "Назад. Цель: {area:16602}. {npc:246378} даст вам {item:6866}; {npc:257655} ждет внизу в крепости. Если вы потеряете символ, {npc:246378} даст вам другой.",
		["Tarnished Drudges x8"] = "Порочные чернорабочие x8",
		["Tarnished Zealots x6"] = "Порочные фанатики x6",
		["The Scarlet attack plans"] = "Планы атаки Алого ордена",
		["The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "Мурлоки из племени Злобного Плавника (9-11-й уровень) скрываются на утесах вдоль дороги к востоку от крепости и в лагерях вокруг озера к юго-западу, по пути вниз: {area:16881}.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328} (Forsaken)"] = "Дозор Тира и {spell:7328} (Отрекшиеся)",
		["Vile Fin Attackers x8"] = "Налетчики из племени Злобного Плавника x8",
		["Vile Fin Seers x8"] = "Провидцы из племени Злобного Плавника x8",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Идите на юг от места {area:159}. Цель: {area:153}; спуститесь в {zone:1458}. {npc:10181} принимает здесь: {object:36126}; {npc:257648} попрошайничает здесь: {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after {quest:96896} from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602} стоит на утесах к северо-западу (ориентир: {area:156}; дорога на запад начинается около 29,46). {npc:246349} ждет у ворот. {npc:246389}, учитель крепости, и {npc:259190}, смотритель стойл, стоят на опушке леса чуть южнее него. Работа для вас у них будет только с 10-го уровня и после задания {quest:96896} от Леонида в крепости, которым завершается цепочка NPC {npc:267009}, начинающаяся к юго-востоку от места {area:159}; берите их задания, когда увидите.",
		["{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health."] = "{npc:1569} даст вам предмет {item:282423} после задания {quest:364}: прочтите его, затем отнесите NPC {npc:244808} у церкви. Он попросит вас исцелить пятерых NPC {npc:259377}, лежащих вокруг места {area:154}. {spell:635} каждый раз немного ранит паладина-Отрекшегося: следите за здоровьем.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it. {quest:91317} need level 9."] = "{npc:246378} руководит орденом из крепости; {npc:246393} стоит рядом с ней. Для заданий {quest:91317} нужен 9-й уровень.",
		["{npc:246378} offers the first Lesson in Divinity at level 12. Bring 10 {item:2589} if you have it: the {zone:1458} asks for it next."] = "{npc:246378} дает первый урок божественности на 12-м уровне. Если есть, захватите {item:2589} (10 шт.): следом их попросят в городе {zone:1458}.",
		["{npc:257648} needs 10 {item:2589}. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too."] = "{npc:257648} нужно 10 шт.: {item:2589}. Она падает с гуманоидов: с ревнителей и келейников Алого ордена в долине – примерно в трех случаях из десяти. Ее также продают на аукционе Подгорода.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328} для воскрешения павших союзников, а также оружие и щит для нового паладина-Отрекшегося.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "На 20-м уровне {npc:6179}, наверху ({object:32386}, {object:32362}), дает вам {item:6776}. Щелкните по нему правой кнопкой: он отправляет вас к NPC {npc:6171} в Собор Света ({zone:1453}). Сядьте на {area:2257} из города {zone:1455} в город {zone:1453}.",
