		["The {item:6995}"] = "{item:6995}",
		["The {item:7083}"] = "{item:7083}",
		["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} – подземелье для группы из пяти игроков под деревней {area:20}; портал подземелья – в глубине шахты ({area:20}). Гоблины-древорубы (элитные, 18-19-й уровень) в корабельном зале, где Снид, всегда оставляют древесину.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, в шахте ({area:20})",
		["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171} стоит в Соборе Света. Люди получают {item:6776} у него. Щелкните правой кнопкой мыши по книге, чтобы начать ее задание, и сразу сдайте его ему же.",
		["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181} работает у ворот города {zone:1455}, а не внутри. Он дает вам {item:6996}: четыре части, в любом порядке. Сохраните записи.",
		["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241} превращает руду в {item:6993} – деталь, которая нужна Джордану.",
		["{object:91138}, inside"] = "{object:91138}, внутри",
		["{object:92420} crate"] = "Ящик: {object:92420}",
} end)()
