		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "На 10-м уровне {npc:1234}, учитель разбойников ({area:2102}, {area:131}), отправляет вас к персонажу {npc:5165} ({zone:1455}).",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "На 10-м уровне {npc:3599}, учитель разбойников в таверне ({area:186}), дает вам розу для персонажа {npc:4163} ({zone:1457}). Если потеряете розу, откажитесь от задания и возьмите его снова.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "На 10-м уровне {npc:917}, учитель разбойников наверху в таверне ({area:87}), дает вам сверток для персонажа {npc:332} ({zone:1453}). Изучите {spell:921}, если еще не знаете: эта цепочка требует этого навыка.",
		["Back to Mathias Shaw"] = "Назад к Матиасу Шоу",
		["Back to {npc:4163}"] = "Назад: {npc:4163}",
		["Back to {npc:5165}"] = "Назад к {npc:5165}",
