t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "На 16-м уровне {npc:1234} ({area:2102}, {area:131}) отправляет вас к NPC {npc:5165} ({zone:1455}, {object:32383}).",
		["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "На 16-м уровне {npc:3599} в таверне ({area:186}) отправляет вас к NPC {quest:2259} ({zone:1457}).",
		["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "На 16-м уровне {npc:917}, учитель разбойников наверху в таверне «Гордость льва» ({area:87}), отправляет вас к NPC {npc:6946} ({zone:1453}). Если взять это задание, подобные задания из других городов станут недоступны.",
