} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "На 16-м уровне {npc:3170}, учитель разбойников ({area:362}), отправляет вас к персонажу {npc:3401} ({zone:1454}).",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "На 16-м уровне {npc:6467} ({object:36073}) отправляет вас к персонажу {npc:3401} ({zone:1454}). Возьмите у него и задание «{quest:1998}»; оно выполняется в конце этого гайда ({zone:1421}).",
		["Back to {npc:6467}"] = "Назад к {npc:6467}",
		["Back to {npc:7161}"] = "Назад к {npc:7161}",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Десять шт. {item:7676} – энергетического напитка разбойников – за задания Орды по взлому замков на 16-м уровне.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Нежить летит на дирижабле от башен за пределами города ({zone:1458}) сюда: {zone:1411}. {npc:3401} и {quest:2379} стоят здесь: {object:172960} – ущелье под местом {object:172982}. Если у вас еще нет навыка {spell:1804}, изучите его сейчас у NPC {npc:3401} (или любого учителя разбойников): это задание – проверка взлома замков.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} и {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: десять шт. {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "На 20-м уровне {npc:332}, наверху в здании ШРУ ({object:2100}), отправляет вас к персонажу {npc:7024} ({zone:1436}). В Forever яды изучаются через эту цепочку, так что не пропускайте ее.",
		["Back to {npc:7207}"] = "Назад: {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever ядам учит эта цепочка, а не учитель; вместе с ними вы получите рецепт: {item:7676}.",
		["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol. Then sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Сначала добудьте ключ. {npc:7051} (23-й уровень, не элита) начинает у входа в башню и ходит по кругу снаружи; это тот, что с торчащими волосами и желтыми искрами. Уйдите в незаметность и примените {spell:921} сзади: ключ у него всегда. Он больно бьет: если незаметность спадет, убегайте ({spell:2983}). Остерегайтесь пары мертвяков из Братства Справедливости, которые тоже патрулируют. Затем прокрадитесь вверх по башне. Этажи охраняют патрульные башни из Братства Справедливости (23) и часовые (24); Внезапный удар кинжалом убивает их сразу, если хотите их зачистить. {npc:7053}, элита 26-го уровня, ждет на верхнем этаже: оглушите его Ошеломлением или позовите друга. {object:123214} у его стола требует Взлома замков около 70-75 (сначала потренируйтесь на ящиках у места {area:97} в Красногорье). Хитрость: пока часовых нет рядом, прыгните со стула на лампу, затем на книжную полку над сундуком, выйдите из незаметности и откройте сундук оттуда. Открыв его, вы получите яд {spell:9810}, который на время не дает уйти в незаметность и позволяет мертвяку вас увидеть; поэтому ключ – первым делом. Затем уходите.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Идите на север через Элвиннский лес в город {zone:1453}; Матиас Шоу – наверху в здании ШРУ. Он обучает навыку «Яды» и дает рецепт: {item:7676}. Яды не покупают, а делают: на каждую партию {spell:8681} нужны {item:2928} и {item:3371}, которые продают {npc:1325} и {npc:1326} здесь: {object:2100}, рядом со ШРУ. Купите по стопке каждого, откройте «Яды» в книге заклинаний, чтобы изготовить их, затем нанесите яд на оружие.",
		["Poisons (Alliance)"] = "Яды (Альянс)",
		["The cure's ingredients"] = "Ингредиенты лекарства",
		["{item:7908}: the {object:123214}, top floor"] = "{item:7908}: {object:123214}, верхний этаж",
		["{npc:7053} on the top floor is a level 26 elite: easier at 24 or with a friend. Get the key first: the {npc:7051} (level 23, the spiky-haired one trailing yellow sparkles) walks a loop around the tower; stealth up and {spell:921} it from behind. Then up the tower past the Defias Tower Patrollers (23) and Sentries (24) to the {object:123214} beside Klaven's desk (Lockpicking about 70-75). Opening it poisons you with the {spell:9810}, which stops your stealth for a while."] = "{npc:7053} на верхнем этаже – элита 26-го уровня: проще на 24-м или с другом. Сначала добудьте ключ: {npc:7051} (23-й уровень, тот, что с торчащими волосами и желтыми искрами) ходит по кругу вокруг башни; уйдите в незаметность и примените {spell:921} сзади. Затем поднимитесь по башне мимо патрульных башни из Братства Справедливости (23) и часовых (24) к объекту {object:123214} у стола Клейвена (Взлом замков около 70-75). Открыв его, вы получите яд {spell:9810}, который на время не дает уйти в незаметность.",
		["{quest:2359}, solo"] = "{quest:2359}, в одиночку",
		["{quest:2359}, with a group"] = "{quest:2359}, с группой",
		["{spell:921} the {npc:7051} for the {item:7923}"] = "{spell:921}: {npc:7051} – добудьте {item:7923}",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/salute: {npc:3401}",
		["Back to {npc:3401}"] = "Вернитесь: {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Летите обратно в город {zone:1454} (из места {area:392} или с Перекрестка; быстрее умереть у башни и вернуться к Перекрестку через целителя душ). Потом сохраните {item:8072}. Прежде чем покинуть {area:263}, купите у Реккула {item:2928} и пустые колбы: когда Хинотт обучит вас ядам, на каждую партию {spell:8681} понадобится по одному из каждого.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "В Forever яды изучаются через эту цепочку, а не у учителя; заодно вы получаете рецепт: {item:7676}.",
		["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back. Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "Держите {item:8066} в сумках и используйте его на нем каждый раз, подходя ближе, иначе он станет враждебным. {npc:7287} (22-й уровень) ходит у башни: прижмитесь к стене, подкрадитесь к нему сзади в незаметности и примените {spell:921}, чтобы забрать ключ. При убийстве ключ не падает; если карманы пусты, убейте его и подождите 4,5 минуты, пока он не вернется. Внутри, этаж за этажом (все возрождается через 4,5 минуты): мутировавшие мертвяки Торговой компании (25-й уровень) на первом этаже умирают от одного Внезапного удара кинжалом; патрульные на втором этаже теряют половину здоровья от {spell:1943} на одно очко; дозорные на открытом третьем – от {spell:2098} на одно очко. {npc:7288} ждет на верхнем этаже: элита 23-го уровня, возрождается через 10 минут после убийства. Начните с Внезапного удара (около половины его здоровья), затем {spell:1776}, {spell:5277}, лечебное зелье и {item:7676}; с другом будет легко. Одна голова за убийство. Затем вскройте {object:129127} рядом с ним ради тайника: вы получите яд {spell:9810}, ослабляющий незаметность и ловкость, пока {npc:2391} его не вылечит.",
		["Pick Pocket Foreman Silixiz for {item:8072}"] = "Обшарьте карманы бригадира Силиксиза: {item:8072}",
		["Poisons (Horde)"] = "Яды (Орда)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon."] = "Сядьте на дирижабль из города {zone:1454} в {zone:1458} и идите по дороге на юг через зону {zone:1421} в {area:287}, к поселению {area:272}. {npc:2391} работает в здании рядом с точкой полетов, возле NPC {npc:2216}, снаружи стоит повозка. Если вы потеряли образец смеси Занзила, откажитесь от задания и возьмите его снова у NPC {npc:3401}. Постойте рядом с ним около минуты, пока он варит лекарство; если оно так и не будет готово, откажитесь от задания и возьмите его у него снова. Затем откройте «Яды» в книге заклинаний, чтобы сделать {spell:8681} из пыли и колб Реккула, и нанесите яд на оружие.",
		["The Venture Co. tower, solo"] = "Башня Торговой компании, в одиночку",
		["The Venture Co. tower, with a group"] = "Башня Торговой компании, с группой",
		["Wait for the cure"] = "Дождитесь лекарства",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (элитный)",
		["{npc:2391}: Poisons"] = "{npc:2391}: Яды",
		["{npc:7288} on the top floor is a level 23 elite: easier at 23 or with a friend. Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. First Pick Pocket Silixiz's Tower Key from {npc:7287} (level 22), who walks by the tower: stealth up behind him (killing him does not give it). Then clear the tower floor by floor (everything comes back after 4 1/2 minutes): Mutated Venture Co. Drones (25) on the ground floor, Patrollers on the second, Lookouts on the open third, Gallywix on top, back 10 minutes after a kill. Pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "{npc:7288} на верхнем этаже – элита 23-го уровня: проще на 23-м или с другом. Держите {item:8066} в сумках и используйте его на нем каждый раз, подходя ближе, иначе он станет враждебным. Сначала обчистите карманы NPC {npc:7287} (22-й уровень), который ходит у башни, и заберите ключ от башни Силиксиза: подкрадитесь к нему сзади в незаметности (при убийстве ключ не падает). Затем зачищайте башню этаж за этажом (все возрождается через 4,5 минуты): мутировавшие мертвяки Торговой компании (25) на первом этаже, патрульные на втором, дозорные на открытом третьем, Нервотреп наверху, возрождается через 10 минут после убийства. Вскройте {object:129127} рядом с ним ради тайника: вы получите яд {spell:9810}, ослабляющий незаметность и ловкость, пока {npc:2391} его не вылечит.",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: сохраните {item:8051}",
} end)()
