		["the locked reliquary in the Library"] = "запертая рака в библиотеке",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Назад к тайнику",
		["C's dead drop"] = "Тайник C",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210} – плата от C за одиночную работу здесь: {area:236}.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} – сундук в доме сразу за деревней {area:204} на юге Серебряного бора, к югу от места {area:236}. Откройте его и прочитайте записку C: работу нужно выполнить в одиночку, вне группы.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, внутри ({area:236})",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}, гоблин, дружелюбный к обеим фракциям, стоит среди Торговой компании ({area:461}), на востоке Когтистых гор, немного к северо-востоку от места {area:460}. Орда летит сюда: {area:460}; Альянс – сюда: {area:467}. Прежде чем отдать взрывчатку, он хочет {item:210187}: она лежит в карманах у лесорубов Торговой компании (уровень 18), работающих вокруг него. Подкрадитесь к одному в незаметности и примените {spell:921}; при убийстве предмет не выпадает.",
		["{spell:921} a {npc:3989} for a {item:210187}"] = "{spell:921}: {npc:3989} – получите {item:210187}",
} end)()
