t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 37 and 39."] = "Редкое тканевое одеяние для 30-х уровней от NPC {npc:6266}; последние его части ждут 37-го и 39-го уровней.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "На 31-м уровне {npc:3326} ({object:172960}) отправляет вас к персонажу {npc:6266} ({area:392}). Чтобы не ходить лишний раз, сначала купите {item:5770} и {item:3577} (следующие шаги).",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "На 31-м уровне {npc:461} ({object:2164}, {object:2101}) отправляет вас к персонажу {npc:6266} ({area:392}). Чтобы не ходить лишний раз, сначала купите {item:5770} и {item:3577} (следующие шаги).",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "На 31-м уровне {npc:5172} ({zone:1455}) отправляет вас к персонажу {npc:6266} ({area:392}). Чтобы не ходить лишний раз, сначала купите {item:5770} и {item:3577} (следующие шаги).",
		["Back to {npc:6266}"] = "Назад к {npc:6266}",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "Вернитесь к {npc:6266} с нитью, углями и предметом {item:6265}. Затем подождите рядом с ней, пока она работает над одеянием (не атакуйте ее: в журнале заданий это названо убийством), и снова поговорите с ней.",
		["Hatefury satyrs"] = "Сатиры из племени Ярой Ненависти",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25."] = "Сатиры из племени Ярой Ненависти (31-32 уровень) занимают {area:603} на крайнем северо-востоке зоны {zone:1443}, дальше места {area:608}: флакон падает в двух случаях из пяти, так что рассчитывайте примерно на 25 убийств.",
		["Vials of Hatefury Blood"] = "Фиалы крови сатира из клана Ярой Ненависти",
		["{npc:2670}: {quest:4785}, handed straight back"] = "{npc:2670}: {quest:4785}, сдается сразу обратно",
		["{npc:6266} again"] = "Снова {npc:6266}",
} end)()
