t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Посох, предмет для левой руки или роба для уровней 50-59; собственное поручение NPC {npc:14470}, не шаг цепочки коня погибели.",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "На 50-м уровне {npc:3326} ({object:172960}) отправляет вас к NPC {npc:14470} ({zone:1448}) с куском предмета {item:14256}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "На 50-м уровне {npc:4563} ({object:36082}) отправляет вас к NPC {npc:14470} ({zone:1448}) с куском предмета {item:14256}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "На 50-м уровне {npc:461} ({object:2164}, {object:2101}) отправляет вас к NPC {npc:14470} ({zone:1448}) с куском предмета {item:14256}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "На 50-м уровне {npc:5172} ({zone:1455}) отправляет вас к NPC {npc:14470} ({zone:1448}) с куском предмета {item:14256}.",
		["The {area:1417}"] = "{area:1417}",
		["{item:20613} and Bloodvenom"] = "{item:20613} и экстракт Ядовитой Крови",
		["{npc:14470} again"] = "Снова: {npc:14470}",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "На 20-м уровне {npc:6122} из подвала таверны ({object:2164}, {object:2101}) отправляет вас к персонажу {npc:6244} ({zone:1413}): для Альянса это долгий путь. Плывите на корабле из места {area:150} на Терамор и идите на запад через {zone:1445} или плывите из места {area:35} сюда: {area:392}.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "На 20-м уровне: суккуб и инкуб Forever – её двойник мужского пола, – и к каждому сумка для осколков души.",
		["Succubus and Incubus (Alliance)"] = "Суккуб и инкуб (Альянс)",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "На 20-м уровне {npc:5875} ({object:172960} под районом {object:172982}) отправит вас в нескольких шагах отсюда: {npc:5909}. Задания на этих демонов дают два учителя – {npc:5875} здесь и {npc:5675} ({zone:1458}), – и можно взять только одно; гайд следует тому заданию {quest:1507}, которое вы взяли. {npc:5909} предлагает обе ветки ({zone:1454}): возьмите обе.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "На 20-м уровне: суккуб и инкуб из Forever – ее брат-близнец мужского пола, – каждый с сумкой для осколков душ.",
		["Corma Villard"] = "Corma Villard",
		["Succubus and Incubus (Horde)"] = "Суккуб и инкуб (Орда)",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 27 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} – на юге зоны {zone:1440}, к юго-западу от места {area:431}. Чащобные камнедвиги и заскорузлые потрошители (25-27 уровень) у озера роняют {item:190232} примерно в одном случае из двадцати, и одинокий {npc:3931} (30) тоже может его уронить: рассчитывайте на немало убийств, поэтому гайд сначала ждет 27-го уровня (в Forever это задание 27-го уровня); если суккуб уже подчинена, можно отложить его до прокачки на 20-х уровнях в зоне {zone:1440}. Они возрождаются через пять минут.",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} держит {object:173018} на главной улице к востоку от места {object:172960}. Он просит найти его подругу Krilge ({zone:1440}).",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "Вариант для {object:1661} – для чернокнижников, взявших {quest:1472} у NPC {npc:5675}, а не у {npc:5875}. На 20-м уровне {npc:5675} ({object:36082}) отправит вас неподалеку. Цель: {npc:5693}. {npc:5693} покажет вам образ каждой добычи и предложит обе ветки: возьмите обе.",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Сфера для левой руки или посох ближе к 40-му уровню – на выбор путь гончей Скверны или инфернала.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:3326} ({object:172960}) отправит вас сюда: {npc:6266} ({area:392}).",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "На 35-м уровне {npc:4563} ({object:36082}) отправит вас сюда: {npc:6266} ({area:392}). Дирижабль из зоны {zone:1420} летит в зону {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:461} ({object:2164}, {object:2101}) отправит вас сюда: {npc:6266} ({area:392}).",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "На 35-м уровне {npc:5172} ({zone:1455}) отправит вас сюда: {npc:6266} ({area:392}).",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Вернитесь с очищенной сферой к {npc:6266} в башню над местом {area:392}. На пути гончей Скверны примите ее последнее задание и подождите рядом с ней, пока она завершит {item:15108} (не атакуйте ее: в журнале заданий это названо убийством), затем снова поговорите с ней и выберите сферу для левой руки или посох.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Сначала вернитесь с духом и самоцветом в башню над местом {area:392}. Цель: {npc:6266}. Затем – ее сфера.",
		["Choose an acolyte"] = "Выберите послушника",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "На пути инфернала примите ее последнее задание и подождите рядом с NPC {npc:6266}, пока она завершит {item:15107}, затем снова поговорите с ней и выберите сферу для левой руки или посох.",
		["Orb of Orahil"] = "Сфера Орахила",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Выберите одного послушника: можно взять только одно из их заданий. Путь гончей Скверны ({npc:6254}) заканчивается сферой или предметом {item:15106} – темными вариантами; путь инфернала ({npc:6252}) – сферой или предметом {item:15105}, почти такими же предметами огненной стороны. Большинство чернокнижников полагаются на тьму, но сначала сравните все четыре в подсказках. Гайд следует выбранному. Сохраните рубин или изумруд: его вернут.",
		["The demon's spirit"] = "Дух демона",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, добыча: {npc:4678}, {npc:4681} или {npc:4685}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, добыча: {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}: призыватели из клана Пылающего Клинка",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: он даст вам {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: она даст вам {item:12647}",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} и двое ее послушников стоят в башне NPC {npc:6251} на холме над местом {area:392}.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 40. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} живет на своей ферме в центре зоны {zone:1445}, к югу от дороги из зоны {zone:1413} и к юго-западу от Терамора; рядом стоит целитель душ. Зыбун, кроколиск 45-го уровня, патрулирует ручьи чуть к северо-востоку. Сдайте сферу сейчас; «Очищение» ждет 40-го уровня. Прежде чем взять его, перебейте пауков и кроколисков вокруг ее загона. Когда вы берете задание, запускается 3-минутный таймер: она идет к загону и выпускает противника {npc:6549}. Он элитный (40-й уровень): лучше собрать группу; чернокнижник около 40-го уровня справится в одиночку со «Страхом» или {spell:710} и периодическим уроном, на 38-м возьмите друга. Таймер идет и после убийства, поэтому сдайте задание сразу. Если время вышло, откажитесь от задания и снова возьмите его у NPC {npc:6546}.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Редкая сфера для левой руки или посох для 20-х уровней за фрагменты из двух подземелий.",
		["Back to {npc:6247}"] = "Назад: {npc:6247}",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "Осколки Соран'рука: со служителей из культа Сумеречного Молота, внутри",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}: с темных духов из крепости Темного Клыка, внутри",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Редкий предмет для левой руки на 50+ уровне от {npc:14469} и {npc:14470} (зона {zone:1448}); в том же лагере дают задание «Просьба беса».",
		["Back to {npc:14469}"] = "Вернитесь к {npc:14469}",
		["{area:1763} lies just south of {area:1997}, west of the road. The guide waits for level 54 first: its Legionnaires are 55. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} – чуть южнее места {area:1997}, к западу от дороги. Сначала гайд ждет 54-го уровня: его легионеры – 55-го. Из двух пещер {area:1770} – северная, выше по склону; в другой легионеров нет. Туннели ({area:1770}) идут на север под холмами, а джеденарские легионеры (55-й уровень) стоят в дальних залах, от первых пандусов до покоев NPC {npc:9516}; в ближнем бою они бьют «Апперкотом». Эссенция падает в трех случаях из четырех, но появляется их всего около одиннадцати: расчистите путь и, если нужно, переждите пятиминутное возрождение. Все культисты ({area:1763}, {area:1770}) враждебны.",
		["{item:18626}, at {object:179677}"] = "{item:18626} — у объекта {object:179677}",
} end)()
