t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:3041}, учитель воинов ({zone:1456}), отправляет вас к NPC {npc:6394} ({area:378}).",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:3354} ({object:172958}) отправляет вас к NPC {npc:6394} ({area:378}).",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "На 20-м уровне {npc:4595}, учитель воинов ({zone:1458}), отправляет вас к NPC {npc:6394} ({area:378}).",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "Вернитесь к {npc:5878}: {area:1699}. {quest:1848} – первая часть; затем он отправляет вас к трем мастерам, по одному на часть: возьмите все три задания.",
		["Hillsbrad Miners"] = "Хилсбрадские шахтеры",
		["Iron Bars"] = "Железные слитки",
		["Iron Bars: {npc:8673}"] = "Железные слитки: {npc:8673}",
		["Roogug in {area:1717}"] = "Ругуг. Локация: {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 30 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Ругуг – элитный свинобраз (28-й уровень) в подземелье {area:1717} на южной окраине зоны {zone:1413}; подземелье на пятерых: нужна группа из пяти человек, с ним приходят его стражи. Сначала гайд ждет 30-го уровня. Внутри на первой развилке идите налево, перейдите мост из лиан над свинарниками, пройдите мимо зала с большим котлом: он ждет в зале справа. Он применяет {spell:403} и призывает земляных грохотунов. Флакон падает всегда.",
		["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "Начинается сейчас, на 20-м уровне, у вашего учителя; четыре части доспехов на 30-м уровне (хауберк, шлем, рукавицы, поножи), а по пути еще и щит.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Сядьте на дирижабль из города {zone:1454} до зоны {zone:1420}; {npc:6411} работает здесь: {zone:1458}, {object:36078}. Ей нужны 8 крепких берцовых костей Драконьей Пасти.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Орки клана Драконьей Пасти (уровни 26-30) стоят лагерем в центре зоны {zone:1437}; из места {area:321} в Арати идите на юг через {area:881} ({area:150} принадлежит Альянсу). Если в журнале есть задание {quest:1846} от NPC {npc:6411}, с каждого налетчика, болотного бегуна, центуриона, хранителя теней и костостража падает {item:7131} (без задания не падает ничего): щелкните по ней правой кнопкой мыши, чтобы проверить; примерно одна из четырех оказывается прочной, остальные ломаются, так что на 8 штук понадобится 30 убийств или больше. Проверять можно на ходу или в бою. Орки убегают за помощью при 15% здоровья; налетчики набрасывают сеть, центурионы бьют щитом, хранители теней применяют {spell:686}, костостражи поднимают скелетов.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "Вам нужно 10 железных слитков. Шахтеры выплавляют их из руды ({item:2772}, одна руда на слиток, {spell:3307} при навыке {skill:186} 125); остальные покупают их на аукционе ({zone:1454}).",
		["You need 10 {item:7127}. The guide waits for level 30 first ({quest:1838} is a level 30 quest). The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Нужно 10 шт. {item:7127}. Сначала гайд ждет 30-го уровня ({quest:1838} – задание 30-го уровня). Хилсбрадские шахтеры (26-27 уровень) работают в шахте на холмах к западу от места {area:271} и роняют азурит в четырех случаях из пяти; они дерутся в защитной стойке ({spell:71}), раскалывают вашу броню и при 30% здоровья бегут за подмогой. Летите сюда: {area:272}, и идите на юго-запад.",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}: {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841} с Ругуга",
		["{item:7119}, from the silithid"] = "{item:7119} с силитидов",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126} с кобольдов из племени Ветрорезов",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127} с хилсбрадских шахтеров",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest, so the guide waits for level 29 before you take it. {item:7587} list where each material comes from."] = "Хижина NPC {npc:5878} стоит на вершине: {area:1699}, к востоку от Перекрестка; поднимайтесь по широкому гребню с северной или восточной стороны. {quest:1838} – задание 30-го уровня, поэтому гайд ждет 29-го уровня, прежде чем вы его возьмете. В предмете {item:7587} указано, откуда берется каждый материал.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} находится здесь: {area:367}, на побережье зоны {zone:1411}. Ему нужны 7 нерасщепленных копыт сатира.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "На 20-м уровне {npc:5113}, учитель воинов ({zone:1455}), отправляет вас к NPC {quest:1698} в Красногорье.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "На 20-м уровне {npc:5479}, рядом с NPC {npc:5480} в здании учителей воинов ({object:2100}), отправляет вас к NPC {quest:1698} в Красногорье.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "На 20-м уровне {npc:7315}, учитель воинов ({zone:1457}), отправляет вас к NPC {quest:1698} в Красногорье.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Вернитесь за хауберком: {npc:5413} ({object:28027}). Затем он отправит вас к кузнецу вашей расы; части двух других кузнецов вам тоже доступны: поговорите с ними напрямую.",
		["Charred and Galvanized Horns"] = "Обугленные и гальванизированные рога",
		["Enter the {area:98} and come back; below ground, at the first fork"] = "Войдите сюда и вернитесь: {area:98}; под землей, у первой развилки",
		["Fire Hardened Armor"] = "Закаленный огнем доспех",
		["Roogug in {area:1717}"] = "Ругуг — {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. The guide waits for level 28 first. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Ругуг – элитный свинобраз (28-й уровень) в подземелье {area:1717} на южной окраине зоны {zone:1413}; подземелье на пятерых: нужна группа из пяти человек, и с ним приходят его стражи. Сначала гайд ждет 28-го уровня. Внутри на первой развилке идите налево, перейдите мост из корней, пройдите мимо большого пустого котла: он в тупике справа, по пути около десяти элитных противников. Он применяет {spell:403} и призывает земляных грохотунов. Флакон падает всегда.",
		["Scorched Spider Fangs"] = "Опаленные паучьи клыки",
		["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Начинается с 20 уровня со щита; на 28 уровне – кольчуга, затем капюшон, поножи и рукавицы у трех кузнецов.",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five; the guide waits for level 28 first. The Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Воргены из стаи Ночной Погибели в зоне {zone:1431} (вестники Тьмы, Ярые Клыки, тенеткачи, воргены и нечистые воргены, 26-31 уровень) к югу и западу от места {area:42} роняют {quest:1705} в четырех случаях из пяти; сначала гайд ждет 28-го уровня. Нечистые воргены отравляют и воют; Ярые Клыки вызывают {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}; the guide waits for level 28 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Химеры живут к юго-западу от места {area:460}, здесь: {area:465}; сначала гайд ждет 28-го уровня. Нужно 12 обугленных рогов с химер-слетков (25-27 уровень) и молодых химер (23-25) – падают в четырех случаях из пяти, – и {item:6840} с NPC {npc:6167} (28, самая большая), тоже в четырех случаях из пяти. Там живут всего три слетка, две молодые химеры и одна матриарх, каждая возрождается через 5 минут, так что придется подождать. Слетки и матриарх плюются ядом ({spell:3396}), молодые применяют {spell:403}. Альянс: летите сюда: {area:467}, и идите на юг.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once: the guide waits for level 30 first."] = "Панцири лежат на земле под гнездами виверн ({area:482}) на западе зоны {zone:1441}, в глубине ущелья. Их всего девять, и каждый появляется снова через 3 минуты после того, как вы его подберете, так что придется подождать; некоторые похожие на панцири предметы подобрать нельзя. Их охраняют виверны Скального гнездовья (28-31 уровень), иногда нападая по несколько сразу: сначала гайд ждет 30-го уровня.",
		["The {area:98}"] = "{area:98}",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang, but the Highland Horrors and Lurkers (elites, 28-29) roam the same ground, so the guide waits for level 28. The spiders poison; back in 5 minutes."] = "Нужно 50 клыков. Ловцы-кровопийцы и пещерные ловцы (21-22 уровень) ползают в центре зоны {zone:1437}, к северу от места {area:836}; с каждого падает клык, но там же бродят ужасы нагорья и затаившиеся (элита, 28-29), поэтому гайд ждет 28-го уровня. Пауки отравляют; возрождаются через 5 минут.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}: с молодых химер",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}: {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841} — с Ругуга",
		["{item:6845}, from {npc:6170}"] = "{item:6845}: {npc:6170}",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield."] = "{npc:5413} работает в Квартале дворфов Штормграда. Он забирает {item:6843} (потеряли? откажитесь от задания, и {npc:6166} даст новый) и дает вам щит: {item:6970}.",
		["{npc:5413}'s next task, {quest:1701}, is a level 28 quest: its chimaeras and Roogug are level 28, so the guide waits for level 27 before you take it. Come back to {npc:5413} in the {object:28027} then; {item:6842} list what it needs."] = "Следующее поручение NPC {npc:5413}, {quest:1701}, – задание 28-го уровня: химеры и Ругуг в нем 28-го уровня, поэтому гайд ждет 27-го уровня, прежде чем вы его возьмете. Тогда возвращайтесь к NPC {npc:5413} ({object:28027}); что нужно, перечислено в предмете {item:6842}.",
		["{npc:6170} (level 32, not elite) carries the {item:6845}, four kills in five; the guide waits for level 32 first. He walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. He poisons and howls."] = "{npc:6170} (32-й уровень, не элитный) носит {item:6845}, падает в четырех случаях из пяти; сначала гайд ждет 32-го уровня. Он ходит между глубиной и входом шахты ({area:2161}) к юго-востоку от места {area:42}, так что ждите у входа и выманите его наружу. Он отравляет и воет.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed, and it is a level 22 quest, so the guide waits for level 21 before you take it: before that, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} сидит в таверне ({area:69}). Его испытание ограничено по времени, и это задание 22-го уровня, поэтому гайд ждет 21-го уровня, прежде чем вы его возьмете: до этого перебейте гноллов Красногорья на пути к месту {area:98} на холмах к северо-западу от места {area:69}, включая двух на скале у входа в пещеру (забирайтесь на нее справа).",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}: с воргенов Ночной Погибели",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["Back to {npc:294}"] = "Вернитесь: {npc:294}",
		["{spell:71} and a Weapon (Alliance)"] = "{spell:71} и оружие (Альянс)",
		["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} на 10-м уровне и одноручное оружие на выбор из городов {zone:1453}, {zone:1455} или {zone:1457}.",
} end)()
t.guides["forever/class/warrior/heirloom-weapon"] = (function() return {
