t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Снова на восток через мост и вверх по тропе к святилищу NPC {npc:5900}. {npc:5900} делает из смолы и мешочка предмет {item:6636}. Используйте его у жаровни рядом с ним, чтобы появился {npc:5893}; убейте его ради предмета {item:6655}, затем положите уголек в жаровню.",
		["Back north along the beach to {area:392}."] = "Вернитесь на север вдоль пляжа: {area:392}.",
		["Bristleback camps"] = "Лагеря Дыбогривых",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Примените {spell:18960}. {npc:11802} стоит наверху в своем доме, здесь: {area:2361}. Поднимитесь внутри: стрелка не различает этажи.",
		["Crossroads flight master"] = "Распорядитель полетов на Перекрестке",
		["Down the {area:458} to {area:378} again."] = "Снова на юг по дороге ({area:458}). Цель: {area:378}.",
		["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "На восток к пляжу, у южного края лагеря пиратов: там стоят ящик с сапогами и хрупкий ящик с линзой, а рядом стоит {npc:3467} (16).",
		["Finish the Raptor Heads"] = "Доберите головы ящеров",
		["Follow the {area:458} south to {area:378}."] = "Идите по дороге ({area:458}) на юг. Цель: {area:378}.",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["He gives you the {item:15826}"] = "Он даст вам {item:15826}",
		["Inside"] = "Внутри",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Сохраните: {npc:12696} ({zone:1440}), следующий гайд",
		["Keep {npc:3446}'s {quest:865} and {npc:3467} for the next {area:392} stop, at 18: Scytheclaws you meet on the plains before then drop the horns too."] = "Оставьте задание {quest:865} от NPC {npc:3446} и {npc:3467} до следующего захода сюда: {area:392}, на 18-м уровне; смертехваты, встреченные на равнинах до этого, тоже роняют рога.",
		["Kolkar camp"] = "Лагерь Колкар",
		["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Потерявшиеся степные кодо бродят по равнинам вокруг лагеря Колкар к северо-западу от {npc:3389}; травники там же собирают {item:2449}.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate."] = "На север по дороге ({area:458}) к Перекрестку: {npc:3448} – у южных ворот, {npc:3432} – у таверны, {npc:3428} – к западу от северных ворот.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "На север по дороге ({area:458}) к Перекрестку: {npc:3448} – у южных ворот, {npc:3432} – у таверны, {npc:3428} – к западу от северных ворот. Сохраните {item:5075}: {npc:3430} примет его при следующем заходе сюда: {area:378}.",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "На обратном пути вниз по тропе ({area:1076}) {npc:11856} удерживают в хижине NPC {npc:11858} у поворота дороги. Как только вы возьмете ее задание, она сразу пойдет на юго-восток к месту {area:2538}, в сожженную деревню, не дожидаясь вас: держитесь рядом, иначе задание будет провалено.\nОсторожно: в сожженной деревне на нее нападут трое из племени Зловещего Тотема, и атаковать они будут ее, а не вас: отвлеките их на себя и побыстрее убейте заклинателя.",
		["Raptor Heads as you go"] = "Головы ящеров по пути",
		["Razormane camp"] = "Лагерь Иглогривых",
		["South along the beach past the pirate camp to {area:385}, on the coast. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "На юг вдоль берега мимо лагеря пиратов к месту {area:385} на побережье. С тераморских стражей бухты и хранителей (15-16) падают медали; {npc:3393} (20) и двое канониров (19) стоят в крепости и на ее стенах.\nОсторожно: каждую цель сопровождают лекарь и стража, а с Гордостанной еще три стража бухты. Если первым убить лекаря, бой будет проще.",
		["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them back in {area:392}; any still missing come with {npc:3682}'s hills later.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Яркочешуйчатые смертехваты охотятся на равнинах вокруг места {area:1697}; с них падают рога. {npc:3446} примет их в поселении {area:392}; недостающие добудете позже в холмах NPC {npc:3682}.\nНа юго-восток к побережью: украденное серебро лежит в гнезде ящеров к северо-западу от места {area:385}.",
		["Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health."] = "Яркочешуйчатые ящеры бродят по равнинам к северу и востоку от Перекрестка, примерно с трех из четырех падает голова: убивайте встречных по пути. Осторожно: яркочешуйчатые крикуны при здоровье ниже 30% зовут союзников в радиусе 30 м.",
		["The Razormane camp lies east of the Crossroads. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}.\nCareful: The chest stands next to a broken wagon, guarded by a pair of Razormanes, including hunters that can pull more quilboar into the fight."] = "Лагерь Иглогривых находится к востоку от Перекрестка. Воины: {object:58369} стоит в лагере. Шаманы: с кабанолюдов падает {item:5026}.\nОсторожно: сундук стоит рядом со сломанной повозкой, его охраняют двое Иглогривых, включая охотников, которые могут привлечь в бой других кабанолюдов.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "{item:5097} падает с надзирателей и головорезов Торговой компании у рудника в северо-восточном углу зоны.",
		["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them. {npc:3467} (16) stands at the camp's southern end: leave him for the next {area:392} stop."] = "Пираты разбили лагерь на пляже к югу от поселения {area:392}: груды сложных деталей лежат в песке среди них. {npc:3467} (16) стоит в южном конце лагеря: оставьте его до следующего захода сюда: {area:392}.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "Пруды – сразу к северу от NPC {npc:3389}. Зайдите в воду, чтобы исследовать их; спелые грибы для Хелбрима растут вокруг. Убивайте всех встречных Колкар ради наручей. {npc:3394} стоит в лагере Колкар к западу от прудов.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Дорога поднимается на север – {area:1076}. Хижина: {quest:1483} – там, где дорога сворачивает на восток к месту {area:461}.",
		["The {object:177794} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177794} лежит у северного края места {area:382}, у башни Торговой компании. В нем – {item:15883} для задания {quest:30}.",
		["The {object:3972} poster: {npc:3467} comes on the next {area:392} stop too"] = "Плакат «{object:3972}»: {npc:3467} – тоже при следующем заходе сюда: {area:392}",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "{object:4141} стоит на исследовательской площадке Торговой компании к западу от места {area:382}. Закройте три вентиля вокруг бура, снова используйте пульт, затем заберите {item:5089} у NPC {npc:3471} рядом.\nОсторожно: несколько стражей стоят в зоне агрессии у вентилей, возрождаются менее чем через 3 минуты и при малом здоровье убегают за подмогой; ближайшие противники тоже вмешиваются, если вы используете вентиль рядом с ними.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard (level 24), roams among them: his Tailspike starts a quest. Leave him alone below level 23."] = "Громоголовы пасутся на равнинах чуть южнее места {area:378}. Среди них бродит синий громоящер {quest:884} (24-й уровень): его хвостовой шип начинает задание. Не трогайте его, пока у вас нет 23-го уровня.",
		["Upstairs"] = "Наверху",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "На запад от сожженной деревни к месту {area:2539}: {npc:12816} стоит прямо перед деревней.",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "На запад к сторожевому посту NPC {npc:3389} на границе с Колкар.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}: из объекта {object:177785} в озере",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449}: продает {npc:3490}; травники собирают на равнинах",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} ({area:2361}) отправляет туда друидов по воздуху",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: приветствие от {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, в хижине NPC {npc:11858}",
		["{npc:3389}: {npc:3395} comes out when you kill the Kolkar at the {area:388}, later"] = "{npc:3389}: {npc:3395} появляется, когда вы убиваете Колкар у места {area:388}, позже",
		["{npc:3391}, upstairs"] = "{npc:3391}, на втором этаже",
		["{npc:3391}: the crates lie at the south end of the beach camp, on the next {area:392} stop at 18"] = "{npc:3391}: ящики лежат в южном конце лагеря на пляже, при следующем заходе сюда: {area:392}, на 18-м уровне",
		["{npc:3395} doesn't wander on his own: he comes out when you kill the Kolkar centaurs at the {area:388}, south-east of the Crossroads. Keep killing them around the oasis until he appears. Test {npc:3448}'s seeds at the bubbling fissure on the oasis' east bank while you are there."] = "{npc:3395} не бродит сам по себе: он появляется, когда вы убиваете кентавров Колкар у места {area:388} к юго-востоку от Перекрестка. Убивайте их вокруг оазиса, пока он не появится. Раз уж вы там, проверьте семена NPC {npc:3448} у бурлящей расщелины на восточном берегу оазиса.",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, на вершине башни",
		["{npc:3430}, in the cage"] = "{npc:3430}, в клетке",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} предложит {quest:95774}, когда будет сдано задание {quest:4921}",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: пульт управления – {area:382}, позже",
		["{npc:3446}, beside the {object:3972} poster"] = "{npc:3446}, рядом с плакатом ({object:3972})",
		["{npc:3446}, beside the {object:3972} poster: the Sunscale raptors come on the next {area:392} stop, at 18"] = "{npc:3446}, рядом с плакатом «{object:3972}»: яркочешуйчатые ящеры – при следующем заходе сюда: {area:392}, на 18-м уровне",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} закован в цепи внутри крепости. Поговорите с ним, чтобы начать сопровождение, и держитесь рядом: на выходе нападут солдаты Терамора. Он доведет вас обратно. Цель: {area:392}.",
		["{npc:3615}, on the tower"] = "{npc:3615}, на башне",
		["{npc:4201}, inside"] = "{npc:4201}, внутри",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} стоит лагерем у дороги на восток к месту {area:392}.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, ваш {item:5176} и {item:263412}",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} – {object:172961}, на западе города.",
		["{quest:1483}, inside"] = "{quest:1483}, внутри",
		["{quest:1492}, on the dock"] = "{quest:1492}, на причале",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, следующий гайд",
		["{quest:809}, beside {npc:3337}: from {npc:3216} in {zone:1454}"] = "{quest:809}, рядом с NPC {npc:3337}: от NPC {npc:3216} из города {zone:1454}",
		["{zone:1454} class quests"] = "Классовые задания: {zone:1454}",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Allister's Ambermill Investigations is for the ride through Silverpine at 22; leave it."] = "«Расследование в Янтарной мельнице» Аллистера – для поездки через Серебряный бор на 22-м уровне; не берите его.",
		["Class trainer"] = "Учитель классовых навыков",
		["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing."] = "Идите от мурлоков на юг вдоль берега озера: {object:1593} – у паромной пристани.",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Идите вдоль берега озера на юго-восток от дома Йориков: живорезы и волноловы из племени Злобного Плавника на берегу роняют глаза мурлоков.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Идите по дороге на северо-восток к дому Йориков: {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood. Careful: Dalaran Apprentices (13) stand around the crate: pull them one at a time before you open it."] = "Идите по дороге на юг. {object:1627} стоит у дороги, к северу от Деревни Погребальных Костров. Осторожно: вокруг ящика стоят ученики Даларана (13): выманивайте их по одному, прежде чем открыть его.",
		["From the ferry back west up the road to the {area:228}."] = "От парома обратно на запад по дороге: {area:228}.",
		["Inside"] = "Внутри",
		["Mottled Worgs"] = "Крапчатые ворги",
		["Mottled Worgs prowl the hills around the house."] = "Крапчатые ворги рыщут по холмам вокруг дома.",
		["North again to the Yoricks' house."] = "Снова на север к дому Йориков.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field. Careful: {npc:1983} (14) rises once you have killed rot hide gnolls in the field: fight her with full health."] = "К северу от места {area:228}. {npc:1983} бродит по {area:240}: убейте ее, затем пройдите через поле. Осторожно: {npc:1983} (14) появляется, как только вы убьете гноллов из племени Гнилошкурых на поле: сражайтесь с ней с полным здоровьем.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Поговорите с NPC {npc:10181} ({object:36126}): {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Поговорите с NPC {npc:10540} в Крепости Громмаш",
		["Speak with {npc:3230}, in Grommash Hold"] = "Поговорите с NPC {npc:3230} в Крепости Громмаш",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Идите по дороге на север ({zone:1420}): дом Йориков ({area:238}) по пути. {quest:425} прячется недалеко к западу от него.",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Рогоз и копейник растут вдоль воды – {object:172958}, к востоку от Волока.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960} – ущелье под местом {object:172982}; {quest:829} стоит в дальнем конце.",
		["Vile Fin murlocs"] = "Мурлоки из племени Злобного Плавника",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:6929} keeps the inn below it, {npc:268701} stands by the bank. Bind here: the Hearthstone brings you back from {zone:1421} beside the zeppelin towers and the road to the {zone:1413}."] = "Войдите через главные ворота. {npc:3310}, распорядитель полетов, стоит на башне ({object:172982}); {npc:6929} держит таверну под ней, {npc:268701} стоит у банка. Привяжите камень возвращения здесь: он вернет вас из зоны {zone:1421} к башням дирижаблей и дороге в зону {zone:1413}.",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Войдите через главные ворота. {npc:268701} стоит здесь: {object:172982}.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} – недалеко на север по дороге от башен дирижаблей; {npc:1499} – в ратуше.",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} – городок Отрекшихся у склепа посреди леса. Все нужные NPC стоят у входа в склеп; {npc:2226}, укротитель летучих мышей, – чуть к востоку.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, в Районе Фармацевтов",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, учитель алхимии, стоит по соседству с NPC {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, учитель наложения чар, работает на Волоке.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: для Квинна, на дороге на север в конце",
		["{npc:1952}, below ground"] = "{npc:1952}, под землей",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} ждет к северо-востоку от дома. Проводите его к NPC {npc:1950}; по пути нападают ворги.",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: {npc:4556} – {zone:1458}, в конце этого гайда; покупать полет не нужно",
		["{npc:246152}, in {area:159}"] = "{npc:246152}, здесь: {area:159}",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, учитель портняжного дела, находится здесь: {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} и {npc:3347} держат лавку алхимии на Волоке; {npc:11046} – по соседству.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, учитель кожевничества, работает здесь: {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, учитель травничества, держит лавку на Волоке.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{npc:4551}, the bat handler"] = "{npc:4551}, укротитель летучих мышей",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: сохраните {item:16210}, Подриг заберет его на следующей остановке – {area:228}, на 22 уровне",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, торговец оружием рядом с укротителем летучих мышей",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, учитель инженерного дела, работает здесь: {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, учитель горного дела, работает здесь: {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, учитель кузнечного дела, работает здесь: {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: «Основы походной жизни», от костра NPC {npc:265812} в Тирисфальских лесах",
		["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} стоит в Крепости Громмаш. Он предлагает задания {quest:98024} и {quest:93739}, когда сдано задание {quest:95350}.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, внутри Крепости Громмаш",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}: сохраните, Торк на Перекрестке в гайде по зоне {zone:1413}",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, обход вождей Орды",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, учитель снятия шкур, стоит здесь: {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: «Основы походной жизни», от костра Бракка – {zone:1411}",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} сдается не персонажу, а объекту {object:24776} – могиле в нескольких шагах к югу от входа в склеп.",
		["{quest:829}: {quest:809} stands at {area:379}, on the next guide's road to the Crossroads"] = "{quest:829}: {quest:809} стоит здесь: {area:379}, на дороге к Перекрестку в следующем гайде",
		["{quest:829}: {quest:832}, from the {item:4903} in {zone:1411}"] = "{quest:829}: {quest:832}, из предмета {item:4903} (зона {zone:1411})",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "Назад на запад к хижине NPC {npc:4201}, по пути вниз к месту {area:2539}.",
		["Bael'dun fortress"] = "Крепость Бейл'дана",
		["Crossroads flight master"] = "Распорядитель полетов на Перекрестке",
		["Fly to {area:378}"] = "Лететь: {area:378}",
		["Fly to {area:392}"] = "Лететь: {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Идите по дороге на север к месту {area:467}. По пути пасутся беговые олени-рогачи ({npc:4018}); сокотвари ({npc:4020}), сумеречные бегуны ({npc:4067}) и волшебные дракончики ({npc:4016}) бродят в лесу под пиком, а кенарийские друиды занимают рощу там.",
		["Gaea Dirt Mounds"] = "Земляные курганы Геи ({object:177929})",
		["North up the road to {area:378}: your hearthstone takes you there if it is ready."] = "На север по дороге: {area:378}. Камень возвращения перенесет вас туда, если он готов.",
		["On down the {area:1076} to {area:2539}."] = "Дальше вниз по тропе ({area:1076}). Цель: {area:2539}.",
		["On up the {area:1076} from {npc:4201}' hut to {area:460}."] = "Дальше вверх по тропе ({area:1076}) от хижины ({npc:4201}) к месту {area:460}.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "К югу от Ганна дворфы Бейл'дана ведут раскопки ({area:359}). В котловане работают землечерпы и старшины; дневник – у NPC {npc:3392} (26): выманите его одного.\nОсторожно: землечерпы (21-22-й уровень) и старшины (22-23-й уровень) при 15% здоровья убегают за подмогой, так что в бой могут вступить другие дворфы.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "К юго-западу от Солнечного Камня лежит выжженная {area:465}. Посадите семена Геи в земляные курганы на дне долины; с огненных элементалей падают {item:16312}. Гарпии и душительницы из стаи Кровавой Ярости гнездятся на севере, душегубки и бродяжницы – на юге. Осторожно: пылающие разрушители, опаленные василиски и ведьмы бури из стаи Кровавой Ярости здесь 27-го уровня, а на дне долины тесно: выманивайте по одному и держитесь ее краев.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "Летательная машина дворфов стоит на площадке внутри раскопок. Используйте на ней {item:5021}, полученную от NPC {npc:3341}.",
		["The flying machine"] = "Летательная машина",
		["Up the {area:1076} to {npc:4201}' hut, where the road forks east to {area:461}: {npc:3442}'s orders are for him."] = "Вверх по тропе ({area:1076}) к хижине NPC {npc:4201}, где дорога сворачивает на восток к месту {area:461}: приказы NPC {npc:3442} – для него.",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, с любой гарпии из стаи Кровавой Ярости",
		["{item:5736}, from {quest:1096}"] = "{item:5736}, падает с цели {quest:1096}",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: сверкающие солнечные камни ({item:277936}) с гарпий из стаи Кровавой Ярости",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, рядом с NPC {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, наверху на уступе",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, на дереве чуть восточнее {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, распорядитель ветрокрылов, стоит на центральном возвышении: получите у него маршрут полета, если его у вас нет. {npc:3024} и {npc:4721} стоят недалеко к востоку от него.",
		["{npc:3428}, west of the north gate"] = "{npc:3428}, к западу от северных ворот",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, у северного края лагеря",
		["{npc:3442} stands beside the flight master you land at. His new orders go back to {npc:4201} on the {area:1076}, later in this guide."] = "{npc:3442} стоит рядом с распорядителем полетов, у которого вы приземлитесь. Его новые приказы позже в этом гайде вернутся к NPC {npc:4201} на тропе ({area:1076}).",
		["{npc:3442}: for {npc:4201}, on the way up the {area:1076}"] = "{npc:3442}: для NPC {npc:4201}, по пути вверх ({area:1076})",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, от NPC {npc:4201}",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "Следующее задание {npc:4198}, «Гордан», – на стороне Альянса в зоне {zone:1440}. Пропустите его.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, за воротами",
		["{npc:4201}, inside"] = "{npc:4201}, внутри",
		["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "{npc:4201}: {npc:4202}, наверху башни Торговой компании ({area:461})",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: склянка – в зоне {zone:1440}, следующий гайд",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Хижина ({npc:5899}) стоит на гребне над водопоем свинобразов, к югу от места {area:378}, по пути в {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: синий бурдюк наполняется в зоне {zone:1440}, следующий гайд",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: красный бурдюк из места {area:272}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Снова на юг по дороге. Там, где она сворачивает на восток в {area:287}, {npc:2214} ждет здесь: {area:285}.",
		["Back to the outpost."] = "Назад к заставе.",
		["Below ground"] = "Под землей",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "По дороге через Серебряный бор: {area:228}. От башен дирижаблей – на юг через Тирисфальские леса; от предмета {object:177844} – на юго-восток от побережья к дороге. {npc:2121} и {npc:1937} стоят у входа в склеп.",
		["Druid trainer"] = "Учитель друидов",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Все наги из клана Зловещего Хвоста вдоль берега к северу от заставы роняют головы.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "От лагеря Сирета идите на северо-восток через зону {zone:1413} к дороге к северу от Перекрестка; разбойники, идущие от башни Физзула, идут к ней на запад. {npc:8582} стоит на сторожевой башне ({area:1703}), где дорога входит в зону {zone:1440}.",
		["Naga brazier"] = "Жаровня наг",
		["Naga heads"] = "Головы наг",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "По пути на запад: {npc:267214} застрял в овраге к югу от главной дороги, к юго-востоку от места {area:415}. Вокруг бродят тенероги и медведи Ясеневого леса.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Выведите NPC {npc:271181} {npc:267214} из оврага к главной дороге за четыре минуты; если поддержание прервется, попросите {npc:267214} снова.",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["{item:15882}, from the {object:177844}"] = "{item:15882}, из ящика ({object:177844})",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, с NPC {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}: с измученных душ среди руин; под землей",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Дарталия – {area:272}",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} обучает паладинов – {area:159}, недалеко на север по дороге от башен дирижаблей. Возвращайтесь по той же дороге в Серебряный бор.",
		["{npc:271181}, on the road"] = "{npc:271181}, на дороге",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} стоит здесь: {object:172960}. Используйте {item:6626} на круге призыва и победите суккуба, чтобы подчинить ее.",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Bears, creepers and lions"] = "Медведи, ползуны и львы",
		["Darthalia's next {quest:528} and Lydon's Elixir of Agony are for the next visit, at about 30."] = "Следующее задание Дарталии {quest:528} и Эликсир агонии Лидона – на следующий визит, примерно на 30-м уровне.",
		["Drull's ball and chain"] = "Ядро и цепь Друлла",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Наполните {item:7768} у колодца рядом с таверной: {object:107045}",
		["From {area:272} fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "Из места {area:272} летите сюда: {area:228}. {npc:2121} стоит у входа в склеп.",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often.\nCareful: A fleeing peasant that reaches the town hall can bring back many adds, including {area:287} footmen; snares, roots or similar effects keep them from escaping. Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "Крестьяне работают на полях к югу от фермерских домов. Черепа падают со всех людей из места {area:287}, но с крестьян – чаще всего.\nОсторожно: сбежавший крестьянин, добравшийся до ратуши, может привести много подкреплений, включая пехотинцев (место {area:287}); замедления, обездвиживание и подобные эффекты не дадут ему сбежать. Кирин-торские стражники (55) стоят к северу от ферм, на дороге к Альтераку: держитесь полей.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms. Careful: Kirin Tor Guards (55) stand north of the farms, on the road up toward Alterac: keep to the fields."] = "Фермы к востоку от городка {area:287}. {npc:232} работает на поле у северного фермерского дома, {npc:2403} – на поле юго-восточнее; батраки и фермеры повсюду. {npc:2451} ухаживает за полем к югу от ферм. Осторожно: стражи Кирин-Тора (55) стоят к северу от ферм, на дороге к Альтераку: держитесь полей.",
		["Train and restock in the {zone:1458} before the zeppelin."] = "Перед дирижаблем обучитесь и пополните запасы: {zone:1458}.",
		["Train before you fly on: the next guide flies from here."] = "Обучитесь перед вылетом: следующий гайд начинается с перелета отсюда.",
		["Train with {npc:3033}. {npc:3419}, in the {area:2197} under {area:1640}, takes Lydon's toxin if you carry it. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Обучитесь у NPC {npc:3033}. {npc:3419} ({area:2197}, под местом {area:1640}) принимает токсин Лидона, если он у вас есть. Перед вылетом возьмите два задания у NPC {npc:3024} и {npc:4721}, недалеко к востоку от распорядителя ветрокрылов: их выполняют по пути в следующих гайдах. Затем летите на Перекресток, где начинается следующий гайд.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "К западу от Мельницы Таррен по холмам на пути к фермам бродят серые медведи, лесные моховые ползуны и голодные горные львы. {item:3477} падает с ползунов редко; нужен только один.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{area:272} is your base for this guide: you come back here between each loop. Everyone stands around the town square."] = "{area:272} – ваша база в этом гайде: вы возвращаетесь сюда после каждого круга. Все стоят вокруг городской площади.",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: используйте половинку здесь: {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: хилсбрадские крестьяне на полях",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} ({area:2361}) отправляет туда друидов по воздуху",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}, рядом с Лидоном; внутри",
		["{npc:2238}'s ball and chain"] = "Ядро и цепь: {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} — собака NPC {npc:232}, у северного фермерского дома ({area:286}).",
		["{npc:2391}: Poisons"] = "{npc:2391}: Яды",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, мирквид у места {area:464} рядом с Солнечным Утесом",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} стоит здесь: {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, флакон с хохочущих сестер ({zone:1440})",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back east past {area:2237} to {area:484}."] = "Назад на восток мимо места {area:2237} к месту {area:484}.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Назад на юг к лагерю, затем наверх: {zone:1456} – для полета в {area:378}.",
		["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Назад к NPC {npc:12867} в лагерь лесорубов, на дороге на север к Заставе Расщепленного Дерева.",
		["Back west to Zoram'gar from Thistlefur before heading east for good."] = "Вернитесь от Чертополоха на запад в форт Зорам'гар, прежде чем окончательно уйти на восток.",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Злобные элементали воды плавают у берегов озера; беседка стоит на острове, напротив заставы Альянса.",
		["Below ground"] = "Под землей",
		["Class trainer"] = "Учитель классовых навыков",
		["Felmusk satyrs"] = "Сатиры из племени Мускуса Скверны",
		["Fly to {area:1638}"] = "Летите сюда: {area:1638}",
		["Fly to {area:378}"] = "Летите сюда: {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Идите по главной дороге на восток мимо места {area:415} (Альянс: держитесь дороги). {npc:12678}, большой медведь-гризли, бродит здесь: {area:418} – к югу от дороги, к западу от места {area:421}. Его лапа начинает следующее охотничье задание.",
		["From the {area:2360} head north-east to the Warsong lumber camp on the road: {npc:12867} stands there."] = "От места {area:2360} идите на северо-восток к Лесозаготовкам Песни Войны у дороги: там стоит {npc:12867}.",
		["Galak centaurs"] = "Кентавры из племени Галак",
		["Gazebo"] = "Беседка",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Продолжайте идти по дороге на восток. {npc:12858} ждет к юго-западу от Лесозаготовок Песни Войны. Он со своими бойцами штурмует {area:2360}: дайте им принять удар на себя и держитесь рядом с NPC {npc:12858}, пока {npc:12860} не погибнет.",
		["Keep {npc:4877}'s two harpy quests and {npc:2986}'s {quest:1150}: {area:487} comes with the next Freewind visit, at about 30, with the {area:2240}'s quests."] = "Оставьте два задания NPC {npc:4877} про гарпий и задание {quest:1150} от NPC {npc:2986}: {area:487} будет в следующий визит на заставу Вольного Ветра, примерно на 30-м уровне, вместе с заданиями места {area:2240}.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Убейте NPC {npc:10720}, который придет за {npc:10638}",
		["Laughing Sisters"] = "Смеющиеся сестры",
		["Level 28"] = "28-й уровень",
		["Level 29"] = "Уровень 29",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} (30, elite) sits at the north end: leave her unless you do {quest:96261} with a group; her {item:273658} starts {quest:96294}."] = "К северу от лагеря пауки заполонили кладбище – {area:17044}. Используйте {item:273015} ({npc:264074}) на обглоданных трупах; с прядильщиц падает {item:273181}. {npc:264082} (30, элитная) сидит в северном конце: не трогайте ее, если только не выполняете задание {quest:96261} с группой; ее {item:273658} начинает задание {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns. Careful: Felmusk Rogues and Shadowstalkers move in stealth and join fights without warning."] = "К северо-западу от заставы Расщепленного Дерева в лесу стоит лагерь сатиров из племени Мускуса Скверны. Рога могут упасть с любого сатира. Осторожно: разбойники и ловцы теней из племени Мускуса Скверны передвигаются незаметно и вступают в бой без предупреждения.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest. Careful: {npc:12676} is a level 31 nightsaber and hits hard: pull her alone, away from the Outrunners."] = "По пути назад на северо-восток к Заставе Расщепленного Дерева: {npc:12676} рыщет в лесах к юго-востоку от лесозаготовки Песни Войны. Ее коготь начинает следующее охотничье задание. Осторожно: {npc:12676} – ночная саблезубая кошка 31-го уровня и бьет сильно: выманивайте ее одну, подальше от скороходов.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Только если {npc:10617} выронил для вас свой план: {npc:10638} стоит здесь: {area:2237}.",
		["Pesterhide Snarlers"] = "Паршивые рыкуны",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Спуститесь на подъемнике, затем идите по дороге на восток через каньоны: {area:484}, деревня тауренов на вершинах столовых гор. Ее подъемник – на северной стороне.",
		["Sapphires of Aku'Mai"] = "Сапфиры Аку'май",
		["Short of 28? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon instead."] = "Не хватает до 28-го? Зловещие Тотемы вокруг этих лагерей (25-28) как раз по уровню: убейте еще несколько перед подъемом к NPC {npc:10646}. После этого уровня шаг пропускается сам. Или пройдите с группой подземелье {area:2797}.",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "К югу от Приюта Чащобы лунный колодец лежит в низине к западу от реки, его трудно заметить с дороги; {area:421} – к западу от него. Используйте {item:5867} у лунного колодца, чтобы наполнить его.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Спуститесь на подъемнике. Яйцо лежит в гнезде на дне каньона в одном из трех мест: к юго-востоку от столовых гор (52.3,55.2), к востоку (56.4,50.4) или к юго-западу (37.6,56.1).",
		["The Earthen Ring"] = "Служители Земли",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Фурболги из племени Гиблой Чащи занимают лес к востоку от места {area:421}, к югу от дороги. Установите {item:16972} на {object:178206} и охраняйте: фурболги придут его сломать. {npc:12918} придет последним; его тотем падает в корзину.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "Смеющиеся сестры, дриады, бродят здесь: {area:426} – по лесу, где обитает {npc:12677}; одна из них роняет {item:5867} для NPC {npc:4721}, на это может уйти несколько убийств.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Сапфиры – синие кристаллы на стенах туннелей, ведущих к порталу ({area:2797}), под землей и вне подземелья: нырните из ямы под стену в пещеру. Сатиры и наги в туннелях – элита: лучше собрать группу. Кристаллы быстро появляются снова, так что глубоко идти не нужно.",
		["The Wanted poster beside {npc:10537}"] = "Плакат «Разыскивается» рядом с {npc:10537} утесов",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "Фонтан стоит посреди места {area:418}, где бродит {npc:12678}: используйте там {item:7767}.",
		["The next guide opens with Korran's The Swarm Grows at the Crossroads, offered from level 29. Short of 29? The Pesterhide Snarlers (28-29) prowl the canyon floor just north-west of {area:484}: kill them until level 29. Or, with a group, run the {area:2797} dungeon instead."] = "Следующий гайд начинается с задания Коррана «Рой растет» на Перекрестке, доступного с 29-го уровня. Не хватает до 29-го? Паршивые рыкуны (28-29) рыщут по дну каньона чуть к северо-западу от места {area:484}: убивайте их до 29-го уровня. Или, с группой, пройдите подземелье {area:2797}.",
		["The night elf {quest:6503} (23-24) stalk the woods south and south-east of the lumber camp; they stealth, so watch for them."] = "Ночные эльфы из задания {quest:6503} (23-24) рыщут в лесах к югу и юго-востоку от лагеря лесорубов; они скрываются, так что смотрите в оба.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Путь к сапфирам – через затонувшие руины в северном конце берега: спуститесь по лестнице в яму.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone."] = "Это элитные противники: лучше собрать группу, поищите напарников. {npc:10992} – элита 30-го уровня: большинство классов справляются с ней в одиночку на 32-м уровне, но вам может понадобиться помощь. Если вы один, пропустите ее.",
		["Thistlefur Hold"] = "Логово Колючего Меха",
		["Underwater"] = "Под водой",
		["Warsong lumber camp"] = "Лесозаготовки Песни Войны",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "К западу от заставы Вольного Ветра, под местом {area:2097}, – лагеря Зловещего Тотема. Тайные записки лежат в сундучках для бумаг ({object:176344}) в юго-восточном, юго-западном и северо-западном лагерях.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "К западу от Мистрального озера бродит {npc:12678}, большой медведь-гризли: {area:418}. Теперь с него падает лапа.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."] = "К западу от заставы Белого Плеса виверны гнездятся на утесах ({area:482}); яйца лежат в гнездах. {npc:10427} ждет на восточной стороне гнездовий: освободите его и сохраните ему жизнь на пути обратно в {area:2237}.\nОсторожно: над головой летают виверны 28-29-го уровня, которых можно привлечь без предупреждения. Когда вы минуете первую колонну внизу, на вас может напасть группа из трех виверн. Здесь же гнездятся патриархи Скального гнездовья (30-31) и редкий Сердцерез (32): обходите их.",
		["for {npc:5901}, south of {area:392}: next guide"] = "для NPC {npc:5901}, к югу от поселения {area:392}: следующий гайд",
		["grind on {npc:4249}"] = "убивайте NPC {npc:4249}",
		["{area:2797} ruins"] = "Руины: {area:2797}",
		["{area:418} fountain"] = "Фонтан: {area:418}",
		["{area:485} detour warning: the arrow may miss the path up {area:2097}. If you are on the canyon floor, follow the path and rope bridges up {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Осторожно, обход через {area:485}: стрелка может не найти тропу наверх ({area:2097}). Если вы на дне каньона, идите по тропе и веревочным мостам наверх ({area:2097}). {npc:10646} в плену рядом с NPC {npc:10896} (29): сначала уберите стражу и {npc:10896}, затем освободите ее и защищайте на спуске; по пути нападут засадники Зловещего Тотема.",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{item:273658}, с NPC {npc:264082}: падает не у всех",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, у объекта {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, с NPC {npc:4054}",
		["{npc:10079}, at the top of the lift: {npc:10537} at {area:484}"] = "{npc:10079}, наверху подъемника: {npc:10537} – здесь: {area:484}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, у распорядителя полетов",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "Следующее задание {npc:10428}, «Священное пламя», заканчивается в {zone:1456}, вне маршрута. Пропустите его.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} от {npc:10617}, если встретите его",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, теневая пантера, рыщет в лесу вокруг места {area:426}, к западу от лагеря сатиров. Ее голова начинает следующее охотничье задание.",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: только если у вас есть страницы руководства",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "Затем {npc:12736} предложит задание ({area:2797}); не берите без группы.",
		["{npc:12736}, {npc:12757} and {npc:12721} stand in the outpost."] = "{npc:12736}, {npc:12757} и {npc:12721} стоят в форте.",
		["{npc:12757}: a banner defence in the Foulweald, east of {area:421}: furbolg waves, then {npc:12918}"] = "{npc:12757}: оборона знамени в Гиблой Чаще, к востоку от места {area:421}: волны фурболгов, затем {npc:12918}",
		["{npc:12837}, inside the inn"] = "{npc:12837}, в таверне",
		["{npc:259118} offers {quest:96261} only once {quest:96259} is handed in."] = "{npc:259118} предложит {quest:96261} только после сдачи задания {quest:96259}.",
		["{npc:259118}: {quest:96261} comes once this is handed in"] = "{npc:259118}: {quest:96261} – после сдачи этого задания",
		["{npc:264082} sits at the north end of {area:17044}; her {item:273658} starts {quest:96294}. {npc:264082} is elite: grouping up is advised."] = "{npc:264082} сидит в северном конце места {area:17044}; ее {item:273658} начинает задание {quest:96294}. {npc:264082} – элитный противник: лучше собрать группу.",
		["{npc:2986}: {npc:4490}, in the harpy den west of the post"] = "{npc:2986}: {npc:4490}, в логове гарпий к западу от лагеря",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} стоит рядом с NPC {npc:4721}, к востоку от NPC {npc:2995}.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} стоит недалеко к востоку от NPC {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} ({area:484}), позже в этом гайде",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} стоит здесь: {area:484}. Наполненный фиал от NPC {npc:4721} – для него.",
		["{npc:4877}'s two harpy quests are taken when you leave Freewind; their den comes with the next Freewind visit, at about 30."] = "Два задания NPC {npc:4877} про гарпий берутся при уходе с Заставы Свободного Ветра; их логово – на следующий визит туда, примерно на 30-м уровне.",
		["{npc:4877}, inside the inn"] = "{npc:4877}, в таверне",
		["{object:176344}, south-east camp"] = "{object:176344}, юго-восточный лагерь",
		["{object:176344}, south-west camp"] = "{object:176344}, юго-западный лагерь",
		["{quest:1150} ({npc:4490}, 31) waits for the next Freewind visit, at about 30: keep it."] = "{quest:1150} ({npc:4490}, 31) ждет следующего визита на заставу Вольного Ветра, примерно на 30-м уровне: сохраните задание.",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back east to {area:272}."] = "Возвращайтесь на восток сюда: {area:272}.",
		["Crossroads flight master"] = "Распорядитель полетов на Перекрестке",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["For your City of Dalaran run, later in this guide: {npc:2278} stands in {area:272}, a short walk east of {npc:2410}."] = "Для похода в Город Даларан, позже в этом гайде: {npc:2278} стоит здесь: {area:272}, чуть восточнее NPC {npc:2410}.",
		["From the blossoms, back north along the river and then west to {area:287} town, well north of {area:271} (its guards are 55)."] = "От цветов назад на север вдоль реки, затем на запад к поселению {area:287}, держась далеко к северу от места {area:271} (там стража 55-го уровня).",
		["Head south-west past {area:287} town to the {area:288}. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "На юго-запад мимо поселения {area:287} – к месту {area:288}. В туннелях работают шахтеры; {npc:2305} (30) и {npc:2450} (29) – в глубине.",
		["Inside"] = "Внутри",
		["Inside {area:288}"] = "Внутри: {area:288}",
		["Keep Infiltration in your log: its Syndicate (32-35) are over you now, and the 38-39 guide (Alterac and Arathi) works it on its first {area:272} loop."] = "Оставьте «Infiltration» в журнале: Синдикат (32-35) пока вам не по силам, а гайд 38-39 (Альтерак и Арати) выполняет его при первом визите сюда ({area:272}).",
		["Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first {area:272} loop and in {area:321}."] = "Оставьте их в журнале: их лагеря сейчас на 2-4 уровня выше вас, а гайд 38-39 проходит их в первом круге через {area:272} и в месте {area:321}.",
		["North of Southshore"] = "К северу от Южнобережья",
		["On to {area:287} town, south-west of the yeti caves. The town hall is on the town's west side: {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "Дальше – в городок {area:287}, к юго-западу от пещер йети. Ратуша – в западной части городка: {npc:2335} (30) и {npc:2448} внутри, там же городской реестр; рядом висит прокламация. По городку ходят члены совета.",
		["South from {area:272} along the river: Snapjaws (29) sun themselves on its banks all the way down to the hills above {area:271}. Some of them carry {item:3712}."] = "На юг от места {area:272} вдоль реки: черепахи-хваталки (29) греются на берегах до самых холмов над местом {area:271}. У некоторых есть {item:3712}.",
		["South of the river's bend, the Mudsnout gnolls (26-28) camp in the hills above {area:290}; the blossoms grow among their tents. The Shamans heal and call their friends: pull them first."] = "К югу от излучины реки гноллы Грязнорылов (26-28) стоят лагерем на холмах над местом {area:290}; цветы растут среди их палаток. Шаманы лечат и зовут подмогу: выманивайте их первыми.",
		["Thaivand's next errand, the flames, sends you among the Mountain and Giant Yetis (32-34) and to Helcular's grave inside {area:271}: leave it."] = "Следующее поручение Тайлванда, с пламенем, отправляет вас к горным и гигантским йети (32-34) и к могиле Гелькулара прямо в поселении {area:271}: пропустите его.",
		["The river south of {area:272}: kill these as you meet them"] = "Река к югу от места {area:272}: убивайте их по пути",
		["The smithy"] = "Кузница",
		["The {quest:567} poster hangs by the inn; {npc:2216} stands inside it. {npc:2393}, the cook by the inn, wants turtle meat and sells the spices for it."] = "Плакат «{quest:567}» висит у таверны; {npc:2216} стоит внутри. {npc:2393}, повар у таверны, хочет черепашье мясо и продает специи для него.",
		["Torn Fin murlocs"] = "Мурлоки из племени Рваного Плавника",
		["Town hall"] = "Ратуша",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Обучитесь, пока вы здесь ({zone:1458}): учителя – здесь: {object:36070}, {object:36073} и {object:36082} (паладины: {npc:260093}).",
		["Voidglare, Bel'varil and {npc:2770}"] = "Сиянье Бездны, Бел'варил и {npc:2770}",
		["West of Tarren Mill, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills; about one in sixteen carries the rod. Stay in these caverns: the Mountain and Giant Yetis (32-34) of the cave further north carry it too, but they hit hard and come in pairs."] = "К западу от Мельницы Таррен пещерные и лютые йети (30-32) заполняют {area:277} в холмах; примерно у одного из шестнадцати есть жезл. Оставайтесь в этих пещерах: горные и гигантские йети (32-34) из пещеры дальше к северу тоже носят его, но они бьют сильно и ходят парами.",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["for {npc:2055}, on the {zone:1458} stop at the end of this guide"] = "для NPC {npc:2055}, при визите в город {zone:1458} в конце этого гайда",
		["grind on {npc:2375}"] = "бейте: {npc:2375}",
		["{item:3712}, from the Snapjaws"] = "{item:3712}, с черепах-хваталок",
		["{item:3713}, from {npc:2393}"] = "{item:3713}, у NPC {npc:2393}",
		["{npc:2055} stands in the Apothecarium, in the {object:36126}."] = "{npc:2055} стоит в Районе Фармацевтов, в месте {object:36126}.",
		["{npc:2215}: her next {quest:539}, and {npc:2419}'s sword, are elite group quests at {area:290}: take them only with a group"] = "{npc:2215}: ее следующее задание {quest:539} и меч NPC {npc:2419} – элитные групповые задания у места {area:290}: берите их только с группой",
		["{npc:2229}, inside: Infiltration, worked on the 38-39 visit (its Syndicate are 32-35)"] = "{npc:2229}, внутри: «Infiltration», выполняется при визите на 38-39 (Синдикат там 32-35)",
		["{npc:2410} and {npc:2437} are inside the inn, {npc:2770} just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first {area:272} stop takes them."] = "{npc:2410} и {npc:2437} – в таверне, {npc:2770} – прямо у входа. Их задания доступны с 30-го уровня; если вы ниже, их возьмет гайд 38-39 при первом визите сюда ({area:272}).",
		["{npc:2410}'s quests on the next {area:272} stop and Alliance Relations in {zone:1454}, the next guide's first stop, are offered from level 30. Short of 30? The Torn Fin Muckdwellers and Coastrunners (28-30) crowd the coast south of the {area:288}, a short walk: kill them until level 30. Their Oracles (30-31) cast from the shore further east. Or, with a group, run the Excavation Site dungeon (in the {zone:1437}) instead."] = "Задания NPC {npc:2410} при следующем визите сюда ({area:272}) и «Alliance Relations» в городе {zone:1454}, первая остановка следующего гайда, доступны с 30-го уровня. Не хватает до 30? Грязекопы и береговики из племени Рваного Плавника (28-30) толпятся на побережье к югу от места {area:288}, недалеко: убивайте их до 30-го уровня. Их оракулы (30-31) колдуют на берегу дальше к востоку. Или с группой пройдите подземелье Раскопки ({zone:1437}).",
		["{npc:2410}, inside: {quest:544}, for the 38-39 visit (the {area:279} crater's traitors are 33-35)"] = "{npc:2410}, внутри: {quest:544}, для визита на 38-39 (предатели в кратере {area:279} – 33-35)",
		["{npc:2410}: {quest:93680}, with {quest:544} on the 38-39 visit"] = "{npc:2410}: {quest:93680}, вместе с заданием {quest:544} при визите на 38-39",
		["{npc:2429}, in the town: {item:3708}, from the yetis on the way to the town hall"] = "{npc:2429}, в городке: {item:3708} – с йети по пути к ратуше",
		["{npc:2437}, inside: {quest:556}, with the crater on the 38-39 visit"] = "{npc:2437}, внутри: {quest:556}, вместе с кратером при визите на 38-39",
		["{npc:270038} stands in the Apothecarium. His {quest:97985} is for Stormheart, a level 30 elite who walks the canyon east of {area:484}, on the next guide's way to the {area:439}."] = "{npc:270038} стоит в Районе Фармацевтов. Его задание {quest:97985} – на Stormheart, элитного противника 30-го уровня, который ходит по каньону к востоку от места {area:484}, по пути в следующем гайде: {area:439}.",
		["{npc:270038}: back to him on the next {zone:1458} stop, at about 38"] = "{npc:270038}: вернитесь к нему при следующем визите в город {zone:1458}, примерно на 38-м уровне",
		["{npc:2770}, outside the inn: the Boulderfist ogres (32-34) on the 38-39 Arathi visit"] = "{npc:2770}, у таверны: огры Тяжелого Кулака (32-34) при визите в Арати на 38-39",
		["{npc:3428} stands beside the Crossroads flight master. {quest:1145} is offered from level 29; below it, the next guide's {zone:1454} stop takes it."] = "{npc:3428} стоит рядом с распорядителем полетов на Перекрестке. {quest:1145} доступно с 29-го уровня; если уровень ниже, его можно взять на остановке в зоне {zone:1454} в следующем гайде.",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Крепость Громмаш, если у вас есть это задание",
		["{object:1761}, inside"] = "{object:1761}, внутри",
		["{quest:96986} from your City of Dalaran run: {npc:2278}, a short walk east of {npc:2410}."] = "{quest:96986} из Города Даларан: {npc:2278}, чуть восточнее NPC {npc:2410}.",
		["{zone:1458} trainers"] = "Учителя: {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back across to {npc:2986}'s mesa north-east of the post, then take the lift down to the canyon floor. {npc:2986}'s next test, {npc:4499}, is an elite: leave it."] = "Обратно на плато к NPC {npc:2986}, к северо-востоку от поста, затем спуститесь на подъемнике на дно каньона. Следующее испытание NPC {npc:2986}, {npc:4499}, – элита: оставьте его.",
		["Back east to {area:484}."] = "Обратно на восток: {area:484}.",
		["Clam beds"] = "Отмели с моллюсками",
		["Crossroads flight master"] = "Распорядитель полетов на Перекрестке",
		["East to the raceway, on the way south to {area:976}."] = "На восток к трассе, по пути на юг сюда: {area:976}.",
		["Fly to {area:460}"] = "Летите сюда: {area:460}",
		["Fly to {area:484}"] = "Летите сюда: {area:484}",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Идите на север вдоль побережья, затем вглубь суши к разрушенной башне ({area:2405}): внутри ждет {npc:11863}. Моллюски и наги на побережье – после этого места: {area:599}; их вы пройдете за один переход на север сюда: {area:2406}.",
		["Keep north to {area:598} for {item:15881}: any Slitherblade can drop it.\nCareful: the Myrmidons (34-35) hold the beach's northern half with the Sea Witches and Oracles (34-36, casters), up to two over you at 33: work the Naga and Sorceresses (32-33) of the southern half until the key drops, and leave the north for the second {zone:1443} visit, at 38."] = "Идите дальше на север ({area:598}) за предметом {item:15881}: он может выпасть с любой наги Скользящего Клинка.\nОсторожно: мирмидоны (34-35) держат северную половину пляжа вместе с морскими ведьмами и оракулами (34-36, заклинатели) – до двух уровней выше вас на 33-м. Бейте наг и колдуний (32-33) южной половины, пока не выпадет ключ, а север оставьте на второй визит в зону {zone:1443}, на 38-м уровне.",
		["Level 32"] = "Уровень 32",
		["North-east of the raceway onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it, and the Sparkleshell Tortoises (30-31) wander among them on the western flats; the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low. The Sparkleshell Snappers (34-35) crowd round a half-buried ship in the north-east and are over you here: the Tortoises of the western flats drop the shells just as often, so stay with them. Take the venom from the Reavers (31-32) of the north half and leave the Scorpid Terrors (33-34) further south."] = "К северо-востоку от гоночной трассы, на равнину. Просоленные василиски (30-31) греются к северо-западу от нее, а блестопанцирные черепахи (30-31) бродят среди них на западе равнины; солончаковые падальщики и стервятники кружат на востоке. С каждого стервятника падает кость, примерно с каждой третьей черепахи – панцирь.\nОсторожно: падальщики и стервятники применяют «Казнь», когда у вас мало здоровья. Блестопанцирные крепкохваты (34-35) толпятся у полузарытого корабля на северо-востоке и здесь выше вас по уровню: черепахи на западе роняют панцири так же часто, оставайтесь с ними. Яд берите с разорителей (31-32) в северной половине, а скорпидов-убийц (33-34) южнее не трогайте.",
		["Scorpid Reavers"] = "Скорпиды-разорители",
		["South from the raceway over the {zone:1446} border to {area:976}, the walled goblin town: learn its flight path and fly back to {area:484} from there, which is quicker than the walk west across the flats, and the next guides fly straight to {area:976}."] = "На юг от трассы через границу зоны {zone:1446}: {area:976}, гоблинский город за стенами. Откройте там маршрут полета и летите обратно сюда: {area:484}. Это быстрее, чем идти на запад через равнину, а следующие гайды летят прямо в {area:976}.",
		["South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats.\nCareful: the level 35 Gazers can still be two over you: pull them one at a time from the camp's edge, never two together."] = "К югу от трассы, в дальнем конце равнины, бродят просоленные хрусталиски (32-33) и созерцатели (34-35).\nОсторожно: созерцатели 35-го уровня могут быть на два уровня выше вас: выманивайте их по одному с края лагеря, никогда по двое.",
		["Swim out to {area:2406} off the far northern tip: {object:177786} stands on the shore beside the {object:177673}. Open it with both keys; leave the statue alone."] = "Плывите к острову ({area:2406}) у северной оконечности: {object:177786} стоит на берегу рядом с объектом {object:177673}. Откройте его обоими ключами; статую не трогайте.",
		["Taiga's {item:14547}, Drulzegar's Other Fish to Fry and {zone:1443}'s other 37-40 quests wait for the second visit, at 38: the next guides fly to {zone:1454} and take the zeppelin to {zone:1434}."] = "{item:14547} для Тайги, «Other Fish to Fry» Друлзегара и прочие задания 37-40 в зоне {zone:1443} ждут второго визита, на 38-м уровне: следующие гайды летят в {zone:1454} и садятся на дирижабль: {zone:1434}.",
		["The flats' south and the silithid dig are 32-35, {zone:1443}'s quests 32-38. Still below 32 after the raceway's hand-ins? Back north on the flats, the Scorpid Reavers (31-32) roam among the basilisks and tortoises: kill them until level 32; leave the Sparkleshell Snappers (34-35) and the Scorpid Terrors (33-34) alone. Or, with a group, run the {area:1717} dungeon instead."] = "Юг равнины и раскопки силитидов – 32-35, задания в зоне {zone:1443} – 32-38. Все еще ниже 32-го после сдачи заданий на трассе? Вернитесь на север равнины: скорпиды-разорители (31-32) бродят среди василисков и черепах – убивайте их до 32-го уровня; блестопанцирных крепкохватов (34-35) и скорпидов-убийц (33-34) не трогайте. Или с группой пройдите подземелье {area:1717}.",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "Дирижабль причаливает к башне у главных ворот города {zone:1454}. {npc:5639} бродит по Аллее Чести: если его нет у стрелки, поищите на улицах к юго-западу. {npc:5640} стоит здесь: {object:172961}, в западной части города.",
		["Underwater"] = "Под водой",
		["West of Freewind Post, below {area:2097}, the harpies of {area:487} (28-30). The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s; her {quest:98069} lie on the ground along the foot of the cliff and in the cave up on top. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her, for {npc:2986}'s claw."] = "К западу от Поста Вольного Ветра, под местом {area:2097}, – гарпии ({area:487}, 28-30). Визгливые гарпии, гарпии Злоперья и призывательницы ветра там нужны для задания NPC {npc:4877}; ее {quest:98069} лежат на земле у подножия утеса и в пещере наверху. {npc:4490} (31) ходит среди них: проредите гарпий вокруг нее, прежде чем нападать, – коготь нужен NPC {npc:2986}.",
		["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health, and the {npc:4132} (37, rare) walks the dig: take the Searchers and Drones (32-34) outside first, then pull the Invaders (34-35) one at a time from the cave mouth."] = "К западу от них силитиды кишат на раскопках. Искатели и трутни улья бродят среди холмов, а захватчики (34-35) остаются в пещере улья. Первый убитый силитид дает {item:5877}: откройте его.\nОсторожно: трутни улья зовут на помощь при 20% здоровья, а по раскопкам ходит {npc:4132} (37, редкий). Сначала перебейте искателей и трутней (32-34) снаружи, затем выманивайте захватчиков (34-35) по одному от входа в пещеру.",
		["You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.\n{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges.\nFor the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "Вы пропустили это при прошлом посещении этих мест по маршруту: теперь это идёт первым. Это быстро и открывает следующие задания.\n{npc:2986} ждет на плато к северо-востоку от места {area:484}, за веревочными мостами.\nДля задания {quest:1149} сойдите с края досок рядом с ним: вы приземлитесь невредимым.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["grind on {npc:4140}"] = "убивайте цель {npc:4140}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881} – с наг Скользящего Клинка",
		["{item:5795}, from the Sparkleshell Tortoises of the western flats"] = "{item:5795}, с блестопанцирных черепах на западе равнины",
		["{item:5843}, from {npc:4490}"] = "{item:5843}, с NPC {npc:4490}",
		["{npc:11863}'s next errand, the {item:15803}, needs {npc:12369} (38) out on {area:2406}: leave it, he is over your level."] = "Следующее поручение NPC {npc:11863} – {item:15803} – требует убить NPC {npc:12369} (38) здесь: {area:2406}. Пропустите его: он выше вашего уровня.",
		["{npc:2986} waits on the mesa just north-east of {area:484}, across the rope bridges."] = "{npc:2986} ждет на плато к северо-востоку от места {area:484}, за веревочными мостами.",
		["{npc:4877}, inside the inn"] = "{npc:4877}, в таверне",
		["{npc:4877}, the trade supplies vendor, stands inside {area:484}'s inn."] = "{npc:4877}, торговец товарами для ремесел, стоит в таверне ({area:484}).",
		["{npc:5641} and {npc:4498}"] = "{npc:5641} и {npc:4498}",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} стоит здесь: {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} и ваш {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} также выдает задание о помощи стихий ({area:1717}) – цепочку 33-40 к оружию бури: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: ваш {item:5178}",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} лежит на земле к юго-западу от башни, где ждет {npc:11863}, по пути вниз к берегу: прочитайте его. Оба ключа выпадают, только пока у вас есть задание.",
		["{object:19868}, all over the northern flats: pick it on the western flats, away from the Snappers"] = "{object:19868} – по всей северной равнине: собирайте на западе, подальше от крепкохватов",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Обратно на север к лагерю.",
		["Back to {object:3202}."] = "Вернитесь: {object:3202}.",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Детали Шестерень надо вернуть Кравелу в место {area:439}, это не по маршруту: оставьте их.",
		["Dustwallow's quests are 35-38. Still below 36 after {object:3202}'s hand-ins? The Snapjaw Crocolisks (35-36) line the river just east of the camp, below the Mosh'Ogg hills: kill them until level 36, then walk back to the zeppelin tower. Leave the Mosh'Ogg ogres (36-37) above them alone."] = "Задания Пылевых топей 35-38 уровня. Все еще ниже 36 после сдачи заданий в месте {object:3202}? Кроколиски-хрустогрызы (35-36) лежат вдоль реки сразу к востоку от лагеря, ниже холмов Мош'Огг: убивайте их до 36 уровня, затем возвращайтесь к башне дирижаблей. Огров Мош'Огг (36-37) над ними не трогайте.",
		["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "К востоку от холмов Мош'Огг тенебрюхие пантеры (37-38) крадутся по джунглям в сторону озера; там же бродят тигрицы Тернистой долины, с которых иногда падает безупречный клык. Кроколиски-хрустогрызы лежат вдоль реки сразу к западу от джунглей; сохраняйте их шкуры для NPC {npc:2495}. Осторожно: тенебрюхие пантеры (37-38 уровня) и старые тенебрюхие пантеры (42-43 уровня) вне боя используют Незаметность, поэтому не видны, пока вы не подойдете близко; 38-е могут быть на два уровня выше вас: выманивайте их по одному, а старых не трогайте.",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {object:3202}"] = "Летите: {object:3202}",
		["Nesingwary's camp"] = "Лагерь Эрнестуэя",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "К северо-западу от Лагеря Гром'гол под водой у побережья лежит {area:104}. {item:4094} лежит на морском дне у затонувших руин; следите за дыханием и мурлоками.",
		["On the walk west from Nesingwary's camp, a pile of {object:661516} lies by the path: it starts {quest:97328}, whose Stolen Shipments lie in the {area:102} on the coast ahead."] = "По пути на запад от лагеря Несингвэри у тропы лежат тщательно обысканные припасы ({object:661516}): они начинают задание {quest:97328}, а украденные грузы лежат впереди на побережье: {area:102}.",
		["Snapjaw Crocolisks"] = "Кроколиски-хрустогрызы",
		["Stolen Shipments, in the ruins"] = "Украденные грузы – в руинах",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads. Careful: the 37s can be two over you: pull them one at a time from the village's edge, never into the middle with the Witch Doctors.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of The {item:2755}."] = "Сушеные головы носят охотники за головами из племени Кровавого Скальпа (36-37) в деревне на побережье. Осторожно: 37-е могут быть на два уровня выше вас: выманивайте их по одному с края деревни, никогда не лезьте в центр к знахарям.\nТролли Кровавого Скальпа занимают руины на побережье к северу от рифа и деревню за ними; с любого может выпасть {item:3915}. Продолжайте собирать страницы из книги «{item:2755}».",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time. Careful: the 37s can be two over you: take them from the camp's western edge, never two together."] = "Огры из клана Мош'Огг стоят лагерем на холмах чуть восточнее места {object:3202}, по пути назад. Убейте 10 громил и 5 знахарей (36-37); выманивайте по одному. Осторожно: 37-е могут быть на два уровня выше вас: атакуйте с западного края лагеря, никогда не берите двоих сразу.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Тенебрюхие пантеры будут гораздо позже, у объекта {object:3202}",
		["The next guide takes the zeppelin to {zone:1454} from the tower on the west side of the camp."] = "Следующий гайд садится на дирижабль в город {zone:1454} у башни на западной стороне лагеря.",
		["Underwater"] = "Под водой",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\nLeave {npc:729}, the level 37 tiger on the hilltop south-west of the camp, for now: he is two over you here, and the 40-50 Stranglethorn guide comes back to him.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "К западу за лагерем на скалах сидят хрустальные василиски (34-35); любой тролль Кровавого Скальпа в деревне дальше может уронить ухо.\n{npc:729}, тигра 37-го уровня на вершине холма к юго-западу от лагеря, пока не трогайте: он на два уровня выше вас, а гайд по Тернистой долине 40-50 вернется к нему.\nОсторожно: в гнезде ящеров есть детеныши, которые вступают в бой, когда вы нападаете на взрослых.",
		["{area:2408} flight master"] = "Распорядитель полетов: {area:2408}",
		["{item:277957}, from the Bloodscalp Scouts, Hunters and Mystics"] = "{item:277957} – с разведчиков, охотников и мистиков из племени Кровавого Скальпа",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: для Нагорья Арати, позже по маршруту",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} ждет на втором этаже дома у распорядителя полетов; {quest:1111} стоит на причале, рядом с кораблем.",
		["{npc:3391}, upstairs"] = "{npc:3391}, на втором этаже",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: для NPC {npc:4631} в месте {area:35}, куда идет корабль",
		["{npc:4631}, on the pier: the Stolen Shipments"] = "{npc:4631}, на пирсе: украденные грузы",
		["{npc:717}: {npc:729} (37) waits for your next Nesingwary stop, at about 40 in forever/horde/40-50/01-stranglethorn-vale"] = "{npc:717}: {npc:729} (37) ждет следующего визита к Несингвэри, примерно на 40-м уровне в forever/horde/40-50/01-stranglethorn-vale",
		["{quest:1111}, on the docks"] = "{quest:1111}, на причале",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back north along the coast to {area:392}'s flight master."] = "Обратно на север вдоль побережья к распорядителю полетов: {area:392}.",
		["Crossroads flight master"] = "Распорядитель полетов на Перекрестке",
		["Drywallow Crocolisks"] = "Кроколиски-грязекупы",
		["East along the road to {area:597}; {npc:5412} stands beside {npc:5395}."] = "Идите на восток по дороге сюда: {area:597}; {npc:5412} стоит рядом с NPC {npc:5395}.",
		["Fly to {area:378}"] = "Летите сюда: {area:378}",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} and {npc:4926} in the village."] = "Возвращайтесь с головой на запад в Гиблотопь: {npc:4503} стоит на южном краю деревни, у въезда, {npc:4791} и {npc:4926} – в деревне.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Идите на восток от места {area:378} по дороге в болото. Сгоревшее здание ({area:403}) стоит у дороги сразу за границей; щит, бляха и следы копыт – в руинах и рядом с ними.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Идите на север сюда: {area:502}. Вонючка стоит у подножия холма; охраняйте его, пока он собирает листья чуть к югу.",
		["Head west back across the marsh. The Darkfang Lurkers (36-37) and Venomspitters (37-38) on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes. Work its outer edge, where the Spiders and Recluses (35-37) stand: the Lurkers and Silkspinners (37-39) deeper in are two or three over you.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Возвращайтесь на запад через болото. Скрытни-темножвалы (36-37) и плюющиеся ядом (37-38) на гребнях к северу от Гиблотопи роняют ядовитые железы. Тераморские секретные агенты (35-36) крадутся по тем же лесам: они в незаметности, так что смотрите внимательно.\nПауки Мглистой пещеры кишат у входа в пещеру к северо-западу от Гиблотопи; глаза падают со всех видов. Действуйте по внешнему краю, где стоят пауки и затворники (35-37): паучата и шелкопряды (37-39) глубже на два-три уровня выше вас.\nОсторожно: скрытни-темножвалы (36-37 уровня) вне боя используют Незаметность, а в бою применяют яд.\nОсторожно: пауки в незаметности в этой же местности нападают, едва заметив вас.\nОсторожно: паучата Мглистой пещеры передвигаются незаметно и в бою применяют яд. Пауки стоят плотно, поэтому лишние враги часто присоединяются; выманивание одиночных целей с внешнего края уменьшает их число.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Ярл живет здесь: {area:497}, к юго-востоку от места {area:502}.",
		["Mirefin murlocs"] = "Мурлоки Болотного Плавника",
		["North up the road to {area:599}. Clear the middle of the largest building, then use the {item:14523} on the red {object:176581} there. A {npc:11876} (37) comes out: kill it for the {item:13542}. The Burning Blade around it are well under you now."] = "Идите на север по дороге сюда: {area:599}. Зачистите середину самого большого здания, затем используйте {item:14523} на красном объекте {object:176581}. Появится {npc:11876} (37): убейте его ради предмета {item:13542}. Пылающий Клинок вокруг теперь намного ниже вас.",
		["North-west to the goblin camp on the west side of the {area:596}, back past {area:602}: keep west of the Magram's village."] = "На северо-запад к лагерю гоблинов в западной части места {area:596}, обратно мимо места {area:602}: держитесь западнее деревни Маграм.",
		["On east to the {area:497}."] = "Дальше на восток сюда: {area:497}.",
		["On the way east, {npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out: {npc:5045} and Theramore Skirmishers (36) join it."] = "По пути на восток {npc:4983} ждет здесь: {area:2302}, к востоку от деревни. Следуйте за ним к Риту и не дайте ему погибнуть в завязавшемся бою: к нему присоединятся {npc:5045} и тераморские рыскатели (36).",
		["South down the coast to Shadowprey: {npc:11624} takes the box and sends you to {area:602} with it; {npc:12340} takes the naga."] = "Идите на юг по побережью в Деревню Ночных Охотников: {npc:11624} берет шкатулку и отправляет вас с ней сюда: {area:602}; {npc:12340} принимает наг.",
		["South-east of the coven, the bone fields of the {area:2657}, where Undead Ravagers roam, at {zone:1443}'s southern edge: keep south of the Magram's village on the way. Use the {item:15848} at the arrow to draw the Magrami Spectres (38-39): they come in numbers, so fight them with your back to the valley's edge. They drop the ghost-o-plasm.\nCareful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields just west of the arrow, well above you: use the crate at the arrow, on the valley's eastern side, and pull the spectres away from them."] = "К юго-востоку от ковена – костяные поля ({area:2657}), где бродят опустошители-отрекшиеся, на южном краю зоны {zone:1443}: по пути держитесь южнее деревни Маграм. Используйте {item:15848} у стрелки, чтобы приманить призраков Маграми (38-39): они приходят толпой, так что сражайтесь спиной к краю долины. С них падает эктоплазма.\nОсторожно: некроханы и трупоеды Маграм (45, элита) ходят по костяным полям чуть западнее стрелки, намного выше вас: используйте ящик у стрелки, на восточной стороне долины, и уводите призраков от них.",
		["Stinky Ignatz"] = "«Вонючка» Игнац",
		["Swamp Eye Jarl"] = "Ярл «Болотный Глаз»",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "На развилке сверните на север к деревне огров Гиблотопь.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Мурлоки племени Болотного Плавника толпятся на побережье к востоку и северо-востоку от места {area:502}; головы падают со всех видов.",
		["The {area:2657}"] = "{area:2657}",
		["Underwater"] = "Под водой",
		["West from the fortress to the coast at {area:598}: the Slitherblade Myrmidons, Naga and Sorceresses hold the beach. Pull them one at a time; the Sea Witches and Oracles (34-36) cast from range."] = "Идите на запад от крепости к побережью ({area:598}): мирмидоны, наги и колдуньи из клана Скользящего Плавника занимают пляж. Выманивайте по одному; морские ведьмы и оракулы (34-36) атакуют издалека.",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "только если у вас есть {item:3853} ({skill:164} или аукцион)",
		["{area:2408} flight master"] = "Распорядитель полетов: {area:2408}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}: для Ярла «Болотного Глаза»",
		["{npc:11624} and {npc:12340} stand in the village."] = "{npc:11624} и {npc:12340} стоят в деревне.",
		["{npc:11624}: the {quest:5381}, at {area:599} later on this visit"] = "{npc:11624}: «{quest:5381}», в месте {area:599} позже в этот визит",
		["{npc:12340}: the Slitherblade of Sar'theris Strand, on the way back from {area:599}"] = "{npc:12340}: Скользящие Плавники с Берега Сар'терис, на обратном пути из места {area:599}",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} стоит под домом Газлоу, у распорядителя полетов, ближе к причалам.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, на южном краю деревни, у въезда",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} ждет в лагере гоблинов в западной части места {area:596}.",
		["{npc:6019}: the ghost-o-plasm, after {area:602} at the end of this visit"] = "{npc:6019}: эктоплазма, после места {area:602} в конце этого визита",
		["{object:20985}, beside the manor"] = "{object:20985}, у усадьбы",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, теперь, когда {npc:4791} прочел донесение",
		["{zone:1443}'s last quests are 36-39. Still below 36 after Brackenwall's hand-ins? The Drywallow Crocolisks (35-36) along the river east of the village are the closest at your level: kill them until level 36."] = "Последние задания в зоне {zone:1443} 36-39 уровня. Все еще ниже 36 после сдачи заданий в Гиблотопи? Ближайшие по уровню – кроколиски-грязекупы (35-36) вдоль реки к востоку от деревни: убивайте их до 36 уровня.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "Обратно на восток вдоль предгорий сюда: {area:272}: все с первого круга сдается в таверне.",
		["Back north to {area:321}: the doctor stands at the south gate."] = "Возвращайтесь на север сюда: {area:321}. Доктор стоит у южных ворот.",
		["Back to {area:321}"] = "Назад: {area:321}",
		["Below ground"] = "Под землей",
		["Boulderfist camp"] = "Лагерь клана Тяжелого Кулака",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["Follow the road north out of {area:272} into the Alterac foothills: {quest:535} waits by the Syndicate camp. He offers his errand only while you carry {npc:2229}'s Infiltration: hand him the stout at once, and his reward is the Syndicate Missive Krusk wants. A missive from the Syndicate here does the same: with one in your bags the guide passes {quest:535}."] = "Идите по дороге на север от места {area:272} в предгорья Альтерака: {quest:535} ждет у лагеря Синдиката. Он дает поручение, только пока у вас есть задание «Проникновение» от NPC {npc:2229}: сразу отдайте ему пиво, и его награда – послание Синдиката, нужное Круску. Послание Синдиката отсюда тоже подойдет: если оно в сумках, гайд пропускает {quest:535}.",
		["From {area:280} follow the road south-west to {area:1357} and on west to the ruins north of the {area:279} crater, along the lake shore. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves. Careful: Arcane Sentries (55, elite) and Kirin Tor Guards (55) guard the dome itself and attack the Horde: work the ruins' outer edge and don't go up to the dome."] = "От места {area:280} идите по дороге на юго-запад к месту {area:1357} и дальше на запад к руинам к северу от кратера ({area:279}), вдоль берега озера. Даларанские призыватели водят с собой порабощенных элементалей; наручи падают с элементалей. Осторожно: чародейские часовые (55, элита) и кирин-торские стражники (55) охраняют сам купол и нападают на Орду: бейте по внешнему краю руин и не подходите к куполу.",
		["Head north up the road past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "Идите на север по дороге мимо лагеря, где ждет {quest:535}, сюда: {area:280} – деревня под контролем Синдиката (35-37). {npc:2431} носит {item:3704}; {quest:503} сидит в клетке в доме на северной стороне.\nОсторожно: по деревне ({area:280}) бродят незаметные шпионы Синдиката, а в зданиях много мобов Синдиката, включая магов.",
		["Hearth back to {area:272}: your hearthstone is bound there."] = "Вернитесь с помощью камня возвращения сюда: {area:272} – он привязан там.",
		["Inside"] = "Внутри",
		["Only if {quest:535}'s missive didn't come your way: the Syndicate Footpads and Thieves (32-34) around the camps west of the road carry missives too; about one in three drops one."] = "Только если послание от NPC {quest:535} не досталось: разбойники и воры Синдиката (32-34) у лагерей к западу от дороги тоже носят послания; падает примерно с каждого третьего.",
		["Syndicate missives"] = "Донесения Синдиката",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "Громилы из клана Тяжелого Кулака стоят лагерем у чертога огров далеко к юго-западу от места {area:321}; среди них – волхвы. Выманивайте по одному.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Внутренний круг – к югу от западного, к востоку от Стромгарда.",
		["The magus offers a dungeon errand next: leave it."] = "Затем маг предлагает поручение в подземелье: не берите его.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} – в дальнем конце ущелья.",
		["The {object:2702}"] = "{object:2702}",
		["Underwater"] = "Под водой",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "К западу от бухты налетчики и колдуньи из клана Пронзающего Гребня (38-40) занимают берег: выманивайте по одному. Два затонувших корабля лежат на мелководье, карты и журналы – внутри; самоцветы лежат на дне вокруг кораблей.",
		["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "К западу от внутреннего круга – руины Стромгарда: Синдикат занимает восточную половину (печать падает с их заклинателей, бродяг и магов), огры Тяжелого Кулака – западную, у места {area:325} ({npc:2773} ждет в одном из домов без крыши рядом).",
		["Worn Stone Tokens, from the Shield Guards and Theurgists on the camp's west side"] = "Истертые каменные талисманы – со стражей со щитами и теургов на западной стороне лагеря",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, для персонажа {npc:2333}",
		["{npc:2229} will offer {npc:2423} (41, in his manor far up {area:1339}) for this: leave it, he is over your level."] = "За это {npc:2229} предложит задание {npc:2423} (41, в его поместье далеко вверх по берегу: {area:1339}): не берите его, он выше вашего уровня.",
		["{npc:2792}, by the gate"] = "{npc:2792}, у ворот",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Под землей",
		["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Идите на запад по дороге к месту {area:340}; лагерь {npc:2921} – здесь: {area:1878}, на полпути.",
		["Head west back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "Возвращайтесь на запад сюда: {area:340}. {npc:5394} стоит на верхнем ярусе ({area:340}), высоко над распорядителем полетов: поднимайтесь по пандусам, стрелка не различает ярусы.",
		["Into the {zone:1418}"] = "В край {zone:1418}",
		["Keep north on the road to {area:1517}'s entrance, in the north of the {zone:1418}: the chest lies just inside the cave mouth. {npc:2932} and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."] = "Продолжайте путь на север по дороге ко входу ({area:1517}) на севере зоны {zone:1418}: сундук лежит сразу за входом в пещеру. Рядом с ним стоят {npc:2932} и обсидиановые големы (38), а в туннеле работают землекопы Тенегорна (35-36), все элитные: держитесь группой.",
		["Lesser Rock Elementals"] = "Младшие каменные элементали",
		["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards. Careful: Malevolent Mirages (42, elite) drift across the {zone:1418}: give them a wide berth.\nCareful: the Giant Buzzards are 39-41, and the 41s are two over you at 39: pick the 39s and 40s and pull them one at a time. The Buzzards (37) you kill later for {npc:2817}'s wings drop gizzards too, more rarely."] = "Старые скальные койоты и гигантские канюки бродят по котловине к югу от места {area:1878}. С койотов падают и челюсти, и клыки; с гигантских канюков – желудки. Осторожно: зловредные миражи (42, элита) бродят по зоне {zone:1418}: обходите их стороной.\nОсторожно: гигантские канюки 39-41 уровня, а 41-е на два уровня выше вас на 39-м: выбирайте 39-х и 40-х и выманивайте по одному. Канюки (37), которых вы позже бьете ради крыльев для {npc:2817}, тоже роняют желудки, но реже.",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way north from {area:345}; the Bonesnappers and Shamans drop the flakes. The Buzzards for {npc:2817}'s wings circle the hills between the {area:1877} and {area:345}."] = "Трогги племени Каменного Свода копают у входов в пещеры к югу от места {area:1877}, по пути на север от места {area:345}; хлопья падают с костегрызов и шаманов. Канюки, нужные для крыльев ({npc:2817}), кружат над холмами между местами {area:1877} и {area:345}.",
		["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "Дорога на север к месту {area:1517} проходит здесь: {area:1877}. По пути {npc:2817} и {npc:4618} принимают крылья и хлопья.",
		["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Маленькие элементали бродят по равнине между местом {area:340} и лагерем {npc:2921}, по дороге обратно на восток. С любого каменного элементаля в зоне могут падать осколки каменного элементаля для {npc:6868}.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: письмо Пшикса Медноштифа ({area:439})",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "Кристаллы дренетиста",
		["Felsteed: Zevrost in {zone:1454}, then {npc:6251} in {area:392}, on the {zone:1444} guide's {zone:1454} stop."] = "Конь Скверны: Зеврост ({zone:1454}), затем {npc:6251} ({area:392}), на остановке в краю {zone:1454} в гайде по краю {zone:1444}.",
		["Fly to the {area:1497}"] = "Летите сюда: {area:1497}",
		["Fly to {area:35}"] = "Летите: {area:35}",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "Идите по дороге на восток из края {zone:1431} через край {zone:1430} в болото. {npc:1776} ждет здесь: {area:657} – лагерь дренеев у дороги, там, где она входит со стороны края {zone:1430}.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Дальше к северу гоблины Торговой компании копают в руднике к востоку от дороги; кристаллы падают с шахтеров, десятников, геодезистов и механиков.\nОсторожно: по округе вокруг лагеря в незаметности бродят пантеры Тенегрызов и тигрицы Тернистой долины.",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Грингер, распорядитель полетов, ждет на верхней палубе ({area:35}). Персонажи с заданиями стоят на мостках вокруг гавани и в таверне.",
		["Head east to {area:75}, in the reeds south of the road."] = "Идите на восток сюда: {area:75}, в камышах к югу от дороги.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Идите на север по дороге; лагерь охотников – на холме над рекой.",
		["Head west to {object:3202}."] = "Идите на запад сюда: {object:3202}.",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "Его сундук – в его старом лагере к северу от места {area:75}, по пути обратно на запад.",
		["Inside"] = "Внутри",
		["Jungle stalkers"] = "Ящеры-ловчие",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Выйдите из города через туннель; записка лежит в пиратской бухте чуть к северу от места {area:35}.",
		["Mistvale gorillas"] = "Гориллы из Мглистой долины",
		["Nesingwary's camp"] = "Лагерь Эрнестуэя",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Нобору бродит по поляне к юго-западу от места {area:76}; его дубина начинает задание.",
		["Riding at 40"] = "Верховая езда на 40-м",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454} and go south down the {zone:1411} road to {area:367}: {npc:7953} teaches Trolls there, with Zjolnir's raptors (20 gold each). Then back to the zeppelin for {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; изучив ее, вы получите транспорт, а без него {zone:2548} после Тернистой долины – долгий путь пешком. Сядьте на дирижабль у башни ({object:3202}) до места {zone:1454} и идите на юг по дороге через {zone:1411} к месту {area:367}: {npc:7953} обучает там троллей, ящеры у Зьолнира (по 20 золотых). Затем обратно к дирижаблю до места {object:3202}. Не хватает золота? Пропустите этот шаг: гайд по зоне {zone:1444} снова проходит через {zone:1454} примерно на 45-м.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}, fly to {zone:1456} and ride down to {area:222}: {npc:3690} teaches Tauren there, with {npc:3685}'s kodos (20 gold each). Then fly back to {zone:1454} for the {object:3202} zeppelin. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1456} again at about 45."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; изучив ее, вы получите транспорт, а без него {zone:2548} после Тернистой долины – долгий путь пешком. Сядьте на дирижабль у башни ({object:3202}) до места {zone:1454}, летите сюда: {zone:1456} и спуститесь к месту {area:222}: {npc:3690} обучает там тауренов, кодо у NPC {npc:3685} (по 20 золотых). Затем летите обратно сюда: {zone:1454}, к дирижаблю до места {object:3202}. Не хватает золота? Пропустите этот шаг: гайд по зоне {zone:1444} снова проходит через {zone:1456} примерно на 45-м.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount, and the {zone:2548} after Stranglethorn are a long walk without one. Take the zeppelin from {object:3202}'s tower to {zone:1454}: {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel (wolves 20 gold each). Then the zeppelin back to {object:3202}. Short of gold? Skip this step: the {zone:1444} guide passes {zone:1454} again at about 45."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; изучив ее, вы получите транспорт, а без него {zone:2548} после Тернистой долины – долгий путь пешком. Сядьте на дирижабль у башни ({object:3202}) до места {zone:1454}: {npc:4752} обучает орков здесь: {object:172958}, у псарни ({npc:3362}; волки по 20 золотых). Затем дирижаблем обратно сюда: {object:3202}. Не хватает золота? Пропустите этот шаг: гайд по зоне {zone:1444} снова проходит через {zone:1454} примерно на 45-м.",
		["Sawtooth crocolisks"] = "Острозубые кроколиски",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Кони-скелеты: {npc:4731}, рядом с NPC {npc:4773} ({area:159}).",
		["The Bloodsail ships"] = "Корабли Кровавого Паруса",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Кроколиски лежат в лужах вокруг лагеря {npc:5391} и к югу, к месту {area:75}; бок падает примерно с каждого четвертого.",
		["The naga explorers on the coast south of here (43-44) are for Bloads and Mok'thardin: keep both quests for your Stranglethorn stop at about 45."] = "Наги-исследователи на побережье к югу отсюда (43-44) нужны для Блоадса и Мок'тардина: сохраните оба задания до остановки в Тернистой долине примерно на 45-м.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "Следующие трофейные черепа – в небольших руинах чуть к северу от лагеря воинов.\nПоследние черепа – в руинах недалеко к западу, по пути обратно сюда: {object:3202}.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast.\nCareful: the Jungle Stalkers (40-41) are thick here: pull one at a time and rest between fights."] = "Ящеры-ловчие охотятся в джунглях к югу от места {object:3202}, ближе к западному побережью.\nОсторожно: тропических ловцов (40-41) здесь много – тяните по одному и отдыхайте между боями.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone."] = "Это элитные противники: лучше собрать группу, поищите напарников. {npc:728} – элита 40-го уровня: большинство классов справляются в одиночку на 42-м, но может понадобиться помощь. Если вы один, пропустите.",
		["Venture Co. mine"] = "Рудник Торговой компании",
		["Warlocks don't buy riding: your mount is the Felsteed, from your class quest. Zevrost in {zone:1454}'s {object:172960} starts it and {npc:6251} in {area:392} teaches it, both on the {zone:1444} guide's {zone:1454} stop at about 45."] = "Чернокнижники не покупают верховую езду: ваш транспорт – конь Скверны из классового задания. Его начинает Зеврост ({zone:1454}, {object:172960}), а {npc:6251} ({area:392}) обучает ему; оба – на остановке в краю {zone:1454} в гайде по краю {zone:1444}, примерно на 45-м.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "К западу от экспедиции вожди племени Кровавого Скальпа – {npc:1061} и {npc:1062} – стоят вместе в руинах Зул'Кунды. Сначала перебейте охрану, затем выманите их.\nНа побережье между Зул'Кундой и местом {object:3202} {npc:2635} (элитный, 38-й уровень) появляется на месте обычных кроколисков: если он на месте, убейте его и снимите шкуру для {npc:2495}.",
		["Your level 40 training is in the {area:1497}: fly there from {area:340}, train, and take the zeppelin from the towers outside the city to {object:3202}."] = "Ваше обучение на 40-м уровне – здесь: {area:1497}. Летите туда из места {area:340}, обучитесь и сядьте на дирижабль у башен за городом до места {object:3202}.",
		["Your mount at 40"] = "Ваш транспорт на 40-м",
		["Zeppelin to {object:3202}"] = "Дирижабль: {object:3202}",
		["Zul'Kunda"] = "Зул'Кунда",
		["Zul'Mamwe"] = "Зул'Мамбве",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}, рядом: {npc:2497}",
		["{npc:2487}: keep it for the {area:43} at about 45"] = "{npc:2487}: сохраните для места {area:43}, примерно на 45-м",
		["{npc:2488}, on the top floor: keep it for the {area:43} at about 45"] = "{npc:2488}, на верхнем этаже: сохраните для места {area:43}, примерно на 45-м",
		["{npc:2493}: keep it for the {area:43} at about 45"] = "{npc:2493}: сохраните для места {area:43}, примерно на 45-м",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, внутри: {item:4105}",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}: {npc:2635} греется на побережье между Зул'Кундой и местом {object:3202}, позже на этом круге",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, на балконе рядом с Мак-Кинли",
		["{npc:2497}: for the {zone:1425}, around level 48"] = "{npc:2497}: для зоны {zone:1425}, примерно на 48-м уровне",
		["{npc:2519}: the trophy skulls stand in the Skullsplitter ruins, later on this loop"] = "{npc:2519}: трофейные черепа стоят в руинах Дробителей Черепов, позже на этом круге",
		["{npc:265756}, riding trainer, at the {area:17684} in {area:16638}"] = "{npc:265756}, учитель верховой езды: {area:17684}, {area:16638}",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, на пристани: письмо Газлоу, если оно у вас есть",
		["{npc:4773}, riding trainer"] = "{npc:4773}, учитель верховой езды",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} в плену здесь: {area:76}, на северо-востоке болота. Освободите его и следуйте за ним, отбиваясь от болотных тварей.",
		["{npc:716} collects the pages of {quest:338}: the trolls of the vale drop them now and then. Take his quest; each chapter he takes once you have all its pages."] = "{npc:716} собирает страницы книги «{quest:338}»: время от времени они падают с троллей долины. Возьмите его задание; каждую главу он принимает, когда у вас есть все ее страницы.",
		["{npc:716}: every page of chapter I is in your bags"] = "{npc:716}: все страницы главы I в сумках",
		["{npc:716}: every page of chapter II is in your bags"] = "{npc:716}: все страницы главы II в сумках",
		["{npc:716}: every page of chapter III is in your bags"] = "{npc:716}: все страницы главы III в сумках",
		["{npc:716}: every page of chapter IV is in your bags"] = "{npc:716}: все страницы главы IV в сумках",
		["{npc:716}: the four chapters"] = "{npc:716}: четыре главы",
		["{npc:729}, the tiger {npc:717} sent you after on your last visit, prowls the hilltop just south-west of the camp."] = "{npc:729} – тигр, за которым вас отправил {npc:717} в прошлый раз, – бродит по вершине холма чуть к юго-западу от лагеря.",
		["{npc:737}, upstairs, has his next errand now: the Skullsplitter tusks come from the trolls of Zul'Mamwe, later on this loop."] = "У NPC {npc:737} наверху теперь есть следующее поручение: клыки Дробителей Черепов – с троллей Зул'Мамве, позже на этом круге.",
		["{npc:7953}, riding trainer"] = "{npc:7953}, учитель верховой езды",
} end)()
t.guides["forever/horde/40-50/01b-riverglades"] = (function() return {
		["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Около 70 заданий в новой зоне Forever, из крепости {area:16743}.",
		["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Через {area:3} в {area:340} – крепость Орды, встроенную в скалы у западного края зоны: распорядитель полетов стоит у подножия крепости.",
		["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Обратно на север вдоль берега: по пути к ползунам сдайте мурлоков и шкуру на причалах.",
		["Back through the port"] = "Обратно через порт",
		["Back to the port, from the north pier west through the docks."] = "Возвращайтесь в порт: от северного пирса на запад через доки.",
		["Back to the port."] = "Возвращайтесь в порт.",
		["Down to the port."] = "Спускайтесь в порт.",
		["Fly to {area:340}"] = "Летите сюда: {area:340}",
		["Fly to {area:484}"] = "Летите сюда: {area:484}",
		["Into the {area:16591}"] = "Сюда: {area:16591}",
		["Learn {area:976}'s flight path: it saves the ride next time."] = "Откройте маршрут полета ({area:976}): в следующий раз не придется ехать.",
		["New in Forever: this guide follows what players did in the {area:16591}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFrom {area:340}, ride south-east across the {area:3} to the zone's southern edge: the pass of {area:16685} leads down into the {area:16591}. {area:16743}, the Horde's fort, stands in the middle of the zone, east along the valley."] = "Новое в Forever: этот гайд повторяет то, что делали игроки здесь: {area:16591}. Если шаг неверен, сообщите нам в Discord или на GitHub Polestar и назовите шаг.\nИз места {area:340} езжайте на юго-восток через {area:3} к южному краю зоны: перевал {area:16685} ведет вниз сюда: {area:16591}. {area:16743}, крепость Орды, стоит в центре зоны, к востоку по долине.",
		["New in Forever: this guide follows what players did in the {zone:2548}. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe {zone:2548} lie across the sea from {zone:1446}: a goblin boat sails from {area:977}, north-east of {area:976}, to {area:16727}. Fly to {area:484} in {zone:1441} and head south-east through the {area:439} to {area:976}. (If you already know {area:340} in the {area:3}, the way in through {area:16685} works too.)"] = "Новое в Forever: этот гайд повторяет то, что делали игроки в зоне {zone:2548}. Если шаг неверен, сообщите нам в Discord или на GitHub Polestar и назовите шаг.\n{zone:2548} лежат за морем от края {zone:1446}: гоблинский корабль ходит из места {area:977}, к северо-востоку от места {area:976}, до места {area:16727}. Летите сюда: {area:484} ({zone:1441}), и идите на юго-восток через {area:439} к месту {area:976}. (Если у вас уже открыт {area:340} ({area:3}), можно пройти и через {area:16685}.)",
		["The Eastsea pirates"] = "Пираты Восточного моря",
		["The murlocs, south-west"] = "Мурлоки на юго-западе",
		["The pirates' second wave"] = "Вторая волна пиратов",
		["The pirates' ships"] = "Корабли пиратов",
		["The plains and the marsh"] = "Равнины и болото",
		["The river and the Farholde camp"] = "Река и лагерь Фархольда",
		["The vipers and the tallstriders"] = "Гадюки и долгоноги",
		["The {zone:2548} lie south of the {area:3}. Ride east from the {area:657} to {area:75} and fly to {area:340}: the way down into the zone starts there."] = "{zone:2548} лежат к югу от зоны {area:3}. Езжайте на восток от места {area:657} к месту {area:75} и летите сюда: {area:340}. Оттуда начинается спуск в зону.",
		["West back to {area:16743}'s east side."] = "Возвращайтесь на запад, к восточной части места {area:16743}.",
		["the middle ship"] = "средний корабль",
		["the northern ship"] = "северный корабль",
		["the {object:707249} poster"] = "Плакат: {object:707249}",
		["{area:977} is on the coast north-east of {area:976}: wait on the pier for the goblin boat to {area:16727}."] = "{area:977} – на побережье к северо-востоку от места {area:976}: ждите на пристани гоблинский корабль до места {area:16727}.",
		["{item:268505}, the southern ship"] = "{item:268505}, южный корабль",
		["{item:271629}, from the Peasant Woodpiles"] = "{item:271629}: из крестьянских поленниц",
		["{item:271629}: fletch it into Makeshift Stickin' Spears"] = "{item:271629}: сделайте из нее самодельные копья",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Back into town. The ships' captains, Seahorn's next request, are for your Stranglethorn stop at about 50."] = "Возвращайтесь в город. Капитаны кораблей, следующая просьба Морского Рога, – для визита в Тернистую долину примерно на 50-м уровне.",
		["Back west to {object:3202}."] = "Возвращайтесь на запад: {object:3202}.",
		["Fly to {area:1638}"] = "Летите сюда: {area:1638}",
		["Fly to {area:484}"] = "Летите сюда: {area:484}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["Fly to {object:3202}"] = "Летите сюда: {object:3202}",
		["Grimtotem camp"] = "Лагерь Зловещего Тотема",
		["In {area:35}: {npc:2494} on the docks, {npc:2486} by the inn, {npc:2498} inside it, MacKinley, {npc:737} and {npc:773} upstairs."] = "{area:35}: {npc:2494} на причалах, {npc:2486} у таверны, {npc:2498} внутри, Маккинли, {npc:737} и {npc:773} наверху.",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Кодо: {npc:3685}, рядом с персонажем {npc:3690} ({area:222}).",
		["On south-west to the jungle north-east of Mistvale: the three ghostly pirates haunt it beside Zanzil's camps. {npc:2535} and {npc:2536} stand together, {npc:2537} further east. Every one of Zanzil's followers can carry the mixture.\nCareful: the Zanzil Witch Doctors (44) cast and the camps are packed: pull from the edge, one at a time. {npc:2534} (46) himself stands in the southern camp around 39.6,58.6, a few steps from {npc:2537}'s ghost: pull {npc:2537} out to the north or east before you fight him."] = "Далее на юго-запад, в джунгли к северо-востоку от Туманной долины: там бродят три пирата-призрака рядом с лагерями Занзила. {npc:2535} и {npc:2536} стоят вместе, {npc:2537} – дальше к востоку. Смесь может быть у любого последователя Занзила.\nОсторожно: знахари Занзила (44) колдуют, а лагеря плотные: выманивайте с краю по одному. {npc:2534} (46) стоит в южном лагере около 39.6,58.6, в паре шагов от призрака {npc:2537}: выманите {npc:2537} на север или восток, прежде чем сражаться с Занзилом.",
		["Pirate ghosts and Zanzil's camps"] = "Призраки пиратов и лагеря Занзила",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Ящеры: Зьольнир, рядом с персонажем {npc:7953} ({area:367}).",
		["Ride east to the Skullsplitter ruins east of the Venture Co. mine. The headhunters, berserkers and hunters roam the ruins.\n{npc:1059} (45) carries the Broken Armor for {quest:586}: he walks the south-western ruins with two guards and sometimes stands in a small cave there. Pull the guards first.\nCareful: {npc:1060}, an elite troll (level 44), stands in the southern ruins around 47.7,44.3: pull the headhunters and berserkers away from him."] = "Езжайте на восток к руинам Череполомов к востоку от шахты Торговой компании. По руинам бродят охотники за головами, берсерки и охотники.\nУ NPC {npc:1059} (45) – сломанный доспех для задания «{quest:586}»: он ходит по юго-западным руинам с двумя стражами и иногда стоит в небольшой пещере там. Сначала выманите стражей.\nОсторожно: {npc:1060}, элитный тролль (44-й уровень), стоит в южных руинах около 47.7,44.3: оттаскивайте охотников за головами и берсерков подальше от него.",
		["Ride north-east to the goblin harbour on the coast."] = "Езжайте на северо-восток к гоблинской гавани на побережье.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Верховая езда и буреступы: {npc:265756}, ориентир: {area:17684} ({area:16638}), остров Зефрис.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; при обучении вы получаете транспорт. {npc:4752} обучает орков, ориентир: {object:172958}, у псарни ({npc:3362}). Небеснорожденные учатся у NPC {npc:265756} ({area:17684}, {area:16638}, остров Зефрис), вместе с буреногом: небесный корабль на остров отходит с утесов к югу от места {area:17045}, к северу от города {zone:1456}, примерно каждые пять минут. Другой транспорт вашей расы стоит по 20 золотых: в разделе «Коллекции», «Транспорт · 40-й уровень» есть гайд для каждого.",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents and in the rowboat beside the larger camp. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "К югу от Пиратской бухты висельники из шайки Кровавого Паруса стоят лагерем здесь: {area:43}; карты и приказы лежат в их палатках и в шлюпке рядом с большим лагерем. Нюхательный табак и глаз {npc:2493} может нести любой пират Кровавого Паруса: убивайте, пока не получите оба.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Тактическая карта лежит в лагере Древолапов к югу от Лагеря Мохаче.",
		["The {area:43}"] = "{area:43}",
		["Upstairs"] = "Наверху",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Волки: {npc:3362}, рядом: {npc:4752}.",
		["Woodpaw battle map"] = "Тактическая карта Древолапов",
		["Woodpaw north camp"] = "Северный лагерь Древолапов",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["Zul'Mamwe"] = "Зул'Мамбве",
		["for {zone:1454}, around level 45"] = "для города {zone:1454}, примерно на 45-м уровне",
		["the Rage Scar yetis, on the next visit to {zone:1444}"] = "йети Яростного Шрама – при следующем посещении края {zone:1444}",
		["the {object:2076}"] = "{object:2076}",
		["{area:392} for the Felsteed"] = "{area:392} – для коня Скверны",
		["{area:976} flight master"] = "Распорядитель полетов: {area:976}",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} – обнесенный стеной гоблинский город сразу за границей края {zone:1446}.",
		["{npc:3690}, riding trainer"] = "{npc:3690}, учитель верховой езды",
		["{npc:4752}, riding trainer"] = "{npc:4752}, учитель верховой езды",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}, later in this guide"] = "{npc:773}, наверху: для задания «{quest:2864}» ({area:976}), позже в этом гайде",
		["{npc:7953}, riding trainer"] = "{npc:7953}, учитель верховой езды",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: для города {zone:1454}, примерно на 45-м уровне",
		["{quest:2863}: one hour from now"] = "{quest:2863}: в течение часа",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "Назад на восток мимо места {area:75}: артефакты Атал'ай лежат в воде и на берегах (задание: {quest:1424}).",
		["Back to {npc:14637} on the dock."] = "Назад к NPC {npc:14637} на причале.",
		["Below ground"] = "Под землей",
		["Dragon caves"] = "Драконьи пещеры",
		["Fly to {area:1099}"] = "Летите сюда: {area:1099}",
		["Fly to {area:75}"] = "Летите сюда: {area:75}",
		["Frayfeather hippogryphs"] = "Блеклоперые гиппогрифы",
		["Level 45.37"] = "Уровень 45.37",
		["Murlocs of the Misty Reed"] = "Мурлоки Тростникового берега",
		["On the way back south-east from the coast, the Rage Scar yetis live around the caves in the hills by the road. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "На обратном пути от побережья на юго-восток, у пещер в холмах у дороги живут йети Бешеного оврага. С любого может также упасть {quest:7738} – это начинает отдельное задание.",
		["Onyxia's eggs"] = "Яйца Ониксии",
		["Rage Scar yetis"] = "Йети Бешеного оврага",
		["Ride back north to Brackenwall."] = "Возвращайтесь на север в Гиблотопь.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Езжайте на северо-запад сюда: {area:1108}; {npc:14637} ждет на причале.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Езжайте на запад по дороге; свиток лежит у кромки воды на дальнем западе болота.",
		["Riding at 40"] = "Верховая езда на 40-м уровне",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, a short ride north of the zeppelin towers, with {npc:4731}'s skeletal horses (20 gold each) beside her. Ride back to the towers for the {object:3202} zeppelin."] = "Верховая езда требует 40-го уровня и стоит 100 золотых; при обучении вы получаете ездовое животное. Каждая раса учится у учителя своей расы: ваш – {npc:4773} ({area:159}), недалеко к северу от башен дирижаблей, рядом кони-скелеты NPC {npc:4731} (по 20 золотых). Вернитесь к башням, чтобы сесть на дирижабль до места {object:3202}.",
		["Rogue Vale opens just north of {npc:14637}'s dock. Kill a {npc:5308}, use {item:10699} on its body before you loot it, then talk to the spirit that rises: it is friendly. Three spirits in all."] = "Разбойничья долина начинается чуть к северу от причала ({npc:14637}). Убейте {npc:5308}, используйте {item:10699} на его теле, прежде чем обыскать его, затем поговорите с поднявшимся духом: он дружелюбен. Всего три духа.",
		["Rogue Vale screechers"] = "Крикуны Разбойничьей долины",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Кони-скелеты: {npc:4731}, рядом с персонажем {npc:4773} ({area:159}).",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "К югу от долины на склонах гнездятся блеклоперые гиппогрифы; почти с каждого падают сухожилия и металлические осколки.",
		["Sprite darters and forest walkers"] = "Летучие хамелеоны и лесные древни",
		["Stays on the main route"] = "Остается на основном маршруте",
		["Takes you to level 47"] = "Доведет вас до 47-го уровня",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Яйца Ониксии лежат в драконьих пещерах на юго-востоке ({area:511}) под охраной чешуйчатых губителей; разбейте пять.",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Болотные мурлоки живут на берегу к югу от лагеря; чернильщики – вдоль берега к востоку, а трупоеды – дальше к западу, у хижин на западном берегу.",
		["The Sea Sprays (47-48) wash along the shore just south of the dock: they drop the Water Elemental Cores as well as the Sea Elementals (48-49) do. The Wave and Deep Striders (47-49) wade in the water off the same beach: zap them with {item:18904} first, and shrunken they lose their elite strength. Leave the Land Walkers and Cliff Giants (48-50) of the northern hills for your next {zone:1444} visit.\nThe Ultra-Shrinker lasts two hours: hand both quests back to {npc:14637} before you leave the coast."] = "Морские валы (47-48) плещутся у берега чуть к югу от причала: ядра элементаля воды падают с них так же, как с морских элементалей (48-49). Волновые странники и странники глубин (47-49) бродят в воде у того же пляжа: сначала примените на них {item:18904} – уменьшившись, они теряют силу элиты. Сухопутных бродяг и скальных великанов (48-50) на северных холмах оставьте до следующего визита в край {zone:1444}.\nУльтрасжиматель действует два часа: сдайте оба задания NPC {npc:14637}, прежде чем покинуть побережье.",
		["Then on to {zone:1446}"] = "Затем в зону {zone:1446}",
		["Three zones, lots of travel"] = "Три зоны, много перемещений",
		["To {area:75}"] = "В место {area:75}",
		["Underwater"] = "Под водой",
		["Zeppelin to {object:3202}"] = "Дирижабль: {object:3202}",
		["Zeppelin to {zone:1458}"] = "Дирижабль: {zone:1458}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "для персонажа {npc:5598} ({zone:1425}), примерно на 48-м уровне",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "для предмета {object:2555} ({zone:1445}), позже в этом руководстве",
		["for the {zone:1425} owlbeasts, around level 48"] = "для совухов ({zone:1425}), примерно на 48-м уровне",
		["{area:1099} flight master"] = "Распорядитель полетов: {area:1099}",
		["{item:18904}, on the Wave and Deep Striders in the water"] = "{item:18904} – на волновых странников и странников глубин в воде",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon instead."] = "Для вызова ({npc:4500}) в Гиблотопи нужна группа из трех человек. В одиночку убивайте огнегривых разведчиков здесь, на северном краю ({area:511}), до уровня 45.37, прежде чем ехать обратно на север, чтобы не возвращаться сюда ради этого. Или, если есть группа, пройдите вместо этого подземелье {area:978}.",
		["{npc:4773}, riding trainer"] = "{npc:4773}, учитель верховой езды",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, {object:36126}",
		["{quest:7738}, a rare drop"] = "{quest:7738}, редкая добыча",
		["{zone:1435} and Dustwallow first, then {zone:1444}."] = "Сначала {zone:1435} и Пылевые топи, затем {zone:1444}.",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Below ground"] = "Под землей",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["From {area:16727}, ride into the {zone:1427} by its eastern pass, then west to the dig site. The {object:173265} stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 {item:4306} (the Auction House sells it)."] = "Из места {area:16727} езжайте в край {zone:1427} через восточный перевал, затем на запад к раскопкам. {object:173265} стоит в южной части; геологи из клана Черного Железа копают чуть к северу. Принесите 15 шт.: {item:4306} (продается на аукционе).",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Для следующей просьбы нужен предмет {item:10552} с элитных культистов: не берите ее.",
		["OOX-17/TN"] = "КПХ-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Только с предметом {item:11818}: назад на восток к раскопкам ({object:173265}).",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "Езжайте на северо-запад через ущелье; {area:1446} – лагерь в лесах на северо-западе.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Кузнецы из клана Черного Железа работают у горнов в центре Котлована; у половины – {item:10551}, у каждого десятого – {item:18959}. Кинжалы есть также у рабов, поработителей и надсмотрщиков.",
		["The Steamsmiths' furnaces"] = "Горны кузнецов",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Доска: {object:179827}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "На запад по дороге на юг; {npc:7771} стоит лагерем у руин ({area:1938}). Наденьте его предмет {item:9978}: он показывает закопанные украшения – здесь и вокруг места {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "К западу от Прибамбасска используйте предмет {item:8584} у водопоя в лагере троллей.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} растет здесь: {zone:1425}, примерно на 48-м уровне",
		["the {object:173265}"] = "{object:173265}",
		["{area:1099} flight master"] = "Распорядитель полетов: {area:1099}",
		["{area:976} and the {zone:1427} at 46-48: the Wastewander camps, {npc:5955}'s escort and {area:1446}."] = "{area:976} и {zone:1427} на 46-48-м уровне: лагеря Скитальцев Пустыни, сопровождение NPC {npc:5955} и {area:1446}.",
		["{item:11818}, a rare drop"] = "{item:11818}, редкая добыча",
		["{item:8623}, a rare drop"] = "{item:8623}, редкая добыча",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} ждет в долине. Доведите его до жены ({npc:6015}, {area:977}) на северо-восток через пустыню: держитесь рядом, не спешите и отбивайтесь от нападающих. Не садитесь на транспорт и не используйте камень возвращения. {npc:8579} тоже стоит в порту.",
		["{npc:5955}'s escort"] = "Сопровождение: {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, рядом с распорядителем полетов",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Назад на запад сюда: {area:350}; следопыты и стрелки держатся у поселения, разведчики и гонцы – на склонах к югу.",
		["East of the village, the violet flower grows in the hills."] = "К востоку от деревни на холмах растет фиолетовый цветок.",
		["Fly to {area:272}"] = "Летите сюда: {area:272}",
		["Fly to {area:75}"] = "Летите сюда: {area:75}",
		["Highvale"] = "Высокодолье",
		["His next request, going on to the {area:355}, is for a group."] = "Его следующая просьба ({area:355}) – для группы.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "К северу вдоль берега на маленьком острове – корзинка для пикника ({npc:14731}); ее охраняет {npc:14748}.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Езжайте на запад до города дворфов Громового Молота ({area:348}) и оставьте послание у колодца в центре. В городе полно стражников Альянса: быстро зайдите, оставьте и уходите.",
		["Ride back north to the bloodmages."] = "Возвращайтесь на север к волшебникам крови.",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "Езжайте на северо-восток от места {area:272} во {zone:1425} и на восток по дороге; {npc:7801} стоит лагерем на холме к югу от эльфийского поселения ({area:350}).",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Езжайте на запад от места {area:75} и на юг через каньон в край {zone:1419}; два волшебника крови стоят у дороги сразу за входом.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "К югу от поселения тролли племени Сухокожих занимают свои деревни. Череп есть у каждого: собрав двадцать, используйте предмет {item:15002}, чтобы сделать пику с тролльими черепами, затем установите ее в деревне.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "Снова к юго-западу: изгнанник прячется у руин ({area:353}).",
		["The bloodmages"] = "Волшебники крови",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Ящики ({item:8684}) лежат у заброшенного лагеря Орды ({area:351}), среди слизней.",
		["The secret lies on the {area:307}, above the beach."] = "Секрет лежит здесь: {area:307}, над пляжем.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Следующие задания снова требуют те же части ради предмета с усилением и не дают опыта: не берите их.",
		["Underwater"] = "Под водой",
		["for {npc:6986} in {zone:1454}, around level 50"] = "для персонажа {npc:6986} ({zone:1454}), примерно на 50-м уровне",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "для персонажа {npc:7825} ({zone:1458}), примерно на 50-м уровне",
		["{area:1446} flight master"] = "Распорядитель полетов: {area:1446}",
		["{area:348} well"] = "Колодец: {area:348}",
		["{item:8704}, a rare drop"] = "{item:8704}, редкая добыча",
		["{npc:14731}'s lunch"] = "Обед: {npc:14731}",
		["{npc:14736} stands up on top of the inn, above {npc:14731}: go up, the arrow cannot tell the levels apart."] = "{npc:14736} стоит на крыше таверны, над NPC {npc:14731}: поднимитесь наверх, Стрелка не различает высоту.",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}, на вершине ({area:354})",
		["{npc:7801}'s camp"] = "Лагерь {npc:7801}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor: Stoley's shipment from {zone:1446}"] = "\"Морской Волк\" Маккинли, на верхнем этаже: груз Стоули из зоны {zone:1446}",
		["Back to {area:1099}"] = "Вернитесь: {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Вернитесь: {npc:11548}, у святилища; держитесь западнее стражи места {area:3137}.",
		["Back to {object:3202}"] = "Вернитесь: {object:3202}",
		["Below ground"] = "Под землей",
		["Fly to {area:1099}"] = "Летите сюда: {area:1099}",
		["Fly to {area:976}"] = "Летите сюда: {area:976}",
		["Fly to {object:3202}"] = "Летите: {object:3202}",
		["Frayfeather Hippogryphs"] = "Блеклоперые гиппогрифы",
		["Hippogryph nests"] = "Гнезда гиппогрифов",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Сохраните {quest:3444}: сундук {npc:7771} откроется при следующем визите.",
		["Pestlezugg's samples come from {zone:1449}."] = "Образцы Пестычинса — из зоны {zone:1449}.",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Езжайте на восток по дороге от Заставы Расщепленного Дерева. {npc:11548} ждет здесь: {area:1235}, чуть в стороне от дороги, в нескольких шагах к западу от места {area:3137} (Альянс): подходите с запада и держитесь подальше от часовых Азшары и Джарродена (элита).",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "Езжайте на юг по дороге к месту {area:1938}; {npc:7771} стоит лагерем рядом. Отсюда дорога на запад ведет вниз в {zone:1449}, где начинается следующий гайд.",
		["Sprite Darters"] = "Летучие хамелеоны",
		["The Droffers' shop is a few steps further into the Drag."] = "Лавка братьев Дрофферсов – чуть дальше на Волоке.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Призраки высокорожденных бродят по руинам чуть севернее святилища; сатиры из племени Халдарр стоят лагерем немного дальше на север.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Морские элементали и морские брызги плещутся вдоль берега вокруг причала.\nСухопутные бродяги и скальные великаны бродят по холмам к северу от причала. Сначала ударьте каждого предметом {item:18904}: уменьшенные, они больше не элита. С каждого уменьшенного великана падает осадок; используйте на его теле и сосуд для уменьшенных горных великанов.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Лесные дракончики порхают в лесу чуть западнее лагеря. Используйте сосуд на каждом убитом.",
		["The flight from {area:75} lands on {area:35}'s upper deck. {npc:7406} has his workshop on the upper ring of the bay."] = "Полет из места {area:75} заканчивается на верхней палубе ({area:35}). Мастерская ({npc:7406}) – на верхнем ярусе бухты.",
		["The flight lands at {area:117}; {npc:2497} stands by the {object:2076}."] = "Полет заканчивается здесь: {area:117}; {npc:2497} стоит у объекта {object:2076}.",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "Гнезда гиппогрифов — на холмах к югу, вокруг места {area:2522}; в каждом лежит яйцо для устройства {object:142071}.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Гиппогрифы гнездятся на холмах к юго-западу от лагеря. Убейте одного, затем используйте сосуд для уменьшенных гиппогрифов на его теле.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Древни бродят по лесным дорогам между лагерем и центром зоны {zone:1444}; их немного, так что ищите вдоль троп.",
		["The {object:142071}, in the middle of town"] = "{object:142071}, в центре города",
		["Wandering Forest Walkers"] = "Бродячие лесные древни",
		["Zeppelin to {zone:1454}"] = "Дирижабль: {zone:1454}",
		["{area:1099} flight master"] = "Распорядитель полетов: {area:1099}",
		["{npc:6986}, the Drag"] = "{npc:6986}, Волок",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}: медведи — в зоне {zone:1448}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, рядом с распорядителем ветрокрылов",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "Назад на северо-восток сюда: {area:251}.",
		["Below ground"] = "Под землей",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Идите вдоль скал на юг сюда: {quest:3821} – холм огров клана Огненного Чрева. Останки ({npc:9136}) лежат у подножия.",
		["Gorillas"] = "Гориллы",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Сохраните задание {quest:4147} ({npc:9118}) и письмо ({npc:8737}) для следующих руководств.",
		["Lar'korwi Mates"] = "Самки Лар'корви",
		["Out of the refuge"] = "Снаружи лагеря",
		["Power Crystals and soil"] = "Кристаллы силы и земля",
		["Scarlet forward camp"] = "Передовой лагерь Алого ордена",
		["Stegodons and ravasaurs"] = "Стегодоны и равазавры",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5405}: Scourgestones only drop while you wear it."] = "Возьмите {object:176092} из ящика рядом с Деррингтоном для задания {quest:5096} – выполните его на обратном пути. Наденьте {quest:5405}: камни Плети падают, только пока он надет.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Самки Лар'корви бродят по джунглям к северо-западу от {npc:9619}.",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "Кристаллы растут по всему кратеру, много – вокруг места {area:537}. Возьмите по несколько лишних каждого цвета для пилонов.",
		["The expedition's lost equipment lies in the south-west jungle."] = "Потерянное снаряжение экспедиции лежит в юго-западных джунглях.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "Из горы вы выйдете рядом с местом {area:252}, полным орков 55-57 уровня. Езжайте по дороге на восток вдоль северных скал к лагерю Орды ({area:251}).",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Плот лежит на берегу юго-восточного озера; небольшой рюкзак – в воде рядом.",
		["Underwater"] = "Под водой",
		["Upstairs"] = "Наверху",
		["Use the Mangled Journal to start it"] = "Используйте истрепанный дневник, чтобы начать задание",
		["{area:340} flight master"] = "Распорядитель полетов: {area:340}",
		["{area:340} is built into the cliffs on the {zone:1418}' west edge."] = "{area:340} – крепость в скалах у западного края ({zone:1418}).",
		["{item:11116}, a rare drop"] = "{item:11116}, редкая добыча",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, рядом с распорядителем полетов",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} стоит здесь: {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, Район Фармацевтов: склянки наполните позже ({zone:1447})",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, в глубине пещеры; под землей",
		["{npc:9618}, just outside"] = "{npc:9618}, сразу снаружи",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} стоит лагерем в юго-восточном углу кратера.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "Затем {npc:9623} просит предмет {item:10561} (профессия {skill:202}). Пропустите, если его у вас нет.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, робот на плато; под землей",
		["{npc:9998}, at the entrance"] = "{npc:9998}, у входа",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, у входа в лагерь",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} бродит по пещерам и штольням ({quest:3821}); если его нет, бейте огров у входов, пока он не вернется.",
		["{zone:1454} flight master"] = "Распорядитель полетов: {zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Под землей",
		["Class trainer"] = "Учитель классовых навыков",
		["Diseased Wolves"] = "Больные волки",
		["Druid trainer"] = "Учитель друидов",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "К востоку от Заставы Отравленной Крови – долина с кратерами, где бродят энтропические звери и ужасы. Убейте по два каждого, затем подойдите к каждому из трех кратеров с водой Скверны.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Езжайте по дороге на северо-запад. Юг места {area:1763}, вокруг оскверненного лунного колодца, занимают культисты, адепты, стражники Совета Теней и их гончие.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Он стоит лагерем у места {area:202}, к юго-востоку от места {area:200}.",
		["Inside"] = "Внутри",
		["Keep {quest:8465} for {zone:1452}."] = "Сохраните задание {quest:8465} для края {zone:1452}.",
		["Northern crater"] = "Северный кратер",
		["Ride north up the road again."] = "Снова езжайте на север по дороге.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Езжайте на юго-запад мимо фермы Фелстоунов и по дороге на запад обратно сюда: {area:152}.",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "Езжайте по дороге на юг через край {zone:1448} к святилищу.",
		["Ror stands at the far south end of {area:1761}."] = "Рор стоит в дальней южной части места {area:1761}.",
		["Scarlet forward camp"] = "Передовой лагерь Алого ордена",
		["Southern crater"] = "Южный кратер",
		["Southern {area:1763}"] = "Юг: {area:1763}",
		["The Horde camp just north of {area:1763}."] = "Лагерь Орды чуть к северу от места {area:1763}.",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Дневник лежит в доме, шкаф стоит внутри, а уборная – за домом. Ключ от уборной у монстра {npc:10816}; {npc:10836} выходит, когда вы открываете уборную, – у него ключ от шкафа.",
		["The druids' camp is just past the border."] = "Лагерь друидов – сразу за границей.",
