t.guides["forever/professions/herbalism"] = (function() return {
		["Artisan {skill:182}"] = "{skill:182}: Искусник",
		["Artisan {skill:182} raises the cap to 300; it needs skill 200 and no character level, and costs 5g: train it as soon as you reach 200. The arrow picks the nearest {skill:182} trainer of your faction."] = "{skill:182}, ранг «Искусник»: предел 300; нужен навык 200, уровень персонажа не важен, стоит 5 з: обучитесь, как только достигнете 200. Стрелка ведет к ближайшему учителю вашей фракции ({skill:182}).",
		["Expert {skill:182}"] = "{skill:182}: Умелец",
		["Expert {skill:182} raises the cap to 225; it needs skill 125 and no character level, and costs 50s: train it as soon as you reach 125. The arrow picks the nearest {skill:182} trainer of your faction."] = "{skill:182}, ранг «Умелец»: предел 225; нужен навык 125, уровень персонажа не важен, стоит 50 с: обучитесь, как только достигнете 125. Стрелка ведет к ближайшему учителю вашей фракции ({skill:182}).",
		["Journeyman {skill:182}"] = "{skill:182}: Подмастерье",
		["Learn {skill:182}"] = "Изучите: {skill:182}",
		["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-15. Expect about 60 herbs for these 49 points."] = "Собирайте по пути: {item:2447} (1, оранжевый), {item:765} (1, оранжевый), {item:2449} (с 15) – и обходите точки маршрута, пока {skill:182} не достигнет 50. Уровень зоны: 1-15. На эти 49 очков уйдет около 60 трав.",
		["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "Собирайте по пути: {item:2447} (1, желтый), {item:765} (1, желтый), {item:2449} (15, желтый), {item:785} (50, оранжевый), {item:2450} (с 70) – и обходите точки маршрута, пока {skill:182} не достигнет 100. Иногда {item:785} и {item:2450} дают еще и {item:2452}. Уровень зоны: 10-20. На эти 50 очков уйдет около 140 трав.",
		["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 130 herbs for these 50 points."] = "Собирайте по пути: {item:2447} (1, желтый), {item:765} (1, желтый), {item:2449} (15, желтый), {item:785} (50, оранжевый), {item:2450} (с 70), {item:3820} (с 85) – и обходите точки маршрута, пока {skill:182} не достигнет 100. Иногда {item:785} и {item:2450} дают еще и {item:2452}. {item:3820} растет под водой вдоль берега: следите за дыханием. Уровень зоны: 10-20. На эти 50 очков уйдет около 130 трав.",
		["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70), {item:3820} (from 85) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. {item:3820} grows underwater along the shore: watch your breath. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "Собирайте по пути: {item:2447} (1, желтый), {item:765} (1, желтый), {item:2449} (15, желтый), {item:785} (50, оранжевый), {item:2450} (с 70), {item:3820} (с 85) – и обходите точки маршрута, пока {skill:182} не достигнет 100. Иногда {item:785} и {item:2450} дают еще и {item:2452}. {item:3820} растет под водой вдоль берега: следите за дыханием. Уровень зоны: 10-20. На эти 50 очков уйдет около 140 трав.",
		["Pick every {item:2449} (15, green), {item:785} (50, green), {item:2450} (70, yellow), {item:2453} (100, orange) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 15-25. Expect about 60 herbs for these 25 points."] = "Собирайте по пути: {item:2449} (15, зеленый), {item:785} (50, зеленый), {item:2450} (70, желтый), {item:2453} (100, оранжевый) – и обходите точки маршрута, пока {skill:182} не достигнет 125. Иногда {item:785} и {item:2450} дают еще и {item:2452}. Уровень зоны: 15-25. На эти 25 очков уйдет около 60 трав.",
		["Pick every {item:3820} (85, green), {item:3356} (125, yellow), {item:3357} (150, orange), {item:3818} (160, orange), {item:3821} (from 170) you pass and circle the waypoints until {skill:182} 185. {item:3820} grows underwater along the shore: watch your breath. Zone level 35-45. Expect about 40 herbs for these 25 points."] = "Собирайте по пути: {item:3820} (85, зеленый), {item:3356} (125, желтый), {item:3357} (150, оранжевый), {item:3818} (160, оранжевый), {item:3821} (с 170) – и обходите точки маршрута, пока {skill:182} не достигнет 185. {item:3820} растет под водой вдоль берега: следите за дыханием. Уровень зоны: 35-45. На эти 25 очков уйдет около 40 трав.",
		["Pick every {item:785} (50, green), {item:2450} (70, yellow), {item:2453} (100, orange), {object:1623} (from 115) you pass and circle the waypoints until {skill:182} 125. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 15-27. Expect about 40 herbs for these 25 points."] = "Собирайте по пути: {item:785} (50, зеленый), {item:2450} (70, желтый), {item:2453} (100, оранжевый), {object:1623} (с 115) – и обходите точки маршрута, пока {skill:182} не достигнет 125. Иногда {item:785} и {item:2450} дают еще и {item:2452}. Уровень зоны: 15-27. На эти 25 очков уйдет около 40 трав.",
		["Pick every {object:1623} (115, green, rare), {item:3357} (150, green), {item:3818} (160, green, rare), {item:3821} (170, yellow), {object:2043} (185, yellow), {item:8831} (210, orange) you pass and circle the waypoints until {skill:182} 230. {item:8831} sometimes gives a {item:8153} as well. Zone level 40-50. Expect about 30 herbs for these 20 points."] = "Собирайте по пути: {object:1623} (115, зеленый, редкий), {item:3357} (150, зеленый), {item:3818} (160, зеленый, редкий), {item:3821} (170, желтый), {object:2043} (185, желтый), {item:8831} (210, оранжевый) – и обходите точки маршрута, пока {skill:182} не достигнет 230. Иногда {item:8831} дает еще и {item:8153}. Уровень зоны: 40-50. На эти 20 очков уйдет около 30 трав.",
		["Pick every {object:1623} (115, green, rare), {item:3357} (150, green), {item:3821} (170, yellow), {object:2043} (185, orange) you pass and circle the waypoints until {skill:182} 210. Zone level 40-50. Expect about 20 herbs for these 10 points."] = "Собирайте по пути: {object:1623} (115, зеленый, редкий), {item:3357} (150, зеленый), {item:3821} (170, желтый), {object:2043} (185, оранжевый) – и обходите точки маршрута, пока {skill:182} не достигнет 210. Уровень зоны: 40-50. На эти 10 очков уйдет около 20 трав.",
		["Pick every {object:1623} (115, green, rare), {item:3357} (150, yellow), {item:3821} (170, orange), {object:2043} (185, orange) you pass and circle the waypoints until {skill:182} 200. Zone level 40-50. Expect about 20 herbs for these 15 points."] = "Собирайте по пути: {object:1623} (115, зеленый, редкий), {item:3357} (150, желтый), {item:3821} (170, оранжевый), {object:2043} (185, оранжевый) – и обходите точки маршрута, пока {skill:182} не достигнет 200. Уровень зоны: 40-50. На эти 15 очков уйдет около 20 трав.",
